    // ---------------------------------------------------------------------------------------------
    // In-app notices: themed, RTL, colour-coded replacement for system Toasts. They sit above the
    // dock, can be tapped away, are announced to TalkBack and fall back to a Toast off-screen.
    // ---------------------------------------------------------------------------------------------
    private View currentNotice;

    private int noticeTone(String msg) {
        String m = msg == null ? "" : msg;
        String[] danger = {"خطا", "نشد", "ناموفق", "نامعتبر", "ممکن نیست", "مجاز نیست", "عدم اتصال", "قطع", "رد شد", "failed", "Error"};
        for (String k : danger) if (m.contains(k)) return DANGER;
        String[] success = {"ثبت شد", "ذخیره شد", "اعمال شد", "ارسال شد", "اضافه شد", "حذف شد", "کپی شد", "ساخته شد", "انجام شد", "فعال شد", "به‌روز شد", "بروز شد", "تأیید شد", "تایید شد", "✓"};
        for (String k : success) if (m.contains(k)) return SUCCESS;
        String[] warn = {"ابتدا", "لطفاً", "لطفا", "الزامی", "کند", "آفلاین", "محلی", "بیشتر از", "کمتر از", "فقط"};
        for (String k : warn) if (m.contains(k)) return WARNING;
        return INFO;
    }

    private void showNotice(CharSequence message, boolean longDuration) { showNotice(message, longDuration, null, null); }

    private void showNotice(CharSequence message, boolean longDuration, String actionLabel, Runnable action) {
        final String msg = message == null ? "" : message.toString().trim();
        if (msg.isEmpty()) return;
        if (Looper.myLooper() != Looper.getMainLooper()) { runOnUiThread(() -> showNotice(msg, longDuration, actionLabel, action)); return; }
        ViewGroup host = null;
        try { host = (ViewGroup) findViewById(android.R.id.content); } catch (Exception ignored) { }
        if (host == null || isFinishing() || !host.isAttachedToWindow() || !hasWindowFocus()) {
            Toast.makeText(this, msg, longDuration ? Toast.LENGTH_LONG : Toast.LENGTH_SHORT).show();
            return;
        }
        if (currentNotice != null && currentNotice.getParent() instanceof ViewGroup) ((ViewGroup) currentNotice.getParent()).removeView(currentNotice);
        int tone = noticeTone(msg);
        LinearLayout pill = new LinearLayout(this);
        pill.setOrientation(LinearLayout.HORIZONTAL);
        pill.setGravity(Gravity.CENTER_VERTICAL);
        pill.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);
        pill.setPadding(dp(12), dp(10), dp(14), dp(10));
        GradientDrawable bg = rounded(isLightTheme() ? mix(SURFACE, tone, 0.06f) : mix(SURFACE_2, tone, 0.14f), 20);
        bg.setStroke(dp(1), alpha(tone, isLightTheme() ? 90 : 120));
        pill.setBackground(bg);
        pill.setElevation(dp(12));
        pill.setClickable(true);
        pill.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);
        TextView icon = text(tone == SUCCESS ? "✓" : (tone == DANGER ? "!" : (tone == WARNING ? "!" : "i")), 14f, onColorFor(tone), Typeface.BOLD);
        icon.setGravity(Gravity.CENTER);
        icon.setIncludeFontPadding(false);
        icon.setBackground(rounded(tone, 999));
        pill.addView(icon, new LinearLayout.LayoutParams(dp(28), dp(28)));
        TextView body = text(msg, 13.2f, TEXT, Typeface.BOLD);
        body.setMaxLines(4);
        body.setEllipsize(TextUtils.TruncateAt.END);
        body.setLineSpacing(dp(2), 1f);
        LinearLayout.LayoutParams blp = new LinearLayout.LayoutParams(0, -2, 1f);
        blp.setMargins(dp(10), 0, 0, 0);
        pill.addView(body, blp);
        TextView actionView = null;
        if (actionLabel != null && action != null) {
            actionView = text(actionLabel, 13f, tc(GOLD), Typeface.BOLD);
            actionView.setGravity(Gravity.CENTER);
            actionView.setPadding(dp(12), 0, dp(12), 0);
            actionView.setMinHeight(dp(44));
            actionView.setBackground(rounded(alpha(GOLD, isLightTheme() ? 26 : 46), 12));
            LinearLayout.LayoutParams alp = new LinearLayout.LayoutParams(-2, dp(44));
            alp.setMargins(dp(8), 0, 0, 0);
            pill.addView(actionView, alp);
        }
        boolean dockVisible = session != null && navStrip != null && navStrip.isShown();
        FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(-1, -2, Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL);
        lp.setMargins(dp(18), 0, dp(18), systemInsetBottom + (dockVisible ? dp(VISITOR_EDITION ? 122 : 112) : dp(24)));
        host.addView(pill, lp);
        currentNotice = pill;
        final View shown = pill;
        Runnable dismiss = () -> {
            if (shown.getParent() == null) return;
            shown.animate().alpha(0f).translationY(dp(10)).setDuration(170).withEndAction(() -> {
                if (shown.getParent() instanceof ViewGroup) ((ViewGroup) shown.getParent()).removeView(shown);
                if (currentNotice == shown) currentNotice = null;
            }).start();
        };
        pill.setOnClickListener(v -> dismiss.run());
        if (actionView != null) actionView.setOnClickListener(v -> { dismiss.run(); try { action.run(); } catch (Exception ignored) { } });
        if (motionAllowed()) {
            pill.setAlpha(0f);
            pill.setTranslationY(dp(18));
            pill.animate().alpha(1f).translationY(0f).setDuration(210).start();
        }
        pill.announceForAccessibility(msg);
        pill.postDelayed(dismiss, actionView != null ? 6000 : (longDuration ? 4200 : 2600));
    }

    private void haptic(View v, boolean confirm) {
        if (v == null) return;
        try {
            int type = Build.VERSION.SDK_INT >= 30 && confirm ? HapticFeedbackConstants.CONFIRM : HapticFeedbackConstants.KEYBOARD_TAP;
            v.performHapticFeedback(type);
        } catch (Exception ignored) { }
    }

    private String appVersionName() {
        // Show a clean number to users ("5.0.0"), without build tags such as "-debug".
        try { String v = getPackageManager().getPackageInfo(getPackageName(), 0).versionName; return v == null ? "" : v.split("-")[0]; }
        catch (Exception ignored) { return ""; }
    }

    private static String hidden(int[] data) {
        char[] out = new char[data.length];
        for (int i = 0; i < data.length; i++) out[i] = (char) (data[i] ^ S_KEY);
        return new String(out);
    }

    /**
     * Readable type scale. Much of the UI was tuned with 8–10.5sp captions, which are hard to read
     * with Vazirmatn outdoors. Sizes under 12sp are lifted toward 12sp while keeping hierarchy
     * (8.4→10, 9.2→10.5, 10.5→11.2). "Compact UI" keeps a denser but still legible scale.
     */
    private float fs(float size) {
        if (size <= 1.5f || size >= 12f) return size;
        boolean compact = prefs != null && prefs.getBoolean(KEY_COMPACT_UI, false);
        // Small captions are lifted toward 12sp so nothing on screen is too tiny to read outdoors.
        float lifted = size + (12f - size) * (compact ? 0.3f : 0.5f);
        return Math.max(lifted, compact ? 9.5f : 10.5f);
    }

    private int dp(float value) {
        return (int) (value * getResources().getDisplayMetrics().density + 0.5f);
    }

    /**
     * Loads the Meelano Persian typeface (Vazirmatn, SIL OFL) once from assets/fonts.
     * Falls back to the system default typeface if the asset is missing or fails to
     * parse, so a packaging problem can never crash the app or block login.
     */
    private void loadMeelanoFonts() {
        try {
            MEELANO_REGULAR = Typeface.createFromAsset(getAssets(), "fonts/Vazirmatn-Regular.ttf");
        } catch (Exception ignored) { MEELANO_REGULAR = Typeface.DEFAULT; }
        try {
            MEELANO_BOLD = Typeface.createFromAsset(getAssets(), "fonts/Vazirmatn-Bold.ttf");
        } catch (Exception ignored) { MEELANO_BOLD = Typeface.DEFAULT_BOLD; }
    }

    /**
     * Resolves the correct Meelano font face for a given Typeface style flag
     * (NORMAL/BOLD/ITALIC/BOLD_ITALIC), using the real bold weight instead of a
     * synthetic (faux) bold whenever possible.
     */
    private Typeface faceFor(int style) {
        boolean bold = (style & Typeface.BOLD) != 0;
        boolean italic = (style & Typeface.ITALIC) != 0;
        Typeface base = bold ? MEELANO_BOLD : MEELANO_REGULAR;
        return italic ? Typeface.create(base, Typeface.ITALIC) : base;
    }

    private boolean compactUi() {
        if (prefs != null && prefs.getBoolean(KEY_COMPACT_UI, false)) return true;
        try {
            float widthDp = screenWidthDp();
            return widthDp > 0 && widthDp < 370;
        } catch (Exception ignored) { return false; }
    }

    private float screenWidthDp() {
        try { return getResources().getDisplayMetrics().widthPixels / getResources().getDisplayMetrics().density; }
        catch (Exception ignored) { return 390f; }
    }

    private float visitorDockScale() {
        float w = screenWidthDp();
        if (w <= 0) return 1f;
        if (w < 350) return 0.82f;
        if (w < 370) return 0.88f;
        if (w < 395) return 0.94f;
        if (w > 460) return 1.06f;
        return 1f;
    }

    private boolean isLightTheme() {
        return Color.red(NAVY) + Color.green(NAVY) + Color.blue(NAVY) > 520;
    }

    private void prepareVisitorEditionDefaults() {
        if (prefs == null) return;
        String savedTheme = prefs.getString(KEY_THEME, "");
        SharedPreferences.Editor ed = prefs.edit();
        if (savedTheme == null || savedTheme.trim().isEmpty() || (VISITOR_EDITION && "onyx_gold".equals(savedTheme))) ed.putString(KEY_THEME, STORE_EDITION ? "emerald_silk" : "azure_diamond");
        ed.putBoolean(KEY_QUICK_LOGIN_ENABLED, false)
                .remove(KEY_QUICK_PIN)
                .remove(KEY_QUICK_USER_ID)
                .remove(KEY_QUICK_VISITOR_ID)
                .remove(KEY_QUICK_USER_NAME)
                .remove(KEY_QUICK_ROLE)
                .remove(KEY_QUICK_PERMISSIONS)
                .apply();
    }

    private boolean isLightThemeId(String id) {
        String v = id == null ? "" : id.trim();
        return "azure_diamond".equals(v) || "crystal_lagoon".equals(v) || "ivory_sunrise".equals(v) ||
                "pearl_platinum".equals(v) || "rose_quartz_lux".equals(v) || "emerald_silk".equals(v) || "hazelnut_gold".equals(v);
    }

    private boolean motionAllowedCache = true;
    private long motionAllowedCheckedAt = 0L;

    /** Cached: this is queried from onDraw(), so avoid a prefs read + system call on every frame. */
    private boolean motionAllowed() {
        long now = System.currentTimeMillis();
        if (motionAllowedCheckedAt != 0L && now - motionAllowedCheckedAt < 4000L) return motionAllowedCache;
        motionAllowedCheckedAt = now;
        motionAllowedCache = computeMotionAllowed();
        return motionAllowedCache;
    }

    private boolean computeMotionAllowed() {
        if (prefs != null && prefs.getBoolean(KEY_REDUCED_MOTION, false)) return false;
        try {
            // Accessibility → "Remove animations" sets the animator scale to 0.
            if (Settings.Global.getFloat(getContentResolver(), Settings.Global.ANIMATOR_DURATION_SCALE, 1f) == 0f) return false;
        } catch (Exception ignored) { }
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                PowerManager pm = (PowerManager) getSystemService(Context.POWER_SERVICE);
                if (pm != null && pm.isPowerSaveMode()) return false;
            }
        } catch (Exception ignored) { }
        return true;
    }

    private void initNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            try {
                NotificationChannel ch = new NotificationChannel(NOTIFY_CHANNEL, "هشدارهای مدیریتی Meelano", NotificationManager.IMPORTANCE_DEFAULT);
                ch.setDescription("یادآوری چک‌ها، مطالبات و هشدارهای مهم داشبورد");
                NotificationManager nm = (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
                if (nm != null) nm.createNotificationChannel(ch);
            } catch (Exception ignored) { }
        }
    }

    private void requestNotificationPermissionIfNeeded() {
        try {
            if (Build.VERSION.SDK_INT >= 33 && checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) {
                requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS}, 9134);
            }
        } catch (Exception ignored) { }
    }

    private String normalizeThemeId(String themeId) {
        String id = themeId == null ? DEFAULT_THEME : themeId.trim();
        if (id.isEmpty()) return DEFAULT_THEME;
        if ("pearl_platinum".equals(id) || "rose_quartz_lux".equals(id) || "emerald_silk".equals(id) ||
                "royal_amethyst".equals(id) || "ivory_sunrise".equals(id) || "crystal_lagoon".equals(id) || "azure_diamond".equals(id) || "noir_aurora".equals(id) || "onyx_gold".equals(id) || "hazelnut_gold".equals(id) || THEME_AUTO.equals(id)) return id;
        return DEFAULT_THEME;
    }

    private static final String THEME_AUTO = "auto_system";

    private boolean systemDarkMode() {
        try { return (getResources().getConfiguration().uiMode & Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES; }
        catch (Exception ignored) { return false; }
    }

    /** Follow-system theme: light Azure Diamond by day, Noir Aurora when the phone is in dark mode. */
    private String resolveThemeId(String themeId) {
        String id = normalizeThemeId(themeId);
        return THEME_AUTO.equals(id) ? (systemDarkMode() ? "noir_aurora" : "azure_diamond") : id;
    }

    private boolean lastAppliedDark = false;

    @Override
    public void onConfigurationChanged(Configuration newConfig) {
        super.onConfigurationChanged(newConfig);
        boolean dark = (newConfig.uiMode & Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES;
        if (THEME_AUTO.equals(currentThemeId()) && dark != lastAppliedDark) {
            applyTheme(THEME_AUTO);
            rebuildUiAfterThemeChange();
        }
    }

