    /**
     * Draws the app edge-to-edge (enforced on Android 15 for targetSdk 35) and colours the system
     * bar icons so they stay visible on light themes. Previously light themes painted a near-white
     * status bar with white icons, and on Android 15 the header slid under the status bar.
     */
    private void applySystemBarStyle() {
        Window w = getWindow();
        if (w == null) return;
        try {
            View decor = w.getDecorView();
            boolean light = isLightTheme();
            if (Build.VERSION.SDK_INT >= 30) {
                w.setDecorFitsSystemWindows(false);
                w.setStatusBarColor(Color.TRANSPARENT);
                w.setNavigationBarColor(Color.TRANSPARENT);
                WindowInsetsController c = w.getInsetsController();
                if (c != null) {
                    int mask = WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS | WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS;
                    c.setSystemBarsAppearance(light ? mask : 0, mask);
                }
            } else {
                int flags = View.SYSTEM_UI_FLAG_LAYOUT_STABLE | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION;
                if (Build.VERSION.SDK_INT >= 23) {
                    w.setStatusBarColor(Color.TRANSPARENT);
                    if (light) flags |= View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR;
                } else {
                    w.setStatusBarColor(light ? alpha(Color.BLACK, 70) : Color.TRANSPARENT);
                }
                if (Build.VERSION.SDK_INT >= 29) {
                    w.setNavigationBarColor(Color.TRANSPARENT);
                    if (light) flags |= View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;
                } else if (Build.VERSION.SDK_INT >= 26) {
                    w.setNavigationBarColor(alpha(NAVY, 238));
                    if (light) flags |= View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;
                } else {
                    w.setNavigationBarColor(light ? Color.rgb(24, 30, 42) : NAVY);
                }
                decor.setSystemUiVisibility(flags);
            }
        } catch (Exception ignored) { }
    }

    private int systemInsetTop = 0;
    private int systemInsetBottom = 0;

    /** Pads the header below the status bar and keeps content/dock above the nav bar and keyboard. */
    private void installWindowInsets(LinearLayout root, LinearLayout headerWrap, int headerBaseHeight) {
        root.setOnApplyWindowInsetsListener((v, insets) -> {
            int top, bottom, left, right;
            boolean imeVisible;
            if (Build.VERSION.SDK_INT >= 30) {
                android.graphics.Insets bars = insets.getInsets(WindowInsets.Type.systemBars() | WindowInsets.Type.displayCutout());
                android.graphics.Insets ime = insets.getInsets(WindowInsets.Type.ime());
                top = bars.top; bottom = Math.max(bars.bottom, ime.bottom); left = bars.left; right = bars.right;
                imeVisible = ime.bottom > bars.bottom;
            } else {
                top = insets.getSystemWindowInsetTop(); bottom = insets.getSystemWindowInsetBottom();
                left = insets.getSystemWindowInsetLeft(); right = insets.getSystemWindowInsetRight();
                imeVisible = bottom > dp(160);
            }
            // B9: while the keyboard is open the dock is hidden so search results get the whole screen.
            if (navStrip != null) {
                if (imeVisible && navStrip.getVisibility() == View.VISIBLE) { navStrip.setVisibility(View.GONE); dockHiddenByKeyboard = true; }
                else if (!imeVisible && dockHiddenByKeyboard) { navStrip.setVisibility(View.VISIBLE); dockHiddenByKeyboard = false; }
            }
            systemInsetTop = top;
            systemInsetBottom = bottom;
            headerWrap.setPadding(dp(8), dp(8) + top, dp(8), dp(8));
            ViewGroup.LayoutParams lp = headerWrap.getLayoutParams();
            if (lp != null && lp.height != headerBaseHeight + top) { lp.height = headerBaseHeight + top; headerWrap.setLayoutParams(lp); }
            v.setPadding(left, 0, right, bottom);
            return insets;
        });
        root.requestApplyInsets();
    }

    private String currentThemeId() {
        return normalizeThemeId(prefs == null ? DEFAULT_THEME : prefs.getString(KEY_THEME, DEFAULT_THEME));
    }

    private String themeName(String id) {
        if ("pearl_platinum".equals(id)) return "مروارید پلاتینیوم";
        if ("rose_quartz_lux".equals(id)) return "رز کوارتز لاکچری";
        if ("emerald_silk".equals(id)) return "زمرد ابریشمی روشن";
        if ("royal_amethyst".equals(id)) return "شب آمتیست سلطنتی";
        if ("ivory_sunrise".equals(id)) return "طلوع عاجی لوکس";
        if ("crystal_lagoon".equals(id)) return "لاگون کریستالی روشن";
        if ("hazelnut_gold".equals(id)) return "فندقی طلایی";
        if ("azure_diamond".equals(id)) return "الماس آبی روشن";
        if ("noir_aurora".equals(id)) return "نوآر شفق لوکس";
        if ("onyx_gold".equals(id)) return "اونیکس طلایی Meelano";
        if (THEME_AUTO.equals(id)) return "خودکار (هماهنگ با حالت روز/شب گوشی)";
        return "الماس آبی روشن";
    }

    private final Map<Integer, Integer> readableColorCache = new HashMap<>();

    private static double relativeLuminance(int color) {
        double[] c = {Color.red(color) / 255d, Color.green(color) / 255d, Color.blue(color) / 255d};
        for (int i = 0; i < 3; i++) c[i] = c[i] <= 0.03928 ? c[i] / 12.92 : Math.pow((c[i] + 0.055) / 1.055, 2.4);
        return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
    }

    private static double contrastRatio(int a, int b) {
        double la = relativeLuminance(a), lb = relativeLuminance(b);
        return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
    }

    /**
     * Text-safe version of an accent colour: keeps the hue but moves it towards TEXT until it
     * reaches WCAG AA (4.5:1) on both SURFACE and SURFACE_2. Light themes used accents such as
     * GOLD_2 at ~2:1 for amounts and titles, which is unreadable in sunlight. Dark themes already
     * pass, so they are returned unchanged. Only for text drawn on the page surface, never for
     * text on a filled accent background (those use onColorFor()).
     */
    private int tc(int color) {
        Integer cached = readableColorCache.get(color);
        if (cached != null) return cached;
        int a = Color.alpha(color);
        int opaque = Color.rgb(Color.red(color), Color.green(color), Color.blue(color));
        int out = opaque;
        int textOpaque = Color.rgb(Color.red(TEXT), Color.green(TEXT), Color.blue(TEXT));
        for (int i = 1; i <= 20 && Math.min(contrastRatio(out, SURFACE), contrastRatio(out, SURFACE_2)) < 4.5; i++) {
            out = mix(opaque, textOpaque, i * 0.05f);
        }
        int result = Color.argb(a, Color.red(out), Color.green(out), Color.blue(out));
        readableColorCache.put(color, result);
        return result;
    }

    private int alpha(int color, int amount) {
        return Color.argb(amount, Color.red(color), Color.green(color), Color.blue(color));
    }

    private int mix(int from, int to, float ratio) {
        float r = Math.max(0f, Math.min(1f, ratio));
        return Color.rgb(
                Math.round(Color.red(from) + (Color.red(to) - Color.red(from)) * r),
                Math.round(Color.green(from) + (Color.green(to) - Color.green(from)) * r),
                Math.round(Color.blue(from) + (Color.blue(to) - Color.blue(from)) * r));
    }

    private int onColorFor(int color) {
        int score = Color.red(color) * 299 + Color.green(color) * 587 + Color.blue(color) * 114;
        return score > 156000 ? Color.rgb(18, 23, 34) : Color.WHITE;
    }

    private int themeAccent(String key) {
        String k = key == null ? "" : key.toLowerCase(Locale.US);
        if (k.contains("danger") || k.contains("خطا") || k.contains("حذف") || k.contains("دزدگیر")) return DANGER;
        return GOLD;
    }

    private GradientDrawable premiumPanel(int accent, float radius) {
        int softAccent = mix(accent, GOLD_2, isLightTheme() ? 0.16f : 0.20f);
        int top = isLightTheme() ? mix(SURFACE, softAccent, 0.04f) : mix(SURFACE, softAccent, 0.10f);
        int mid = isLightTheme() ? mix(SURFACE_2, softAccent, 0.08f) : mix(SURFACE_2, softAccent, 0.16f);
        int bottom = isLightTheme() ? mix(NAVY, softAccent, 0.025f) : mix(NAVY, softAccent, 0.12f);
        GradientDrawable d = gradient(new int[]{alpha(top, 252), alpha(mid, 248), alpha(bottom, 252)}, GradientDrawable.Orientation.TL_BR, radius);
        d.setStroke(dp(1), alpha(mix(softAccent, Color.WHITE, isLightTheme() ? 0.38f : 0.24f), isLightTheme() ? 116 : 92));
        return d;
    }

    /** Flat icon/badge container: solid colour (primary) or soft tint (secondary). No gradients, strokes or glow. */
    private GradientDrawable luxuryButtonBg(int accent, boolean primary, float radius) {
        return rounded(primary ? accent : alpha(accent, isLightTheme() ? 30 : 52), Math.min(radius, 999));
    }

    private void applyTouchFeedback(View v) {
        if (v == null) return;
        v.setOnTouchListener((view, event) -> {
            if (!motionAllowed() || event == null) return false;
            if (event.getAction() == MotionEvent.ACTION_DOWN) {
                view.animate().scaleX(0.975f).scaleY(0.975f).alpha(0.94f).setDuration(90).start();
            } else if (event.getAction() == MotionEvent.ACTION_UP || event.getAction() == MotionEvent.ACTION_CANCEL) {
                view.animate().scaleX(1f).scaleY(1f).alpha(1f).setDuration(130).start();
            }
            return false;
        });
    }

    private String navGlyph(String key) {
        return MeelanoDesignKit.glyph(key);
    }

    private String semanticGlyph(String label) {
        String t = label == null ? "" : label;
        if (t.contains("تماس")) return "☎";
        if (t.contains("پیام") || t.contains("گفتگو")) return "✉";
        if (t.contains("گردش") || t.contains("حساب")) return "☷";
        if (t.contains("CSV")) return "CSV";
        if (t.contains("PDF")) return "PDF";
        if (t.contains("تازه") || t.contains("بروزرسان")) return "⟳";
        if (t.contains("تم")) return "✺";
        if (t.contains("مودیان") || t.contains("مالیات")) return "٪";
        if (t.contains("دوربین") || t.contains("DVR")) return "▣";
        if (t.contains("دزدگیر") || t.contains("امنیت")) return "◬";
        if (t.contains("مرخصی")) return "☘";
        if (t.contains("ورود")) return "↘";
        if (t.contains("خروج")) return "↗";
        if (t.contains("جستجو")) return "⌕";
        if (t.contains("فروش")) return "↗";
        if (t.contains("خرید")) return "↙";
        if (t.contains("چک")) return "✓";
        if (t.contains("کالا")) return "◍";
        if (t.contains("مشتری")) return "♙";
        return "◆";
    }

    private String withIcon(String glyph, String label) {
        String g = glyph == null ? "" : glyph.trim();
        String l = label == null ? "" : label.trim();
        return g.isEmpty() ? l : g + "  " + l;
    }

    private TextView pill(String label, int accent, boolean filled) {
        TextView chip = text(label, 9.6f, filled ? onColorFor(accent) : accent, Typeface.BOLD);
        chip.setGravity(Gravity.CENTER);
        chip.setSingleLine(true);
        chip.setPadding(dp(10), dp(5), dp(10), dp(5));
        chip.setTextColor(filled ? onColorFor(accent) : tc(accent));
        chip.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG_RTL);
        chip.setBackground(rounded(filled ? accent : alpha(accent, isLightTheme() ? 26 : 44), 999));
        return chip;
    }

    private void styleMeelanoDialog(AlertDialog dialog, int accent) {
        if (dialog == null) return;
        final Runnable styler = () -> {
            try {
                if (dialog.getWindow() != null) dialog.getWindow().setBackgroundDrawable(premiumPanel(accent, 30));
                Button pos = dialog.getButton(AlertDialog.BUTTON_POSITIVE);
                Button neg = dialog.getButton(AlertDialog.BUTTON_NEGATIVE);
                Button neu = dialog.getButton(AlertDialog.BUTTON_NEUTRAL);
                if (pos != null) { pos.setTextColor(tc(accent)); pos.setAllCaps(false); pos.setTypeface(MEELANO_BOLD); applyTouchFeedback(pos); }
                if (neg != null) { neg.setTextColor(MUTED); neg.setAllCaps(false); applyTouchFeedback(neg); }
                if (neu != null) { neu.setTextColor(tc(accent)); neu.setAllCaps(false); neu.setTypeface(MEELANO_BOLD); applyTouchFeedback(neu); }
                if (neg != null) neg.setTypeface(MEELANO_BOLD);
            } catch (Exception ignored) { }
            dialogChrome(dialog);
        };
        dialog.setOnShowListener(d -> styler.run());
        if (dialog.isShowing()) styler.run();
    }

    /** Builder used for every dialog so that all of them share the Meelano look (B5/B6). */
    private final class MeelanoDialogBuilder extends AlertDialog.Builder {
        MeelanoDialogBuilder() { super(MainActivity.this); }
        @Override public AlertDialog create() {
            AlertDialog d = super.create();
            styleMeelanoDialog(d, currentPageAccent());
            return d;
        }
    }

    /** Theme-aware title/message/list colours, app font and SVG icons inside a dialog window. */
    private void dialogChrome(AlertDialog dialog) {
        if (dialog == null || dialog.getWindow() == null) return;
        try {
            View decor = dialog.getWindow().getDecorView();
            int titleId = getResources().getIdentifier("alertTitle", "id", "android");
            TextView title = titleId != 0 ? decor.findViewById(titleId) : null;
            if (title != null) { title.setTextColor(TEXT); title.setTypeface(MEELANO_BOLD); title.setTextSize(fs(16)); title.setGravity(Gravity.START); title.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG_RTL); }
            TextView msg = decor.findViewById(android.R.id.message);
            if (msg != null) { msg.setTextColor(TEXT); msg.setTypeface(MEELANO_REGULAR); msg.setLineSpacing(dp(3), 1f); msg.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG_RTL); }
            if (decor.getTag(R.id.meelano_icon_scan) == null) {
                decor.setTag(R.id.meelano_icon_scan, Boolean.TRUE);
                decor.getViewTreeObserver().addOnGlobalLayoutListener(() -> { tintDialogListRows(decor); MeelanoIcons.iconizeTree(decor); });
            }
            tintDialogListRows(decor);
            MeelanoIcons.iconizeTree(decor);
        } catch (Exception ignored) { }
    }

    private void tintDialogListRows(View v) {
        if (v instanceof TextView && !(v instanceof Button) && !(v instanceof EditText)) {
            int id = v.getId();
            if (id == android.R.id.text1 || id == android.R.id.message) { TextView t = (TextView) v; if (t.getCurrentTextColor() != TEXT) { t.setTextColor(TEXT); t.setTypeface(MEELANO_REGULAR); } }
            return;
        }
        if (v instanceof ViewGroup) { ViewGroup g = (ViewGroup) v; for (int i = 0; i < g.getChildCount(); i++) tintDialogListRows(g.getChildAt(i)); }
    }

    private GradientDrawable rounded(int color, float radius) {
        GradientDrawable d = new GradientDrawable();
        d.setColor(color);
        d.setCornerRadius(dp(radius));
        return d;
    }

    private GradientDrawable roundedStroke(int color, float radius, int strokeColor) {
        GradientDrawable d = rounded(color, radius);
        d.setStroke(dp(1), strokeColor);
        return d;
    }

    private GradientDrawable gradient(int[] colors, GradientDrawable.Orientation orientation, float radius) {
        GradientDrawable d = new GradientDrawable(orientation, colors);
        d.setCornerRadius(dp(radius));
        return d;
    }

    private GradientDrawable glassGradient(int accent, float radius) {
        GradientDrawable d = gradient(new int[]{alpha(Color.WHITE, 30), alpha(accent, 22), alpha(SURFACE, 246)}, GradientDrawable.Orientation.TL_BR, radius);
        d.setStroke(dp(1), alpha(mix(accent, Color.WHITE, 0.24f), 72));
        return d;
    }

    private GradientDrawable diamondStroke(int base, int accent, float radius) {
        GradientDrawable d = gradient(new int[]{mix(base, Color.WHITE, 0.05f), alpha(accent, 20), base}, GradientDrawable.Orientation.TL_BR, radius);
        d.setStroke(dp(1), alpha(accent, 58));
        return d;
    }

    private TextView text(String value, float size, int color, int style) {
        TextView t = new TextView(this);
        t.setText(storeWording(value));
        t.setTextSize(fs(size));
        t.setTextColor(color);
        t.setTypeface(faceFor(style));
        t.setIncludeFontPadding(true);
        t.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1) {
            t.setTextDirection(View.TEXT_DIRECTION_RTL);
        }
        return t;
    }

    private View liveMeelanoLogo(boolean compact) {
        LiveMeelanoLogoView logo = new LiveMeelanoLogoView(this, compact);
        logo.setContentDescription("لوگوی Meelano با ترکیب M و A");
        logo.setLayerType(View.LAYER_TYPE_SOFTWARE, null);
        logo.setMinimumWidth(dp(compact ? 48 : 96));
        logo.setMinimumHeight(dp(compact ? 48 : 96));
        return logo;
    }

    private View headerLogoView() {
        FrameLayout shell = new FrameLayout(this);
        shell.setClipChildren(false);
        shell.setClipToPadding(false);
        shell.setPadding(dp(3), dp(3), dp(3), dp(3));
        shell.setBackground(roundedStroke(alpha(Color.WHITE, isLightTheme() ? 70 : 18), 20, alpha(GOLD, isLightTheme() ? 95 : 120)));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) shell.setElevation(dp(7));
        // App mark = the same gold «D» as the launcher icon, so header, login and home-screen icon match.
        ImageView logo = new ImageView(this);
        logo.setImageResource(R.drawable.meelano_3d);
        logo.setScaleType(ImageView.ScaleType.CENTER_CROP);
        logo.setContentDescription(editionTitle());
        logo.setBackground(roundedStroke(Color.TRANSPARENT, 14, Color.TRANSPARENT));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) logo.setClipToOutline(true);
        shell.addView(logo, new FrameLayout.LayoutParams(dp(48), dp(48), Gravity.CENTER));
        return shell;
    }

    private static final float LOGO_REST_T = (float) (3 * Math.PI);

    private class LiveMeelanoLogoView extends View {
        private final boolean compact;
        private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        private long startMs;
        LiveMeelanoLogoView(Context context, boolean compact) {
            super(context);
            this.compact = compact;
            setWillNotDraw(false);
        }
        @Override protected void onAttachedToWindow() {
            super.onAttachedToWindow();
            startMs = System.currentTimeMillis();
            invalidate();
        }
        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            int w = getWidth(), h = getHeight();
            if (w <= 0 || h <= 0) return;
            boolean moving = motionAllowed();
            float elapsed = (System.currentTimeMillis() - startMs) / 1000f;
            boolean introRunning = moving && elapsed < LOGO_REST_T;
            float t = moving ? Math.min(elapsed, LOGO_REST_T) : 0f;
            float s = Math.min(w, h);
            float cx = w / 2f, cy = h / 2f;
            float pulse = (float) Math.sin(t * 2.0f);
            int themeAccent = VISITOR_EDITION ? currentPageAccent() : INFO;
            int leather = VISITOR_EDITION ? mix(SURFACE_2, themeAccent, isLightTheme() ? 0.10f : 0.24f) : Color.rgb(252, 249, 242);
            int leatherEdge = VISITOR_EDITION ? mix(GOLD_2, themeAccent, 0.22f) : Color.rgb(239, 229, 211);
            int blue = VISITOR_EDITION ? mix(themeAccent, GOLD_2, 0.52f) : Color.rgb(31, 120, 222);
            int deepBlue = VISITOR_EDITION ? mix(Color.rgb(3, 3, 4), themeAccent, 0.22f) : Color.rgb(8, 45, 107);
            int gold = VISITOR_EDITION ? mix(GOLD_2, themeAccent, 0.16f) : Color.rgb(235, 184, 97);
            RectF outer = new RectF(s * 0.06f, s * 0.06f, w - s * 0.06f, h - s * 0.06f);

            p.setStyle(Paint.Style.FILL);
            p.setShadowLayer(s * 0.055f, 0, s * 0.020f, alpha(Color.BLACK, 80));
            p.setColor(leather);
            canvas.drawRoundRect(outer, s * 0.22f, s * 0.22f, p);
            p.clearShadowLayer();
            p.setColor(leatherEdge);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(Math.max(1f, s * 0.035f));
            canvas.drawRoundRect(new RectF(s * 0.09f, s * 0.09f, w - s * 0.09f, h - s * 0.09f), s * 0.18f, s * 0.18f, p);

            p.setStrokeCap(Paint.Cap.ROUND);
            p.setStrokeJoin(Paint.Join.ROUND);
            p.setStrokeWidth(Math.max(1f, s * 0.018f));
            p.setColor(alpha(Color.rgb(198, 174, 132), 54));
            Path grain = new Path();
            grain.moveTo(s * 0.13f, s * 0.30f); grain.cubicTo(s * 0.28f, s * 0.23f, s * 0.41f, s * 0.33f, s * 0.54f, s * 0.27f); grain.cubicTo(s * 0.70f, s * 0.20f, s * 0.82f, s * 0.25f, s * 0.92f, s * 0.32f); canvas.drawPath(grain, p);
            p.setColor(alpha(Color.rgb(226, 210, 180), 60));
            Path grain2 = new Path();
            grain2.moveTo(s * 0.12f, s * 0.70f); grain2.cubicTo(s * 0.30f, s * 0.63f, s * 0.42f, s * 0.76f, s * 0.58f, s * 0.69f); grain2.cubicTo(s * 0.75f, s * 0.61f, s * 0.84f, s * 0.67f, s * 0.93f, s * 0.74f); canvas.drawPath(grain2, p);

            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(Math.max(2f, s * 0.045f));
            p.setColor(gold);
            canvas.drawCircle(cx, cy, s * 0.370f, p);
            if (VISITOR_EDITION) {
                p.setStrokeWidth(Math.max(1f, s * 0.010f));
                p.setColor(alpha(mix(themeAccent, Color.WHITE, 0.28f), 150));
                RectF orbit = new RectF(cx - s * 0.405f, cy - s * 0.405f, cx + s * 0.405f, cy + s * 0.405f);
                canvas.drawArc(orbit, t * 72f, 96f, false, p);
            }
            p.setStrokeWidth(Math.max(1f, s * 0.014f));
            p.setColor(alpha(Color.WHITE, 232));
            canvas.drawCircle(cx, cy, s * 0.327f, p);
            p.setColor(alpha(deepBlue, 44));
            canvas.drawCircle(cx, cy, s * 0.292f, p);

            Path m = new Path();
            m.moveTo(s * 0.235f, s * 0.705f);
            m.lineTo(s * 0.302f, s * 0.323f);
            m.lineTo(s * 0.500f, s * 0.610f);
            m.lineTo(s * 0.698f, s * 0.323f);
            m.lineTo(s * 0.765f, s * 0.705f);
            p.setStrokeCap(Paint.Cap.ROUND);
            p.setStrokeJoin(Paint.Join.ROUND);
            p.setStyle(Paint.Style.STROKE);
            p.setShadowLayer(s * 0.050f, 0, s * 0.020f, alpha(deepBlue, 84));
            p.setStrokeWidth(s * 0.128f);
            p.setColor(blue);
            canvas.drawPath(m, p);
            p.clearShadowLayer();
            p.setStrokeWidth(s * 0.043f);
            p.setColor(deepBlue);
            canvas.drawPath(m, p);
            p.setStrokeWidth(s * 0.040f);
            p.setColor(gold);
            canvas.drawPath(m, p);

            Path inner = new Path();
            inner.moveTo(s * 0.260f, s * 0.690f);
            inner.lineTo(s * 0.312f, s * 0.380f);
            inner.lineTo(s * 0.500f, s * 0.640f);
            inner.lineTo(s * 0.688f, s * 0.380f);
            inner.lineTo(s * 0.740f, s * 0.690f);
            p.setStrokeWidth(s * 0.017f);
            p.setColor(blue);
            canvas.drawPath(inner, p);

            Path a = new Path();
            a.moveTo(s * 0.410f, s * 0.715f);
            a.lineTo(s * 0.500f, s * 0.458f);
            a.lineTo(s * 0.590f, s * 0.715f);
            p.setStrokeWidth(s * 0.030f);
            p.setColor(alpha(Color.WHITE, 214));
            canvas.drawPath(a, p);
            p.setStrokeWidth(Math.max(1f, s * 0.008f));
            p.setColor(alpha(deepBlue, 56));
            canvas.drawPath(a, p);
            p.setStrokeWidth(s * 0.019f);
            p.setColor(alpha(gold, 180));
            canvas.drawLine(s * 0.465f, s * 0.598f, s * 0.555f, s * 0.598f, p);

            p.setStyle(Paint.Style.FILL);
            p.setColor(alpha(Color.rgb(255, 243, 194), 230));
            canvas.drawCircle(s * 0.742f, s * 0.260f, s * (0.030f + 0.004f * pulse), p);
            p.setColor(alpha(blue, 160));
            canvas.drawCircle(s * 0.780f, s * 0.305f, s * 0.012f, p);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(Math.max(1f, s * 0.016f));
            p.setColor(alpha(Color.WHITE, 145));
            canvas.drawLine(s * 0.220f, s * 0.312f, s * 0.270f, s * 0.270f, p);
            canvas.drawLine(s * 0.832f, s * 0.326f, s * 0.858f, s * 0.294f, p);

            // Previously this re-drew on every vsync (60-120 fps, software layer) for as long as the app
            // was open. Now: a short intro at ~30 fps, then the logo rests and costs nothing.
            if (introRunning) postInvalidateDelayed(33);
        }
    }

    private void buildFrame() {
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setBackgroundColor(NAVY);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1) {
            root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);
        }

        LinearLayout headerWrap = new LinearLayout(this);
        headerWrap.setOrientation(LinearLayout.VERTICAL);
        headerWrap.setPadding(dp(8), dp(8), dp(8), dp(8));
        headerWrap.setClipChildren(false);
        headerWrap.setClipToPadding(false);
        headerWrap.setBackground(gradient(new int[]{mix(HEADER_START, INFO, 0.10f), mix(HEADER_END, GOLD_2, 0.08f), HEADER_END}, GradientDrawable.Orientation.LEFT_RIGHT, 0));

        LinearLayout header = new LinearLayout(this);
        header.setOrientation(LinearLayout.HORIZONTAL);
        header.setGravity(Gravity.CENTER_VERTICAL);
        header.setPadding(dp(2), 0, dp(2), 0);
        header.setClipChildren(false);
        header.setClipToPadding(false);

        if (VISITOR_EDITION) {
            LinearLayout identity = visitorHeaderIdentity();
            LinearLayout.LayoutParams idLp = new LinearLayout.LayoutParams(0, dp(60), 1f);
            idLp.setMargins(0, 0, dp(6), 0);
            header.addView(identity, idLp);
        } else {
            View logo = headerLogoView();
            LinearLayout.LayoutParams logoLp = new LinearLayout.LayoutParams(dp(58), dp(58));
            logoLp.setMargins(0, 0, dp(4), 0);
            header.addView(logo, logoLp);

            LinearLayout titles = new LinearLayout(this);
            titles.setOrientation(LinearLayout.VERTICAL);
            titles.setGravity(Gravity.CENTER_VERTICAL);
            titles.setPadding(dp(10), 0, dp(8), 0);
            TextView appTitle = text("Meelano", 17.5f, TEXT, Typeface.BOLD);
            appTitle.setSingleLine(true);
            appTitle.setShadowLayer(dp(2), 0, dp(1), alpha(Color.WHITE, isLightTheme() ? 90 : 20));
            subtitle = text("ورود با حساب Meelano", 10.2f, alpha(TEXT, 205), Typeface.NORMAL);
            subtitle.setSingleLine(true);
            status = text("", 1, Color.TRANSPARENT, Typeface.NORMAL);
            titles.addView(appTitle, new LinearLayout.LayoutParams(-1, -2));
            titles.addView(subtitle, new LinearLayout.LayoutParams(-1, -2));
            header.addView(titles, new LinearLayout.LayoutParams(0, dp(56), 1f));
        }

        connectionIndicator = null;

        LinearLayout tools = new LinearLayout(this);
        tools.setOrientation(LinearLayout.HORIZONTAL);
        tools.setGravity(Gravity.CENTER_VERTICAL);
        tools.setPadding(dp(2), 0, dp(2), 0);
        if (!VISITOR_EDITION) {
            addHeaderTool(tools, "⌕", "جستجوی سراسری", GOLD, v -> showGlobalSearchDialog());
            addHeaderTool(tools, "♛", "مدیریت دسترسی کاربران", GOLD, v -> { if (session == null) showLogin("ابتدا وارد شوید."); else showApp("management"); });
        }
        addHeaderTool(tools, "✺", "انتخاب تم", GOLD, v -> showThemeChooser());
        headerSettingsTool = addHeaderTool(tools, "⚙", "تنظیمات", GOLD, v -> { if (session == null) showLogin("ابتدا وارد شوید."); else showApp("settings"); });
        headerLogoutTool = addHeaderTool(tools, "⎋", "خروج", DANGER, v -> { if (session == null) showLogin("برای ورود، نام کاربری و رمز Meelano را وارد کنید."); else showLogin("از حساب خارج شدید. برای ورود مجدد اطلاعات Meelano را وارد کنید."); });
        header.addView(tools, new LinearLayout.LayoutParams(-2, dp(VISITOR_EDITION ? 58 : 56)));
        refreshHeaderTools();
        headerWrap.addView(header, new LinearLayout.LayoutParams(-1, dp(VISITOR_EDITION ? 68 : 64)));
        setConnectionStatus(session == null ? "idle" : "connected");

        int headerBaseHeight = dp(VISITOR_EDITION ? 88 : 82);
        root.addView(headerWrap, new LinearLayout.LayoutParams(-1, headerBaseHeight));

        stage = new FrameLayout(this);
        stage.setBackgroundColor(NAVY);
        root.addView(stage, new LinearLayout.LayoutParams(-1, 0, 1f));
        setContentView(root);
        applySystemBarStyle();
        installWindowInsets(root, headerWrap, headerBaseHeight);
        // Draw every glyph/emoji label as an SVG-derived vector icon (see MeelanoIcons).
        if (!iconHookInstalled) {
            iconHookInstalled = true;
            final View iconRoot = getWindow().getDecorView();
            iconRoot.getViewTreeObserver().addOnGlobalLayoutListener(() -> MeelanoIcons.iconizeTree(iconRoot));
        }
    }

    private LinearLayout visitorHeaderIdentity() {
        LinearLayout identity = new LinearLayout(this);
        identity.setOrientation(LinearLayout.HORIZONTAL);
        identity.setGravity(Gravity.CENTER_VERTICAL | Gravity.RIGHT);
        identity.setPadding(dp(7), dp(4), dp(7), dp(4));
        identity.setClipChildren(false);
        identity.setClipToPadding(false);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1) {
            identity.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);
            identity.setTextDirection(View.TEXT_DIRECTION_RTL);
        }
        identity.setBackground(unifiedCardBg(GOLD, 26, false));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) identity.setElevation(dp(10));

        FrameLayout mark = new FrameLayout(this);
        mark.setPadding(dp(2), dp(2), dp(2), dp(2));
        mark.setBackground(roundedStroke(alpha(Color.WHITE, 22), 22, alpha(GOLD_2, 150)));
        View logo = headerLogoView();
        mark.addView(logo, new FrameLayout.LayoutParams(dp(46), dp(46), Gravity.CENTER));
        LinearLayout.LayoutParams mlp = new LinearLayout.LayoutParams(dp(52), dp(52));
        mlp.setMargins(0, 0, 0, 0);
        identity.addView(mark, mlp);

        LinearLayout titles = new LinearLayout(this);
        titles.setOrientation(LinearLayout.VERTICAL);
        titles.setGravity(Gravity.CENTER_VERTICAL | Gravity.RIGHT);
        titles.setPadding(dp(8), 0, dp(8), 0);
        TextView appTitle = text(editionTitle(), 15.8f, tc(GOLD_2), Typeface.BOLD);
        appTitle.setSingleLine(true);
        appTitle.setEllipsize(TextUtils.TruncateAt.END);
        appTitle.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        if (!isLightTheme()) appTitle.setShadowLayer(dp(3), 0, dp(1), alpha(Color.BLACK, 150));
        String sub = session == null ? (STORE_EDITION ? "ورود امن کارکنان فروشگاه" : "ورود امن ویزیتور") : (STORE_EDITION ? "کارمند فروشگاه • " : "ویزیتور فعال • ") + session.userName;
        subtitle = text(sub, 9.8f, alpha(TEXT, 226), Typeface.BOLD);
        subtitle.setSingleLine(true);
        subtitle.setEllipsize(TextUtils.TruncateAt.END);
        subtitle.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        TextView badge = text(session == null ? "نسخه فروش میدانی" : "● آماده فروش امروز", 8.6f, tc(isLightTheme() ? mix(GOLD, TEXT, 0.25f) : alpha(GOLD_2, 235)), Typeface.BOLD);
        badge.setSingleLine(true);
        badge.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        titles.addView(appTitle, new LinearLayout.LayoutParams(-1, -2));
        titles.addView(subtitle, new LinearLayout.LayoutParams(-1, -2));
        identity.addView(titles, new LinearLayout.LayoutParams(0, -1, 1f));
        status = text("", 1, Color.TRANSPARENT, Typeface.NORMAL);
        return identity;
    }

    private View headerSettingsTool, headerLogoutTool;

    /** B7: settings and logout only make sense with an active session. */
    private void refreshHeaderTools() {
        int vis = session == null ? View.GONE : View.VISIBLE;
        if (headerSettingsTool != null) headerSettingsTool.setVisibility(vis);
        if (headerLogoutTool != null) headerLogoutTool.setVisibility(vis);
    }

    private View addHeaderTool(LinearLayout parent, String glyph, String label, int accent, View.OnClickListener listener) {
        FrameLayout hit = new FrameLayout(this);
        hit.setContentDescription(label);
        hit.setClickable(true);
        hit.setFocusable(true);
        hit.setMinimumWidth(dp(48));
        hit.setMinimumHeight(dp(48));
        hit.setPadding(dp(4), dp(4), dp(4), dp(4));
        hit.setOnClickListener(listener);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) hit.setElevation(0);
        applyTouchFeedback(hit);

        TextView b = new TextView(this);
        b.setText(glyph == null ? "" : glyph);
        b.setTextSize(fs(glyph != null && glyph.length() > 1 ? 12.0f : 16.4f));
        b.setGravity(Gravity.CENTER);
        b.setSingleLine(true);
        // Unified header tool: tonal circle + monochrome SVG icon in the brand colour (danger only for logout).
        b.setTextColor(tc(accent));
        b.setTypeface(MEELANO_BOLD);
        b.setPadding(0, 0, 0, 0);
        b.setBackground(rounded(alpha(accent, isLightTheme() ? 26 : 46), 999));
        b.setContentDescription(label);
        b.setDuplicateParentStateEnabled(true);
        hit.addView(b, new FrameLayout.LayoutParams(dp(38), dp(38), Gravity.CENTER));

        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(dp(48), dp(50));
        lp.setMargins(0, 0, 0, 0);
        parent.addView(hit, lp);
        return hit;
    }

    private LinearLayout.LayoutParams headerButtonLp(boolean margin) {
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(dp(36), dp(40));
        if (margin) lp.setMargins(dp(5), 0, 0, 0);
        return lp;
    }

    private void setConnectionStatus(String state) {
        if (connectionIndicator == null) return;
        String st = state == null ? "idle" : state;
        int color = INFO;
        String glyph = "◌";
        String desc = "آماده اتصال";
        if (st.contains("loading")) { color = GOLD_2; glyph = "⟳"; desc = "در حال ارتباط با سرور"; }
        else if (st.contains("connected")) { color = SUCCESS; glyph = "●"; desc = "اتصال فعال"; }
        else if (st.contains("offline")) { color = DANGER; glyph = "!"; desc = "عدم اتصال"; }
        connectionIndicator.setText(glyph);
        connectionIndicator.setTextColor(tc(color));
        connectionIndicator.setContentDescription(desc);
        connectionIndicator.setBackground(gradient(new int[]{alpha(color, 82), alpha(GOLD, 22)}, GradientDrawable.Orientation.TL_BR, 14));
        if (st.contains("loading")) connectionIndicator.animate().rotationBy(360f).setDuration(850).start();
        else connectionIndicator.animate().rotation(0f).setDuration(120).start();
    }

    private TextView iconButton(String glyph, String description) {
        TextView b = new TextView(this);
        b.setText(glyph);
        b.setTextSize(fs(21));
        b.setGravity(Gravity.CENTER);
        b.setTextColor(tc(GOLD_2));
        b.setTypeface(MEELANO_BOLD);
        b.setBackground(roundedStroke(alpha(Color.WHITE, 10), 14, alpha(GOLD, 48)));
        b.setContentDescription(description);
        b.setClickable(true);
        b.setFocusable(true);
        return b;
    }

    private GradientDrawable scrollThumb(boolean horizontal) {
        GradientDrawable d = gradient(new int[]{GOLD_2, GOLD, INFO}, horizontal ? GradientDrawable.Orientation.LEFT_RIGHT : GradientDrawable.Orientation.TOP_BOTTOM, 999);
        d.setStroke(dp(1), alpha(Color.WHITE, 88));
        d.setSize(horizontal ? dp(88) : dp(6), horizontal ? dp(6) : dp(88));
        return d;
    }

    private GradientDrawable scrollTrack(boolean horizontal) {
        GradientDrawable d = roundedStroke(alpha(SURFACE_2, 100), 999, alpha(GOLD, 28));
        d.setSize(horizontal ? dp(88) : dp(6), horizontal ? dp(6) : dp(88));
        return d;
    }

    private void styleVerticalScroll(ScrollView scroll) {
        if (scroll == null) return;
        scroll.setVerticalScrollBarEnabled(true);
        scroll.setScrollBarStyle(View.SCROLLBARS_INSIDE_OVERLAY);
        scroll.setScrollbarFadingEnabled(false);
        scroll.setVerticalFadingEdgeEnabled(true);
        scroll.setFadingEdgeLength(dp(22));
        scroll.setOverScrollMode(View.OVER_SCROLL_IF_CONTENT_SCROLLS);
        scroll.setScrollBarSize(dp(6));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            scroll.setVerticalScrollbarThumbDrawable(scrollThumb(false));
            scroll.setVerticalScrollbarTrackDrawable(scrollTrack(false));
        }
    }

    private void styleHorizontalScroll(HorizontalScrollView scroll) {
        if (scroll == null) return;
        scroll.setHorizontalScrollBarEnabled(true);
        scroll.setScrollBarStyle(View.SCROLLBARS_INSIDE_OVERLAY);
        scroll.setScrollbarFadingEnabled(false);
        scroll.setHorizontalFadingEdgeEnabled(true);
        scroll.setFadingEdgeLength(dp(20));
        scroll.setOverScrollMode(View.OVER_SCROLL_IF_CONTENT_SCROLLS);
        scroll.setScrollBarSize(dp(5));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            scroll.setHorizontalScrollbarThumbDrawable(scrollThumb(true));
            scroll.setHorizontalScrollbarTrackDrawable(scrollTrack(true));
        }
    }

