    private void addThemeOption(LinearLayout parent, AlertDialog dialog, String id, String title, String subtitle, int[] palette) {
        boolean selected = id.equals(currentThemeId());
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(Gravity.CENTER_VERTICAL);
        card.setPadding(dp(10), dp(9), dp(10), dp(9));
        card.setClickable(true);
        card.setBackground(gradient(new int[]{alpha(palette[1], selected ? 78 : 32), alpha(palette[2], 20), SURFACE}, GradientDrawable.Orientation.LEFT_RIGHT, 18));
        LinearLayout swatches = new LinearLayout(this);
        swatches.setOrientation(LinearLayout.HORIZONTAL);
        swatches.setGravity(Gravity.CENTER);
        for (int color : palette) {
            TextView dot = new TextView(this);
            dot.setText(" ");
            dot.setGravity(Gravity.CENTER);
            dot.setBackground(gradient(new int[]{mix(color, Color.WHITE, 0.26f), color, mix(color, Color.BLACK, 0.16f)}, GradientDrawable.Orientation.TL_BR, 999));
            LinearLayout.LayoutParams dpLp = new LinearLayout.LayoutParams(dp(24), dp(24));
            dpLp.setMargins(dp(2), 0, dp(2), 0);
            swatches.addView(dot, dpLp);
        }
        card.addView(swatches, new LinearLayout.LayoutParams(-2, dp(38)));
        LinearLayout copy = new LinearLayout(this);
        copy.setOrientation(LinearLayout.VERTICAL);
        copy.setPadding(dp(12), 0, dp(12), 0);
        copy.addView(text(title + (selected ? "  ✓" : ""), 15, selected ? palette[1] : TEXT, Typeface.BOLD), new LinearLayout.LayoutParams(-1, -2));
        copy.addView(text(subtitle, 10.5f, MUTED, Typeface.NORMAL), new LinearLayout.LayoutParams(-1, -2));
        card.addView(copy, new LinearLayout.LayoutParams(0, -2, 1f));
        LinearLayout mini = new LinearLayout(this);
        mini.setOrientation(LinearLayout.VERTICAL);
        mini.setPadding(dp(5), dp(4), dp(5), dp(4));
        mini.setBackground(roundedStroke(alpha(palette[1], selected ? 46 : 22), 14, alpha(palette[2], selected ? 130 : 70)));
        for (int i = 0; i < 3; i++) {
            View bar = new View(this);
            bar.setBackground(gradient(new int[]{alpha(palette[(i + 1) % palette.length], 235), alpha(palette[(i + 2) % palette.length], 175)}, GradientDrawable.Orientation.LEFT_RIGHT, 999));
            LinearLayout.LayoutParams bp = new LinearLayout.LayoutParams(-1, dp(i == 1 ? 8 : 6));
            bp.setMargins(0, i == 0 ? 0 : dp(4), 0, 0);
            mini.addView(bar, bp);
        }
        card.addView(mini, new LinearLayout.LayoutParams(dp(66), dp(40)));
        applyTouchFeedback(card);
        card.setOnClickListener(v -> {
            prefs.edit().putString(KEY_THEME, id).apply();
            applyTheme(id);
            if (dialog != null) dialog.dismiss();
            showNotice("تم «" + themeName(id) + "» اعمال شد", false);
            rebuildUiAfterThemeChange();
        });
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(-1, -2);
        lp.setMargins(0, dp(8), 0, 0);
        parent.addView(card, lp);
    }

    private void rebuildUiAfterThemeChange() {
        UserSession oldSession = session;
        String page = activePage;
        buildFrame();
        session = oldSession;
        if (oldSession == null || "login".equals(page)) {
            showLogin("تم جدید Meelano اعمال شد. برای ورود، نام کاربری و رمز Meelano را وارد کنید.");
        } else {
            showApp(page == null ? "dashboard" : page);
        }
    }

    // ---------------------------------------------------------------------------------------
    // Design system — buttons (v4.6): one shape (14dp corners), one height (≥ 48dp), no text
    // shadows, no gradients. Primary = solid brand colour, secondary = tonal brand tint.
    // Only destructive actions (حذف / خروج / لغو) use the danger colour.
    // ---------------------------------------------------------------------------------------
    private static final float BUTTON_RADIUS = 14f;

    private boolean isDestructiveLabel(String label) {
        String t = label == null ? "" : label;
        return t.contains("حذف") || t.contains("خروج") || t.contains("پاک کردن") || t.contains("لغو سفارش") || t.contains("خالی کردن");
    }

    /** Maps any legacy per-page accent to the unified palette: brand for everything, danger for destructive actions. */
    private int buttonTone(int accent, String label) {
        if (accent == DANGER || isDestructiveLabel(label)) return DANGER;
        return GOLD;
    }

    private android.graphics.drawable.Drawable meelanoButtonBg(int tone, boolean primary) {
        GradientDrawable shape = rounded(primary ? tone : alpha(tone, isLightTheme() ? 30 : 52), BUTTON_RADIUS);
        int ripple = primary ? alpha(onColorFor(tone), 70) : alpha(tone, 70);
        GradientDrawable mask = rounded(Color.WHITE, BUTTON_RADIUS);
        return new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(ripple), shape, mask);
    }

    private void styleMeelanoButton(Button b, String label, int accent, boolean primary, float textSp) {
        if (STORE_EDITION && b.getText() != null && b.getText().toString().contains("پیش")) b.setText(storeWording(b.getText().toString()));
        int tone = buttonTone(accent, label);
        b.setAllCaps(false);
        b.setTextColor(primary ? onColorFor(tone) : tc(tone));
        b.setTextSize(fs(textSp));
        b.setTypeface(MEELANO_BOLD);
        b.setMinHeight(dp(48));
        b.setMinimumHeight(dp(48));
        b.setPadding(dp(12), 0, dp(12), 0);
        b.setShadowLayer(0, 0, 0, Color.TRANSPARENT);
        b.setBackground(meelanoButtonBg(tone, primary));
        b.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG_RTL);
        b.setGravity(Gravity.CENTER);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) { b.setStateListAnimator(null); b.setElevation(0); b.setLetterSpacing(0f); }
        applyTouchFeedback(b);
    }

    private Button primaryButton(String label) {
        Button b = new Button(this);
        b.setText(storeWording(label));
        styleMeelanoButton(b, label, GOLD, true, compactUi() ? 12.4f : 13.2f);
        return b;
    }

    private Button secondaryButton(String label) {
        Button b = new Button(this);
        b.setText(storeWording(label));
        styleMeelanoButton(b, label, GOLD, false, compactUi() ? 12.0f : 12.8f);
        return b;
    }

    private Button themedActionButton(String label, int accent, boolean primary) {
        Button b = new Button(this);
        b.setText(label);
        styleMeelanoButton(b, label, accent, primary, compactUi() ? 11.2f : 12.0f);
        b.setPadding(dp(10), 0, dp(10), 0);
        return b;
    }

    private GradientDrawable themedSectionBg(String page, float radius) {
        int accent = navAccent(page);
        int glow = mix(accent, GOLD_2, isLightTheme() ? 0.12f : 0.18f);
        GradientDrawable d = gradient(new int[]{
                alpha(mix(SURFACE, glow, isLightTheme() ? 0.035f : 0.10f), 252),
                alpha(mix(SURFACE_2, glow, isLightTheme() ? 0.075f : 0.16f), 248),
                alpha(mix(NAVY, glow, isLightTheme() ? 0.025f : 0.12f), 250)
        }, GradientDrawable.Orientation.TL_BR, radius);
        d.setStroke(dp(1), alpha(mix(glow, Color.WHITE, isLightTheme() ? 0.36f : 0.24f), isLightTheme() ? 112 : 88));
        return d;
    }

    private GradientDrawable visitorPanel(int accent, float radius) {
        int hero = mix(accent, GOLD_2, isLightTheme() ? 0.10f : 0.16f);
        int companion = mix(hero, navAccent("showcase"), 0.12f);
        GradientDrawable d = gradient(new int[]{
                alpha(mix(SURFACE, hero, isLightTheme() ? 0.04f : 0.10f), 252),
                alpha(mix(SURFACE_2, companion, isLightTheme() ? 0.08f : 0.18f), 248),
                alpha(mix(NAVY, hero, isLightTheme() ? 0.025f : 0.13f), 252)
        }, GradientDrawable.Orientation.TL_BR, radius);
        d.setStroke(dp(1), alpha(mix(hero, Color.WHITE, isLightTheme() ? 0.40f : 0.26f), isLightTheme() ? 128 : 96));
        return d;
    }

    private GradientDrawable unifiedCardBg(int accent, float radius, boolean selected) {
        int hero = mix(accent, GOLD_2, isLightTheme() ? 0.08f : 0.13f);
        int top = mix(SURFACE, hero, isLightTheme() ? 0.035f : 0.095f);
        int mid = mix(SURFACE_2, hero, isLightTheme() ? 0.07f : 0.155f);
        int bottom = mix(NAVY, hero, isLightTheme() ? 0.018f : 0.105f);
        GradientDrawable d = gradient(new int[]{alpha(top, 252), alpha(mid, 248), alpha(bottom, 252)}, GradientDrawable.Orientation.TL_BR, radius);
        d.setStroke(dp(selected ? 2 : 1), alpha(mix(hero, Color.WHITE, isLightTheme() ? 0.38f : 0.24f), selected ? 170 : (isLightTheme() ? 112 : 92)));
        return d;
    }

    private GradientDrawable unifiedInnerBg(int accent, float radius) {
        int hero = mix(accent, GOLD_2, isLightTheme() ? 0.08f : 0.12f);
        GradientDrawable d = gradient(new int[]{
                alpha(mix(SURFACE, hero, isLightTheme() ? 0.025f : 0.085f), 242),
                alpha(mix(SURFACE_2, hero, isLightTheme() ? 0.06f : 0.13f), 238)
        }, GradientDrawable.Orientation.TL_BR, radius);
        d.setStroke(dp(1), alpha(mix(hero, Color.WHITE, 0.24f), isLightTheme() ? 86 : 72));
        return d;
    }

    private String visitorSectionHeadline(String title) {
        String t = title == null ? "" : title.trim();
        if (t.contains("Meelano")) return "ماموریت امروز";
        if (t.contains("کالا")) return "فروش سریع کالا";
        if (t.contains("سبد")) return "سبد فروش";
        if (t.contains("مشتری")) return "مشتریان";
        if (t.contains("حضور")) return "حضور و وضعیت روز";
        if (t.contains("گفتگو")) return "گفتگوی تیم فروش";
        if (t.contains("تنظیمات")) return "تنظیمات";
        return t.isEmpty() ? editionTitle() : t;
    }

    /** One label everywhere for "add to cart with price tier N" (G2/G3). */
    private static final String PRICE1_BUTTON = "قیمت ۱";
    private static final String PRICE2_BUTTON = "قیمت ۲";
    private static final String MANUAL_PRICE_BUTTON = "قیمت دستی";

    /** Shows ASCII digits as Persian digits (product codes, barcodes) — display only. */
    /** True when the user picked a large system font or the app's large text size (G7). */
    private boolean largeFontScale() {
        try { return getResources().getConfiguration().fontScale >= 1.15f; } catch (Exception e) { return false; }
    }

    private static String faDigits(String v) {
        if (v == null) return "";
        StringBuilder b = new StringBuilder(v.length());
        for (int k = 0; k < v.length(); k++) { char ch = v.charAt(k); b.append(ch >= '0' && ch <= '9' ? (char) ('\u06F0' + (ch - '0')) : ch); }
        return b.toString();
    }

    private EditText input(String hint, String value, boolean password) {
        EditText e = new EditText(this);
        e.setSingleLine(true);
        e.setHint(hint);
        e.setText(value == null ? "" : value);
        e.setHintTextColor(alpha(MUTED, 190));
        e.setTextColor(TEXT);
        e.setTextSize(fs(14));
        e.setSelectAllOnFocus(true);
        e.setPadding(dp(14), 0, dp(14), 0);
        e.setBackground(roundedStroke(SURFACE_2, 14, BORDER));
        e.setInputType(password ? (InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD) : InputType.TYPE_CLASS_TEXT);
        // setInputType() switches password fields to monospace; restore the app font afterwards (B4).
        e.setTypeface(MEELANO_REGULAR);
        // Persian text flows right-to-left, Latin text (user names, server addresses) left-to-right.
        e.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG_RTL);
        e.setGravity(Gravity.START | Gravity.CENTER_VERTICAL);
        e.setMinHeight(dp(48));
        if (password) attachPasswordToggle(e);
        else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N && !latinFieldHint(hint)) {
            // Search/name/address fields: ask the keyboard for Persian first (G6).
            try { e.setImeHintLocales(new android.os.LocaleList(new Locale("fa", "IR"), Locale.US)); } catch (Exception ignored) { }
        }
        return e;
    }

    /** Fields that normally hold Latin text (user names, server addresses, ports, IDs). */
    private static boolean latinFieldHint(String hint) {
        String h = hint == null ? "" : hint.toLowerCase(Locale.US);
        for (String k : new String[]{"کاربری", "user", "سرور", "آدرس سرویس", "دامنه", "ip", "پورت", "port", "ایمیل", "email", "url", "http", "client", "شناسه", "رمز", "کلید", "token"})
            if (h.contains(k)) return true;
        return false;
    }

    /** Eye icon on the left edge of a password field that shows/hides the password. */
    private void attachPasswordToggle(EditText e) {
        final boolean[] visible = {false};
        final Runnable paint = () -> {
            Drawable eye = tintedIcon(visible[0] ? R.drawable.mi_visibility_off : R.drawable.mi_visibility, MUTED, dp(22));
            e.setCompoundDrawables(eye, null, null, null);
            e.setCompoundDrawablePadding(dp(8));
            e.setContentDescription(visible[0] ? "پنهان کردن رمز" : "نمایش رمز");
        };
        paint.run();
        e.setOnTouchListener((v, ev) -> {
            if (ev.getAction() != MotionEvent.ACTION_UP) return false;
            Drawable d = e.getCompoundDrawables()[0];
            if (d == null) return false;
            if (ev.getX() > e.getPaddingLeft() + d.getBounds().width() + dp(12)) return false;
            visible[0] = !visible[0];
            int sel = e.getSelectionEnd();
            e.setInputType(InputType.TYPE_CLASS_TEXT | (visible[0] ? InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD : InputType.TYPE_TEXT_VARIATION_PASSWORD));
            e.setTypeface(MEELANO_REGULAR);
            paint.run();
            try { e.setSelection(Math.max(0, Math.min(sel < 0 ? e.length() : sel, e.length()))); } catch (Exception ignored) { }
            return true;
        });
    }

    private Drawable tintedIcon(int resId, int color, int sizePx) {
        try {
            Drawable d = getResources().getDrawable(resId, getTheme()).mutate();
            d.setTint(color);
            d.setBounds(0, 0, sizePx, sizePx);
            return d;
        } catch (Exception ignored) { return null; }
    }

    /** Number without exponent or trailing ".0" (18500000 instead of 1.85E7). */
    private String plainNumber(double v) {
        if (Double.isNaN(v) || Double.isInfinite(v)) return "0";
        try { return java.math.BigDecimal.valueOf(v).stripTrailingZeros().toPlainString(); } catch (Exception e) { return String.valueOf(v); }
    }

    /** Numeric field that shows Persian digits grouped by thousands while typing and keeps the decimal part (B1). */
    private EditText numberInput(String hint, double value, boolean allowDecimal) {
        EditText e = input(hint, "", false);
        e.setKeyListener(android.text.method.DigitsKeyListener.getInstance("0123456789۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩.,٫٬"));
        e.setRawInputType(InputType.TYPE_CLASS_NUMBER | (allowDecimal ? InputType.TYPE_NUMBER_FLAG_DECIMAL : 0));
        e.setTypeface(MEELANO_REGULAR);
        e.setTextDirection(View.TEXT_DIRECTION_RTL);
        e.setGravity(Gravity.START | Gravity.CENTER_VERTICAL);
        e.addTextChangedListener(new TextWatcher() {
            boolean busy = false;
            @Override public void beforeTextChanged(CharSequence s, int a, int b, int c) { }
            @Override public void onTextChanged(CharSequence s, int a, int b, int c) { }
            @Override public void afterTextChanged(Editable s) {
                if (busy) return;
                String out = groupedDigits(s.toString(), allowDecimal);
                if (out.equals(s.toString())) return;
                busy = true;
                try { s.replace(0, s.length(), out); } catch (Exception ignored) { }
                busy = false;
            }
        });
        e.setText(value == 0 && hint != null && hint.contains("تخفیف") ? "" : plainNumber(value));
        return e;
    }

    /** Quantity field: same Persian-digit numeric field as the cart edit form (G5). */
    private EditText qtyInput(String hint, String value) {
        EditText e = numberInput(hint, 0, true);
        e.setText(value == null ? "" : value);
        return e;
    }

    private String groupedDigits(String raw, boolean allowDecimal) {
        String n = normalizeDigits(raw == null ? "" : raw).replace('\u066B', '.').replace('\u066C', ',');
        int dot = allowDecimal ? n.indexOf('.') : -1;
        String intPart = dot >= 0 ? n.substring(0, dot) : n;
        String frac = dot >= 0 ? n.substring(dot + 1) : "";
        StringBuilder digits = new StringBuilder();
        for (int i = 0; i < intPart.length(); i++) { char ch = intPart.charAt(i); if (ch >= '0' && ch <= '9') digits.append(ch); }
        StringBuilder fd = new StringBuilder();
        for (int i = 0; i < frac.length(); i++) { char ch = frac.charAt(i); if (ch >= '0' && ch <= '9') fd.append(ch); }
        String d = digits.toString().replaceFirst("^0+(?=\\d)", "");
        StringBuilder g = new StringBuilder();
        for (int i = 0; i < d.length(); i++) {
            if (i > 0 && (d.length() - i) % 3 == 0) g.append('\u066C');
            g.append((char) ('\u06F0' + (d.charAt(i) - '0')));
        }
        if (dot >= 0) {
            if (g.length() == 0) g.append('\u06F0');
            g.append('\u066B');
            for (int i = 0; i < fd.length(); i++) g.append((char) ('\u06F0' + (fd.charAt(i) - '0')));
        }
        return g.toString();
    }

    /** Adds a small caption above a form field so the field keeps its meaning after it is filled (B1). */
    private void addLabeledField(LinearLayout box, String label, View field, int heightDp) {
        TextView cap = text(label, 10.4f, MUTED, Typeface.BOLD);
        cap.setPadding(dp(4), dp(9), dp(4), dp(3));
        box.addView(cap, new LinearLayout.LayoutParams(-1, -2));
        box.addView(field, new LinearLayout.LayoutParams(-1, heightDp > 0 ? dp(heightDp) : -2));
    }

    private LinearLayout card() {
        LinearLayout c = new LinearLayout(this);
        c.setOrientation(LinearLayout.VERTICAL);
        int pad = compactUi() ? dp(11) : dp(15);
        c.setPadding(pad, pad, pad, pad);
        c.setBackground(VISITOR_EDITION ? visitorPanel(currentPageAccent(), compactUi() ? 22 : 28) : premiumPanel(currentPageAccent(), compactUi() ? 19 : 23));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) c.setElevation(dp(VISITOR_EDITION ? 9 : 7));
        animateEntrance(c, motionSerial++);
        return c;
    }

    private int currentPageAccent() {
        return navAccent(activePage == null || activePage.trim().isEmpty() ? "dashboard" : activePage);
    }

    private void animateEntrance(View v, int seed) {
        if (v == null || !motionAllowed()) return;
        try {
            int delay = Math.min(220, (Math.abs(seed) % 9) * 24);
            v.setAlpha(0f);
            v.setTranslationY(dp(9));
            v.setScaleX(0.988f);
            v.setScaleY(0.988f);
            v.animate()
                    .alpha(1f)
                    .translationY(0f)
                    .scaleX(1f)
                    .scaleY(1f)
                    .setStartDelay(delay)
                    .setDuration(260)
                    .start();
        } catch (Exception ignored) { }
    }

    private class VisitorLeatherBackgroundView extends View {
        private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        VisitorLeatherBackgroundView(Context context) { super(context); setWillNotDraw(false); }
        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            int w = getWidth(), h = getHeight();
            if (w <= 0 || h <= 0) return;
            canvas.drawColor(isLightTheme() ? NAVY : Color.rgb(4, 4, 3));
            p.setStyle(Paint.Style.FILL);
            p.setColor(isLightTheme() ? alpha(mix(SURFACE_2, GOLD_2, 0.10f), 210) : alpha(Color.rgb(28, 22, 10), 185));
            canvas.drawRect(0, 0, w, h, p);
            p.setColor(isLightTheme() ? alpha(Color.WHITE, 92) : alpha(Color.BLACK, 118));
            canvas.drawRect(0, h * 0.18f, w, h, p);
            p.setColor(alpha(GOLD_2, isLightTheme() ? 20 : 10));
            int step = Math.max(dp(118), 96);
            for (int y = -step; y < h + step; y += step) {
                for (int x = -step; x < w + step; x += step) {
                    Path diamond = new Path();
                    diamond.moveTo(x + step / 2f, y);
                    diamond.lineTo(x + step, y + step / 2f);
                    diamond.lineTo(x + step / 2f, y + step);
                    diamond.lineTo(x, y + step / 2f);
                    diamond.close();
                    p.setStyle(Paint.Style.STROKE);
                    p.setStrokeWidth(Math.max(1f, dp(0.55f)));
                    canvas.drawPath(diamond, p);
                    p.setStyle(Paint.Style.FILL);
                }
            }
            p.setColor(alpha(GOLD, 32));
            canvas.drawCircle(w * 0.14f, h * 0.12f, Math.max(w, h) * 0.20f, p);
            p.setColor(alpha(GOLD_2, 24));
            canvas.drawCircle(w * 0.92f, h * 0.06f, Math.max(w, h) * 0.18f, p);
            p.setColor(isLightTheme() ? alpha(mix(INFO, Color.WHITE, 0.55f), 58) : alpha(Color.BLACK, 112));
            canvas.drawCircle(w * 0.50f, h * 0.94f, Math.max(w, h) * 0.42f, p);
            p.setColor(alpha(GOLD_2, 34));
            for (int i = 0; i < 22; i++) {
                float x = (i * 89 % Math.max(1, w));
                float y = (i * 157 % Math.max(1, h));
                canvas.drawCircle(x, y, dp(i % 5 == 0 ? 1.8f : 0.9f), p);
            }
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(dp(1));
            p.setColor(alpha(GOLD, 13));
            for (int i = 0; i < 5; i++) canvas.drawLine(-w * .1f, h * (i / 4f), w * 1.1f, h * (i / 4f) - dp(70), p);
            p.setStyle(Paint.Style.FILL);
        }
    }

    private class VisitorGoalRingView extends View {
        private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final double progress;
        private final String center;
        private final String label;
        VisitorGoalRingView(Context context, double progress, String center, String label) {
            super(context);
            this.progress = Math.max(0d, Math.min(1d, progress));
            this.center = center == null ? "۰٪" : center;
            this.label = label == null ? "هدف" : label;
            setWillNotDraw(false);
        }
        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            int w = getWidth(), h = getHeight();
            if (w <= 0 || h <= 0) return;
            float s = Math.min(w, h);
            float pad = s * 0.14f;
            RectF r = new RectF((w - s) / 2f + pad, (h - s) / 2f + pad, (w + s) / 2f - pad, (h + s) / 2f - pad);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeCap(Paint.Cap.ROUND);
            p.setStrokeWidth(Math.max(dp(8), s * 0.075f));
            p.setColor(alpha(GOLD_2, 36));
            canvas.drawArc(r, -90, 360, false, p);
            p.setColor(progress >= .75d ? SUCCESS : (progress >= .38d ? GOLD_2 : DANGER));
            canvas.drawArc(r, -90, (float)(360d * progress), false, p);
            p.setStyle(Paint.Style.FILL);
            p.setTextAlign(Paint.Align.CENTER);
            p.setTypeface(MEELANO_BOLD);
            p.setTextSize(s * 0.20f);
            p.setColor(TEXT);
            canvas.drawText(center, w / 2f, h / 2f + s * 0.03f, p);
            p.setTypeface(MEELANO_REGULAR);
            p.setTextSize(s * 0.095f);
            p.setColor(MUTED);
            canvas.drawText(label, w / 2f, h / 2f + s * 0.18f, p);
        }
    }


    private class VisitorDonutChartView extends View {
        private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final JSONArray data;
        private final String label;
        private final int[] colors = new int[]{SUCCESS, WARNING, INFO, GOLD_2, DANGER, navAccent("visitor_more")};
        VisitorDonutChartView(Context context, JSONArray data, String label) {
            super(context);
            this.data = data;
            this.label = label == null ? "وضعیت" : label;
            setBackground(roundedStroke(alpha(SURFACE_2, 235), 18, BORDER));
            setWillNotDraw(false);
        }
        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            int w = getWidth(), h = getHeight();
            if (w <= 0 || h <= 0) return;
            float s = Math.min(w, h);
            float pad = s * 0.15f;
            RectF r = new RectF((w - s) / 2f + pad, (h - s) / 2f + pad, (w + s) / 2f - pad, (h + s) / 2f - pad);
            double total = 0;
            int n = data == null ? 0 : data.length();
            for (int i = 0; i < n; i++) { JSONObject o = data.optJSONObject(i); if (o != null) total += Math.max(0, o.optDouble("count", o.optDouble("value", 0))); }
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeCap(Paint.Cap.BUTT);
            p.setStrokeWidth(Math.max(dp(10), s * 0.10f));
            p.setColor(alpha(GOLD_2, isLightTheme() ? 34 : 52));
            canvas.drawArc(r, -90, 360, false, p);
            if (total > 0) {
                float start = -90;
                for (int i = 0; i < n; i++) {
                    JSONObject o = data.optJSONObject(i); if (o == null) continue;
                    double v = Math.max(0, o.optDouble("count", o.optDouble("value", 0)));
                    if (v <= 0) continue;
                    p.setColor(alpha(colors[i % colors.length], 235));
                    float sweep = (float)(360d * v / total);
                    canvas.drawArc(r, start, Math.max(2.5f, sweep - 1.5f), false, p);
                    start += sweep;
                }
            }
            p.setStyle(Paint.Style.FILL);
            p.setTextAlign(Paint.Align.CENTER);
            p.setTypeface(MEELANO_BOLD);
            p.setTextSize(s * 0.20f);
            p.setColor(TEXT);
            canvas.drawText(formatNumber(Math.round(total)), w / 2f, h / 2f + s * 0.02f, p);
            p.setTypeface(MEELANO_REGULAR);
            p.setTextSize(s * 0.088f);
            p.setColor(MUTED);
            canvas.drawText(label, w / 2f, h / 2f + s * 0.17f, p);
        }
    }

    private class DiamondPatternView extends View {
        private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        DiamondPatternView(Context context) { super(context); }
        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            int w = getWidth(), h = getHeight();
            if (w <= 0 || h <= 0) return;
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(Math.max(1f, dp(0.7f)));
            p.setColor(alpha(GOLD_2, 30));
            int step = Math.max(dp(42), 42);
            for (int x = -w; x < w * 2; x += step) {
                canvas.drawLine(x, 0, x + h, h, p);
                canvas.drawLine(x + h, 0, x, h, p);
            }
            p.setColor(alpha(INFO, 24));
            p.setStrokeWidth(Math.max(1f, dp(1.1f)));
            for (int x = -w; x < w * 2; x += step * 3) {
                canvas.drawLine(x, 0, x + h, h, p);
            }
        }
    }


