    private String defaultCameraLiveTemplate() { return "rtsp://{user}:{pass}@{host}:{streamPort}/cam/realmonitor?channel={ch}&subtype=0"; }
    private String defaultCameraReplayTemplate() { return "rtsp://{user}:{pass}@{host}:{streamPort}/cam/playback?channel={ch}"; }
    private String cameraServicePortText() { return stringOr(prefString(KEY_CAMERA_PORT, "37777"), "37777"); }
    private String cameraDefaultStreamPort(String servicePort) { return "37777".equals(normalizeDigits(stringOr(servicePort, "")).trim()) ? "554" : stringOr(servicePort, "554"); }
    private String cameraStreamPortText() { return stringOr(prefString(KEY_CAMERA_STREAM_PORT, cameraDefaultStreamPort(cameraServicePortText())), cameraDefaultStreamPort(cameraServicePortText())); }

    private void testCameraConnection() {
        String host = prefString(KEY_CAMERA_HOST, "").trim();
        if (host.isEmpty()) { showNotice("IP دوربین را ثبت کنید.", false); return; }
        runNetworkJob("camera-test", () -> {
            StringBuilder ok = new StringBuilder();
            int service = parsePort(cameraServicePortText(), 37777);
            int stream = parsePort(cameraStreamPortText(), service == 37777 ? 554 : service);
            testTcp(host, service, 7000); ok.append("P2P/Device ").append(service).append(" ✓");
            if (stream != service) { testTcp(host, stream, 7000); ok.append(" • RTSP ").append(stream).append(" ✓"); }
            return ok.toString();
        }, new NetworkCallback() {
            @Override public void ok(String b) { showNotice("ارتباط دوربین برقرار شد: " + b, true); }
            @Override public void fail(Exception e) { showPageError("تست دوربین", e, () -> renderCamerasPage()); }
        });
    }

    private int parsePort(String value, int fallback) {
        try { int p = Integer.parseInt(normalizeDigits(value == null ? "" : value).trim()); return p > 0 && p <= 65535 ? p : fallback; }
        catch (Exception ignored) { return fallback; }
    }

    private String testTcp(String host, int port, int timeoutMs) throws Exception {
        try (Socket s = new Socket()) { s.connect(new InetSocketAddress(host, port), timeoutMs); return "ok"; }
    }

    private String cameraUrl(int ch, boolean replay) {
        String tpl = prefString(replay ? KEY_CAMERA_REPLAY_TEMPLATE : KEY_CAMERA_TEMPLATE, replay ? defaultCameraReplayTemplate() : defaultCameraLiveTemplate());
        String servicePort = cameraServicePortText();
        String streamPort = cameraStreamPortText();
        boolean rtsp = tpl.trim().toLowerCase(Locale.US).startsWith("rtsp://");
        return tpl.replace("{host}", prefString(KEY_CAMERA_HOST, "").trim())
                .replace("{servicePort}", servicePort)
                .replace("{streamPort}", streamPort)
                .replace("{port}", rtsp ? streamPort : servicePort)
                .replace("{user}", urlPart(prefString(KEY_CAMERA_USER, "")))
                .replace("{pass}", urlPart(prefSecret(KEY_CAMERA_PASS)))
                .replace("{ch}", String.valueOf(ch));
    }
    private String urlPart(String v){ try{return URLEncoder.encode(v==null?"":v,"UTF-8");}catch(Exception ignored){return v==null?"":v;} }

    private void showCameraPlayer(int ch, boolean replay){ String url=cameraUrl(ch,replay); if(prefString(KEY_CAMERA_HOST,"").trim().isEmpty()){showNotice("ابتدا تنظیمات DVR را ثبت کنید.", false);return;} LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); box.setPadding(dp(8),dp(8),dp(8),dp(4)); box.addView(text((replay?"بازپخش ":"پخش زنده ")+"دوربین "+formatNumber(ch),16,TEXT,Typeface.BOLD),new LinearLayout.LayoutParams(-1,-2)); VideoView video=new VideoView(this); MediaController mc=new MediaController(this); mc.setAnchorView(video); video.setMediaController(mc); video.setVideoURI(Uri.parse(url)); FrameLayout wrap=new FrameLayout(this); wrap.setBackgroundColor(Color.BLACK); wrap.addView(video,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER)); LinearLayout.LayoutParams vp=new LinearLayout.LayoutParams(-1,dp(280)); vp.setMargins(0,dp(8),0,dp(8)); box.addView(wrap,vp); LinearLayout row=new LinearLayout(this); row.setOrientation(LinearLayout.HORIZONTAL); Button play=primaryButton("شروع پخش"); Button zoom=secondaryButton("زوم ×۱.۳"); Button external=secondaryButton("پلیر خارجی"); final float[] scale={1f}; play.setOnClickListener(v->{ try{video.start();}catch(Exception ex){showNotice("پخش شروع نشد: "+shortError(ex), true);} }); zoom.setOnClickListener(v->{ scale[0]=scale[0]<1.6f?scale[0]+0.3f:1f; video.setScaleX(scale[0]); video.setScaleY(scale[0]); zoom.setText("زوم ×"+String.format(Locale.US,"%.1f",scale[0])); }); external.setOnClickListener(v->openExternalStream(url)); row.addView(play,weightedButtonLp()); row.addView(zoom,weightedButtonLp()); row.addView(external,weightedButtonLp()); box.addView(row,new LinearLayout.LayoutParams(-1,-2)); AlertDialog dlg=new MeelanoDialogBuilder().setView(box).setNegativeButton("بستن",(d,w)->{try{video.stopPlayback();}catch(Exception ignored){}}).create(); styleMeelanoDialog(dlg,navAccent("cameras")); dlg.setOnShowListener(d-> { try{ video.start(); }catch(Exception ignored){} }); dlg.show(); }


    private void openExternalStream(String url){ try{ Intent i=new Intent(Intent.ACTION_VIEW, Uri.parse(url)); i.setDataAndType(Uri.parse(url), "video/*"); startActivity(Intent.createChooser(i,"باز کردن تصویر دوربین")); }catch(Exception ex){ showNotice("پلیر سازگار پیدا نشد.", true); } }

    private void renderAlarmPage(){ content.removeAllViews(); addHero("دزدگیر", "مدیریت حرفه‌ای دو دستگاه دزدگیر Z4 و Extra G1 با ذخیره امن مشخصات، تست ارتباط و فرمان‌های سریع."); addAlarmOverviewCard(); int configured=(alarmString(1,"host","").trim().isEmpty()?0:1)+(alarmString(2,"host","").trim().isEmpty()?0:1); addHardwareStatusCard("alarm", "سلامت تجهیزات امنیتی", configured, 2, "آخرین رویداد: " + prefString(KEY_ALARM_LOG,"ثبت نشده")); addAlarmDeviceCard(1); addAlarmDeviceCard(2); }

    private String alarmKey(int index,String name){ return "alarm_"+index+"_"+name; }
    private String alarmSecret(int index,String name){ return prefSecret(alarmKey(index,name)); }
    private String alarmString(int index,String name,String def){ return prefString(alarmKey(index,name),def); }

