    private String queryCustomerLedger(String customerCode, String filter) throws Exception {
        JSONArray rows = new JSONArray();
        try (Connection c = openConnection()) {
            if (customerCode == null || customerCode.trim().isEmpty()) return rows.toString();
            if ("all".equals(filter) || "sales".equals(filter) || "paid".equals(filter)) appendCustomerSalesLedger(c, rows, customerCode);
            if ("all".equals(filter) || "checks".equals(filter) || "paid".equals(filter)) appendCustomerChecksLedger(c, rows, customerCode, true);
            if ("all".equals(filter) || "checks".equals(filter)) appendCustomerChecksLedger(c, rows, customerCode, false);
        }
        return sortLedgerRows(rows).toString();
    }

    private JSONArray sortLedgerRows(JSONArray rows) throws Exception {
        List<JSONObject> list = new ArrayList<>();
        for (int i = 0; i < rows.length(); i++) list.add(rows.optJSONObject(i));
        java.util.Collections.sort(list, (a, b) -> b.optString("date", "").compareTo(a.optString("date", "")));
        JSONArray out = new JSONArray();
        for (JSONObject o : list) if (o != null) out.put(o);
        return out;
    }

    private void appendCustomerSalesLedger(Connection c, JSONArray rows, String code) throws Exception {
        Set<String> cols = columns(c, "sailfact");
        String shmo = resolve(cols, "shmo"); String date = resolve(cols, "date"); String amount = resolve(cols, "all"); String number = resolve(cols, "shfacfo");
        if (shmo == null || date == null || amount == null) return;
        String tasvieh = resolve(cols, "tasvieh"); String paid = resolve(cols, "MabDaryaftFactor", "Daryaft"); String desc = resolve(cols, "description", "Explain");
        List<Object> params = new ArrayList<>(); params.add(code);
        String innerWhere = "WHERE TRY_CONVERT(nvarchar(100),x.[" + shmo + "])=?" + activeAnd(cols, "x");
        String soft = softDeleteCondition(cols, "x"); if (!soft.isEmpty()) innerWhere += " AND " + soft;
        String source = dedupeFactorSource("sailfact", cols, number, "sf", innerWhere);
        String sql = "SELECT TOP (100) sf.[" + date + "], " + (number == null ? "CAST(NULL AS nvarchar(50))" : "TRY_CONVERT(nvarchar(50),sf.[" + number + "])") + ", " + sqlNumberExpr("sf", amount, "decimal(19,2)") + ", " + (tasvieh == null ? "N'نامشخص'" : "TRY_CONVERT(nvarchar(50),sf.[" + tasvieh + "])") + ", " + (paid == null ? "CAST(0 AS decimal(19,2))" : sqlNumberExpr("sf", paid, "decimal(19,2)") ) + ", " + (desc == null ? "CAST(NULL AS nvarchar(500))" : "TRY_CONVERT(nvarchar(500),sf.[" + desc + "])") + " FROM " + source + " ORDER BY sf.[" + date + "] DESC";
        try (PreparedStatement ps = c.prepareStatement(sql)) { setParams(ps, params); try (ResultSet r = ps.executeQuery()) { while (r.next()) { JSONObject o = new JSONObject(); o.put("type", "فاکتور فروش"); o.put("date", r.getString(1)); o.put("title", "شماره فاکتور " + stringOr(r.getString(2), "—")); o.put("amount", r.getDouble(3)); o.put("status", "تسویه: " + translateStatus(stringOr(r.getString(4), "—")) + " / دریافتی: " + money(r.getObject(5))); o.put("description", stringOr(r.getString(6), "")); rows.put(o); } } }
    }

    private void appendCustomerChecksLedger(Connection c, JSONArray rows, String code, boolean incoming) throws Exception {
        String table = incoming ? "getchk" : "putchk";
        Set<String> cols = columns(c, table); Set<String> typeCols = columns(c, "CheckTypes");
        String shmo = resolve(cols, "shmo"); String amount = incoming ? resolve(cols, "getchkmab", "mablagh") : resolve(cols, "putchkmab", "mablagh");
        if (shmo == null || amount == null) return;
        String date = incoming ? resolve(cols, "getchkdate", "chkdate", "date", "sarresid") : resolve(cols, "putchkdate", "chkdate", "date", "sarresid");
        String number = incoming ? resolve(cols, "getchknum", "chknum", "number", "serial") : resolve(cols, "putchknum", "chknum", "number", "serial");
        String status = incoming ? resolve(cols, "chk_satus", "status") : resolve(cols, "putchk_status", "status");
        String desc = resolve(cols, "description", "Explain", "tozihat");
        String statusExpr = status == null ? "N'نامشخص'" : (hasCol(typeCols, "ID") && hasCol(typeCols, "Desciption") ? "COALESCE(TRY_CONVERT(nvarchar(120),t.Desciption),TRY_CONVERT(nvarchar(50),x.[" + status + "]))" : "TRY_CONVERT(nvarchar(50),x.[" + status + "])");
        String join = status != null && hasCol(typeCols, "ID") && hasCol(typeCols, "Desciption") ? " LEFT JOIN dbo.CheckTypes t ON t.ID=x.[" + status + "]" : "";
        String sql = "SELECT TOP (100) " + (date == null ? "CAST(NULL AS nvarchar(20))" : "TRY_CONVERT(nvarchar(20),x.[" + date + "])") + ", " + (number == null ? "CAST(NULL AS nvarchar(50))" : "TRY_CONVERT(nvarchar(50),x.[" + number + "])") + ", TRY_CONVERT(decimal(19,2),x.[" + amount + "]), " + statusExpr + ", " + (desc == null ? "CAST(NULL AS nvarchar(500))" : "TRY_CONVERT(nvarchar(500),x.[" + desc + "])") + " FROM dbo.[" + table + "] x" + join + " WHERE TRY_CONVERT(nvarchar(100),x.[" + shmo + "])=? ORDER BY 1 DESC";
        try (PreparedStatement ps = c.prepareStatement(sql)) { ps.setString(1, code); try (ResultSet r = ps.executeQuery()) { while (r.next()) { JSONObject o = new JSONObject(); o.put("type", incoming ? "چک دریافتی" : "چک پرداختی"); o.put("date", stringOr(r.getString(1), "—")); o.put("title", "شماره چک " + stringOr(r.getString(2), "—")); o.put("amount", r.getDouble(3)); o.put("status", stringOr(r.getString(4), "—")); o.put("description", stringOr(r.getString(5), "")); rows.put(o); } } }
    }


    private void loadVisitorDashboard() { loadVisitorDashboard(false); }

    private void loadVisitorDashboard(boolean force) {
        if (VISITOR_EDITION && !force && visitorDashboardCacheJson != null && !visitorDashboardCacheJson.trim().isEmpty()) {
            try { renderVisitorDashboard(new JSONObject(visitorDashboardCacheJson)); return; } catch (Exception ignored) { }
        }
        content.removeAllViews();
        if (!VISITOR_EDITION) {
            addHero("داشبورد ویزیتور", "فروش روزانه، اهداف، وضعیت مشتریان و مسیر اقدام سریع برای ویزیتور");
            addManualRefreshPanel("visitor_dashboard", "بروزرسانی داشبورد ویزیتور", "اطلاعات اختصاصی کاربر فعلی", () -> loadVisitorDashboard(true));
        }
        addLoading(content, "در حال آماده‌سازی خانه ویزیتور…");
        runDb(this::queryVisitorDashboardSql, new DbCallback() {
            @Override public void ok(String body) {
                try { if (VISITOR_EDITION) visitorDashboardCacheJson = body; renderVisitorDashboard(new JSONObject(body)); markRefresh("visitor_dashboard"); }
                catch (Exception e) { showPageError("داشبورد ویزیتور", e, () -> loadVisitorDashboard(true)); }
            }
            @Override public void fail(Exception e) { showPageError("داشبورد ویزیتور", e, () -> loadVisitorDashboard(true)); }
        });
    }

    private String queryVisitorDashboardSql() throws Exception {
        try (Connection c = openConnection()) {
            JSONObject out = new JSONObject();
            Integer vid = currentVisitorScopeId();
            out.put("visitorId", vid == null ? JSONObject.NULL : vid);
            out.put("visitor", session == null ? currentAccountName() : session.userName);
            out.put("date", latestDate(c, "sailfact", "date"));
            JSONObject sales = new JSONObject();
            sales.put("total", 0); sales.put("count", 0); sales.put("customers", 0); sales.put("avg", 0);
            if (vid != null && vid > 0 && tableExists(c, "sailfact")) {
                Set<String> sf = columns(c, "sailfact");
                String vis = resolveFlexible(sf, "vis_rdf", "VisitorID", "visid", "visitor", "shvis");
                String amount = resolveFlexible(sf, "all", "amount", "Total", "mablagh");
                String date = resolveFlexible(sf, "date", "DATE", "t_date");
                String shmo = resolveFlexible(sf, "shmo", "SHMO", "CustomerCode");
                if (vis != null && amount != null) {
                    String latest = out.optString("date", "");
                    List<Object> params = new ArrayList<>(); params.add(String.valueOf(vid));
                    String number = resolveFlexible(sf, "shfacfo", "shfac", "factor_no", "invoice_no", "number", "serial");
                    String inner = "WHERE TRY_CONVERT(nvarchar(100),x.[" + vis + "])=?" + activeAnd(sf, "x");
                    if (date != null && latest != null && !latest.trim().isEmpty()) { inner += " AND (TRY_CONVERT(nvarchar(30),x.[" + date + "])=? OR LEFT(TRY_CONVERT(nvarchar(30),x.[" + date + "]),10)=LEFT(?,10))"; params.add(latest); params.add(latest); }
                    String soft = softDeleteCondition(sf, "x"); if (!soft.isEmpty()) inner += " AND " + soft;
                    String source = dedupeFactorSource("sailfact", sf, number, "s", inner);
                    String sql = "SELECT COUNT_BIG(1), ISNULL(SUM(" + sqlNumberExpr("s", amount, "decimal(19,2)") + "),0), " + (shmo == null ? "CAST(0 AS bigint)" : "COUNT(DISTINCT s.[" + shmo + "])") + " FROM " + source;
                    try (PreparedStatement ps = c.prepareStatement(sql)) {
                        setParams(ps, params);
                        try (ResultSet r = ps.executeQuery()) {
                            if (r.next()) { long count = r.getLong(1); double total = r.getDouble(2); sales.put("count", count); sales.put("total", total); sales.put("customers", r.getLong(3)); sales.put("avg", count == 0 ? 0 : total / count); }
                        }
                    }
                }
            }
            out.put("sales", sales);
            out.put("topDebtors", queryTopDebtors(c));
            out.put("overdueInvoices", queryOverdueInvoices(c));
            out.put("inactiveCustomers", queryInactiveCustomers(c));
            out.put("goals", queryVisitorGoals(c, vid));
            out.put("dailyScore", queryVisitorDailyScore(c, vid, sales));
            try {
                ensurePrefactorTables(c);
                out.put("todayPrefactors", queryPrefactorMetric(c, "today"));
                out.put("weekPrefactors", queryPrefactorMetric(c, "week"));
                out.put("weekTrend", queryVisitorPrefactorWeekTrend(c));
                out.put("prefactorStatus", queryPrefactorStatusReport(c));
                out.put("priceTiers", queryVisitorPriceTierBreakdown(c, "today"));
            } catch (Exception ignored) {
                out.put("weekTrend", new JSONArray());
                out.put("prefactorStatus", new JSONArray());
                out.put("priceTiers", new JSONArray());
            }
            return out.toString();
        }
    }

    private JSONObject queryVisitorDailyScore(Connection c, Integer vid, JSONObject sales) {
        JSONObject o = new JSONObject();
        try {
            o.put("salesAmount", sales == null ? 0 : sales.optDouble("total", 0));
            o.put("salesInvoices", sales == null ? 0 : sales.optInt("count", 0));
            o.put("salesCustomers", sales == null ? 0 : sales.optInt("customers", 0));
            ensurePrefactorTables(c);
            String user = currentAccountName();
            String vidText = vid == null ? "" : String.valueOf(vid);
            long prefactors = 0, visits = 0, price2Items = 0; double prefactorAmount = 0;
            try (PreparedStatement ps = c.prepareStatement("SELECT COUNT_BIG(1), ISNULL(SUM(ISNULL(grand_total,total_amount)),0) FROM dbo.meelano_prefactors WHERE CONVERT(date,created_at)=CONVERT(date,SYSDATETIME()) AND (visitor_username=? OR visitor_id=?)")) {
                ps.setString(1, user); ps.setString(2, vidText);
                try (ResultSet r = ps.executeQuery()) { if (r.next()) { prefactors = r.getLong(1); prefactorAmount = r.getDouble(2); } }
            }
            try (PreparedStatement ps = c.prepareStatement("SELECT COUNT_BIG(1) FROM dbo.meelano_visit_results WHERE CONVERT(date,created_at)=CONVERT(date,SYSDATETIME()) AND (visitor_username=? OR visitor_id=?)")) {
                ps.setString(1, user); ps.setString(2, vidText);
                try (ResultSet r = ps.executeQuery()) { if (r.next()) visits = r.getLong(1); }
            }
            try (PreparedStatement ps = c.prepareStatement("SELECT COUNT_BIG(1) FROM dbo.meelano_prefactor_items i INNER JOIN dbo.meelano_prefactors p ON p.id=i.prefactor_id WHERE CONVERT(date,p.created_at)=CONVERT(date,SYSDATETIME()) AND (p.visitor_username=? OR p.visitor_id=?) AND i.price_tier=N'2'")) {
                ps.setString(1, user); ps.setString(2, vidText);
                try (ResultSet r = ps.executeQuery()) { if (r.next()) price2Items = r.getLong(1); }
            }
            o.put("visits", visits); o.put("prefactors", prefactors); o.put("prefactorAmount", prefactorAmount); o.put("price2Items", price2Items);
        } catch (Exception ignored) { }
        return o;
    }


    private JSONArray queryVisitorPrefactorWeekTrend(Connection c) {
        JSONArray arr = new JSONArray();
        try {
            ensurePrefactorTables(c);
            for (int offset = 6; offset >= 0; offset--) {
                List<Object> params = new ArrayList<>();
                String own = visitorOwnScope("p", params);
                String where = " WHERE CONVERT(date,p.created_at)=DATEADD(day,-?,CONVERT(date,SYSDATETIME()))" + (own.isEmpty() ? "" : " AND " + own);
                String sql = "SELECT CONVERT(nvarchar(10),DATEADD(day,-?,CONVERT(date,SYSDATETIME())),111), COUNT_BIG(1), ISNULL(SUM(ISNULL(p.grand_total,p.total_amount)),0) FROM dbo.meelano_prefactors p" + where;
                try (PreparedStatement ps = c.prepareStatement(sql)) {
                    ps.setInt(1, offset);
                    ps.setInt(2, offset);
                    int idx = 3;
                    for (Object v : params) ps.setObject(idx++, v);
                    try (ResultSet r = ps.executeQuery()) {
                        JSONObject o = new JSONObject();
                        o.put("label", "-" + formatNumber(offset));
                        o.put("count", 0);
                        o.put("value", 0);
                        if (r.next()) {
                            String label = stringOr(r.getString(1), "");
                            if (label.length() >= 5) label = label.substring(Math.max(0, label.length() - 5));
                            o.put("label", stringOr(label, "-" + formatNumber(offset)));
                            o.put("count", r.getLong(2));
                            o.put("value", r.getDouble(3));
                        }
                        arr.put(o);
                    }
                }
            }
        } catch (Exception ignored) { }
        return arr;
    }

    private JSONArray queryVisitorPriceTierBreakdown(Connection c, String window) {
        JSONArray arr = new JSONArray();
        try {
            ensurePrefactorTables(c);
            List<Object> params = new ArrayList<>();
            String where = prefactorScopeWhere("p", params);
            String and = where.isEmpty() ? " WHERE " : where + " AND ";
            String sql = "SELECT ISNULL(NULLIF(i.price_tier,N''),N'1'), COUNT_BIG(1), ISNULL(SUM(i.amount),0) " +
                    "FROM dbo.meelano_prefactor_items i INNER JOIN dbo.meelano_prefactors p ON p.id=i.prefactor_id" +
                    and + prefactorWindowCondition("p", window) + " GROUP BY ISNULL(NULLIF(i.price_tier,N''),N'1') ORDER BY 1";
            try (PreparedStatement ps = c.prepareStatement(sql)) {
                setParams(ps, params);
                try (ResultSet r = ps.executeQuery()) {
                    while (r.next()) {
                        String tier = stringOr(r.getString(1), "1");
                        JSONObject o = new JSONObject();
                        o.put("tier", tier);
                        o.put("label", "2".equals(tier) ? "قیمت ۲" : "قیمت ۱");
                        o.put("count", r.getLong(2));
                        o.put("value", r.getDouble(3));
                        arr.put(o);
                    }
                }
            }
            if (arr.length() == 0) {
                JSONObject p1 = new JSONObject(); p1.put("tier", "1"); p1.put("label", "قیمت ۱"); p1.put("count", 0); p1.put("value", 0); arr.put(p1);
                JSONObject p2 = new JSONObject(); p2.put("tier", "2"); p2.put("label", "قیمت ۲"); p2.put("count", 0); p2.put("value", 0); arr.put(p2);
            }
        } catch (Exception ignored) { }
        return arr;
    }

    private JSONArray queryVisitorGoals(Connection c, Integer vid) {
        JSONArray arr = new JSONArray();
        try {
            if (c == null || vid == null || vid <= 0 || !tableExists(c, "vis_goals")) return arr;
            Set<String> cols = columns(c, "vis_goals");
            String vis = resolveFlexible(cols, "vis_rdf", "VisitorID", "visid", "visitor", "shvis");
            String title = resolveFlexible(cols, "title", "name", "Name", "goal_name", "شرح", "sharh");
            String target = resolveFlexible(cols, "target", "amount", "mablagh", "goal", "هدف");
            String done = resolveFlexible(cols, "done", "achieved", "sale", "forosh", "انجام");
            String date = resolveFlexible(cols, "date", "tarikh", "DATE");
            if (vis == null) return arr;
            String sql = "SELECT TOP (6) " + (date == null ? "CAST(NULL AS nvarchar(30))" : "TRY_CONVERT(nvarchar(30),[" + date + "])") + ", " + (title == null ? "N'هدف فروش'" : "TRY_CONVERT(nvarchar(220),[" + title + "])") + ", " + (target == null ? "CAST(0 AS decimal(19,2))" : "TRY_CONVERT(decimal(19,2),[" + target + "])") + ", " + (done == null ? "CAST(0 AS decimal(19,2))" : "TRY_CONVERT(decimal(19,2),[" + done + "])") + " FROM dbo.vis_goals WHERE TRY_CONVERT(nvarchar(100),[" + vis + "])=? ORDER BY 1 DESC";
            try (PreparedStatement ps = c.prepareStatement(sql)) { ps.setString(1, String.valueOf(vid)); try (ResultSet r = ps.executeQuery()) { while (r.next()) { JSONObject o = new JSONObject(); o.put("date", stringOr(r.getString(1), "—")); o.put("title", stringOr(r.getString(2), "هدف فروش")); o.put("target", r.getDouble(3)); o.put("done", r.getDouble(4)); arr.put(o); } } }
        } catch (Exception ignored) { }
        return arr;
    }

    private void renderVisitorEditionDashboard(JSONObject data) {
        if (data == null) data = new JSONObject();
        content.removeAllViews();
        // The big "start visit" greeting was removed from home; visiting starts from the «ویزیت» tab.
        addVisitorTodayOverview(data);
        addVisitorNextCustomerCard();
        addVisitorHomeCharts(data);
        if (cartHasItems()) addVisitorCartSnapshotCard(); // an empty cart card only repeated the cart page (G8)
        addVisitorQuietOpportunitiesCard(data);
        addVisitorMoreGatewayCard();
    }

    private double visitorConfiguredGoalTarget(JSONObject data) {
        JSONArray goals = data == null ? null : data.optJSONArray("goals");
        JSONObject g = firstObject(goals);
        double target = g == null ? 0 : g.optDouble("target", 0);
        return target > 0 ? target : 0;
    }

    private double visitorTodayPrefactorAmount(JSONObject data) {
        JSONObject today = data == null ? null : data.optJSONObject("todayPrefactors");
        JSONObject score = data == null ? null : data.optJSONObject("dailyScore");
        JSONObject sales = data == null ? null : data.optJSONObject("sales");
        double pref = today == null ? 0 : today.optDouble("amount", 0);
        if (pref <= 0 && score != null) pref = score.optDouble("prefactorAmount", 0);
        if (pref <= 0 && sales != null) pref = sales.optDouble("total", 0);
        return Math.max(0, pref);
    }

    private long visitorTodayPrefactorCount(JSONObject data) {
        JSONObject today = data == null ? null : data.optJSONObject("todayPrefactors");
        JSONObject score = data == null ? null : data.optJSONObject("dailyScore");
        if (today != null && today.has("count")) return today.optLong("count", 0);
        return score == null ? 0 : score.optLong("prefactors", 0);
    }

    private long visitorTodayVisitCount(JSONObject data) {
        JSONObject score = data == null ? null : data.optJSONObject("dailyScore");
        return (score == null ? 0 : score.optLong("visits", 0)) + localVisitsTodayCount();
    }

