    private JSONArray visitorLocalProducts() {
        try {
            String raw = prefs == null ? "" : prefs.getString(KEY_VISITOR_LOCAL_PRODUCTS, "");
            return raw == null || raw.trim().isEmpty() ? new JSONArray() : new JSONArray(raw);
        } catch (Exception ignored) { return new JSONArray(); }
    }

    private void saveVisitorLocalProducts(JSONArray arr) {
        if (prefs != null) prefs.edit().putString(KEY_VISITOR_LOCAL_PRODUCTS, arr == null ? "[]" : arr.toString()).apply();
    }

    private boolean localProductMatches(JSONObject p, String query, String filter) {
        if (p == null) return false;
        String q = query == null ? "" : query.trim();
        if (!q.isEmpty()) {
            String hay = normalizeDigits((p.optString("نام", "") + " " + p.optString("کد", "") + " " + p.optString("بارکد", "") + " " + p.optString("گروه", "")).toLowerCase(Locale.US));
            String needle = normalizeDigits(q.toLowerCase(Locale.US));
            if (!hay.contains(needle)) return false;
        }
        String f = filter == null ? "all" : filter;
        if ("stock".equals(f)) return jsonDouble(p, "موجودی", 0) > 0;
        if ("price2".equals(f)) return jsonDouble(p, "قیمت_فروش۲", 0) > 0;
        if ("low".equals(f)) return jsonDouble(p, "موجودی", 0) <= 0;
        if ("priced".equals(f)) return jsonDouble(p, "قیمت_فروش", 0) > 0 || jsonDouble(p, "قیمت_فروش۲", 0) > 0;
        return true;
    }

    private void normalizeVisitorExactPrices(JSONArray rows) {
        if (rows == null) return;
        for (int i = 0; i < rows.length(); i++) {
            JSONObject r = rows.optJSONObject(i); if (r == null) continue;
            double p1 = Math.max(0, jsonDouble(r, "قیمت_فروش", 0));
            double p2 = Math.max(0, jsonDouble(r, "قیمت_فروش۲", 0));
            try {
                r.put("قیمت_فروش", p1);
                applyPrice2Rule(r);
            } catch (Exception ignored) { }
        }
    }

    private JSONArray mergeVisitorLocalProducts(JSONArray rows, String query, String filter) {
        JSONArray out = new JSONArray();
        JSONArray locals = visitorLocalProducts();
        for (int i = locals.length() - 1; i >= 0; i--) {
            JSONObject p = locals.optJSONObject(i);
            if (localProductMatches(p, query, filter)) out.put(p);
        }
        for (int i = 0; rows != null && i < rows.length(); i++) out.put(rows.optJSONObject(i));
        return out;
    }

    private JSONArray visitorProductSearchFilteredRows(JSONArray rows, String query, String filter) {
        JSONArray out = new JSONArray();
        String q = query == null ? "" : query.trim();
        String f = filter == null || filter.trim().isEmpty() ? "all" : filter;
        List<String> variants = searchVariants(q);
        for (int i = 0; rows != null && i < rows.length(); i++) {
            JSONObject r = rows.optJSONObject(i);
            if (r == null) continue;
            if (!q.isEmpty()) {
                String hay = normalizeDigits((r.optString("نام", "") + " " + r.optString("کد", "") + " " + r.optString("بارکد", "") + " " + r.optString("گروه", "") + " " + r.optString("واحد", "")).toLowerCase(Locale.US));
                boolean match = false;
                for (String v : variants) {
                    String needle = normalizeDigits(v == null ? "" : v).toLowerCase(Locale.US).trim();
                    if (!needle.isEmpty() && hay.contains(needle)) { match = true; break; }
                }
                if (!match) continue;
            }
            double stock = jsonDouble(r, "موجودی", 0);
            double p1 = jsonDouble(r, "قیمت_فروش", 0);
            double p2 = jsonDouble(r, "قیمت_فروش۲", 0);
            double sold = jsonDouble(r, "تعداد_فروش", 0) + jsonDouble(r, "مبلغ_فروش", 0);
            double bought = jsonDouble(r, "تعداد_خرید", 0) + jsonDouble(r, "مبلغ_خرید", 0);
            double pack = jsonDouble(r, "تعداد_در_بسته", 1);
            String img = r.optString("تصویر", "");
            if ("stock".equals(f) && stock <= 0) continue;
            if ("low".equals(f) && stock > 0) continue;
            if ("idle".equals(f) && (sold > 0 || bought > 0)) continue;
            if ("priced".equals(f) && !(p1 > 0 || p2 > 0)) continue;
            if ("price2".equals(f) && !(p2 > 0)) continue;
            if ("image".equals(f) && (img == null || img.trim().length() <= 20)) continue;
            if ("package".equals(f) && !(pack > 1)) continue;
            if ("top".equals(f) && !(sold > 0)) continue;
            out.put(r);
        }
        return out;
    }

