    private void showCartCustomerPicker(String search) { showCartCustomerPicker(search, false); }

    private void showCartCustomerPicker(String search, boolean force) {
        String q = search == null ? "" : search.trim();
        String key = normalizeDigits(q).toLowerCase(Locale.US);
        if (!force && customersCacheJson != null && !customersCacheJson.trim().isEmpty()) {
            try { renderCartCustomerPicker(q, cartCustomerRowsFromCachedCustomers(q)); return; } catch (Exception ignored) { }
        }
        if (!force && cartCustomerPickerCache.containsKey(key)) {
            try { renderCartCustomerPicker(q, new JSONArray(cartCustomerPickerCache.get(key))); return; } catch (Exception ignored) { }
        }
        runDb(() -> queryCartCustomers(q), new DbCallback() {
            @Override public void ok(String body) { try { cartCustomerPickerCache.put(key, body); renderCartCustomerPicker(q, new JSONArray(body)); } catch (Exception e) { showPageError("انتخاب مشتری", e, () -> renderCartPage()); } }
            @Override public void fail(Exception e) { showPageError("انتخاب مشتری", e, () -> renderCartPage()); }
        });
    }

    private boolean cartCustomerMatchesQuick(JSONObject r, String filter) {
        if (r == null) return false;
        String f = filter == null ? "all" : filter;
        if ("debt".equals(f)) return r.optDouble("balance", 0) > 0;
        if ("top".equals(f)) return r.optDouble("totalSales", 0) > 0 || r.optLong("invoiceCount", 0) > 0;
        if ("inactive".equals(f)) return customerIsInactive(r);
        if ("route_today".equals(f)) return customerOnTodayRoute(r);
        return true;
    }

    private int cartCustomerQuickCount(JSONArray rows, String filter) {
        int count = 0;
        if (rows != null) for (int i = 0; i < rows.length(); i++) if (cartCustomerMatchesQuick(rows.optJSONObject(i), filter)) count++;
        return count;
    }

    private JSONArray cartCustomerQuickRows(JSONArray rows, String filter) {
        JSONArray out = new JSONArray();
        if (rows == null) return out;
        for (int i = 0; i < rows.length(); i++) { JSONObject r = rows.optJSONObject(i); if (cartCustomerMatchesQuick(r, filter)) out.put(r); }
        return out;
    }

    private JSONArray cartCustomerRowsFromCachedCustomers(String search) {
        JSONArray out = new JSONArray();
        try {
            JSONArray cached = new JSONArray(customersCacheJson == null || customersCacheJson.trim().isEmpty() ? "[]" : customersCacheJson);
            JSONArray filtered = customerSearchFilteredRows(cached, search);
            for (int i = 0; i < filtered.length(); i++) {
                JSONObject r = filtered.optJSONObject(i); if (r == null) continue;
                out.put(cartCustomerFromRow(r));
            }
        } catch (Exception ignored) { }
        return out;
    }

    /** Converts a row of the customer list into the customer object used by the cart. */
    private JSONObject cartCustomerFromRow(JSONObject r) {
        JSONObject o = new JSONObject();
        try {
            o.put("code", safeDisplayText(r.opt("کد"), ""));
            o.put("name", safeDisplayText(r.opt("نام"), "مشتری"));
            o.put("balance", r.optDouble("مانده", 0));
            o.put("phone", firstPhone(r));
            o.put("invoiceCount", r.optInt("تعداد_فاکتور", 0));
            o.put("totalSales", r.optDouble("جمع_فروش", 0));
            o.put("lastSale", r.optString("آخرین_خرید", ""));
            o.put("creditLimit", r.optDouble("اعتبار", 0));
            o.put("address", cleanCustomerAddress(r.optString("نشانی", "")));
            o.put("blocked", false);
            o.put("route", r.optString("مسیر", ""));
        } catch (Exception ignored) { }
        return o;
    }

    private final Set<String> skippedNextCustomers = new HashSet<>();

    /**
     * Suggests the next customer to visit: not visited today, not the current cart customer, not skipped;
     * customers with purchase history whose last purchase is oldest come first.
     */
    private JSONObject nextCustomerSuggestion() {
        try {
            JSONArray rows = new JSONArray(customersCacheJson == null || customersCacheJson.trim().isEmpty() ? "[]" : customersCacheJson);
            Set<String> visitedToday = new HashSet<>();
            String today = todayDateText();
            JSONArray visits = localVisitResults();
            for (int i = 0; i < visits.length(); i++) {
                JSONObject v = visits.optJSONObject(i);
                if (v != null && v.optString("createdLocal", "").startsWith(today)) visitedToday.add(v.optString("customerCode", ""));
            }
            JSONArray log = todayVisitLog();
            for (int i = 0; i < log.length(); i++) { JSONObject v = log.optJSONObject(i); if (v != null) visitedToday.add(v.optString("code", "")); }
            String current = visitorCartCustomer == null ? "" : visitorCartCustomer.optString("code", "");
            JSONObject best = null; String bestKey = null;
            for (int i = 0; i < rows.length(); i++) {
                JSONObject r = rows.optJSONObject(i); if (r == null) continue;
                String code = safeDisplayText(r.opt("کد"), "");
                if (code.isEmpty() || code.equals(current) || visitedToday.contains(code) || skippedNextCustomers.contains(code)) continue;
                boolean hasHistory = r.optInt("تعداد_فاکتور", 0) > 0;
                String last = r.optString("آخرین_خرید", "");
                // "0" sorts before "1": buyers first, then the oldest last purchase.
                String key = (hasHistory ? "0" : "1") + (last.isEmpty() ? "0000" : toLatinDigits(last));
                if (bestKey == null || key.compareTo(bestKey) < 0) { best = r; bestKey = key; }
            }
            return best;
        } catch (Exception ignored) { return null; }
    }

    private String toLatinDigits(String s) {
        if (s == null) return "";
        StringBuilder b = new StringBuilder(s.length());
        for (char ch : s.toCharArray()) {
            if (ch >= '۰' && ch <= '۹') b.append((char) ('0' + (ch - '۰')));
            else if (ch >= '٠' && ch <= '٩') b.append((char) ('0' + (ch - '٠')));
            else b.append(ch);
        }
        return b.toString();
    }

