    private String queryCartCustomers(String search) throws Exception {
        try (Connection c = openConnection()) {
            Set<String> cols = columns(c, "CUSTOMERS");
            String shmo = resolveFlexible(cols, "SHMO", "shmo", "CustomerCode", "customer_code", "code", "Code", "کد");
            String name = resolveFlexible(cols, "MONAME", "Name", "CusName", "CustomerName", "name", "نام", "نام_مشتری");
            String balance = resolveFlexible(cols, "man", "Balance", "Mandeh", "mande", "مانده");
            String phone = resolveFlexible(cols, "cell", "mobile", "Mobile", "tell1", "tel1", "phone", "Phone", "تلفن", "موبایل");
            String credit = resolveFlexible(cols, "credit", "Credit", "credit_limit", "Limit", "etebar", "Etebar", "سقف_اعتبار");
            String address = resolveFlexible(cols, "address", "Address", "addr", "Adress", "آدرس", "نشانی");
            String blocked = resolveFlexible(cols, "blocked", "blacklist", "lock", "is_blocked", "active", "Active");
            String route = resolveFlexible(cols, "route", "Route", "masir", "Masir", "مسیر", "مسير", "day", "Day", "visit_day", "VisitDay", "rooz", "Rooz", "روز");
            if (shmo == null) return "[]";
            String label = name == null ? "TRY_CONVERT(nvarchar(220),c.[" + shmo + "])" : "TRY_CONVERT(nvarchar(220),c.[" + name + "])";
            List<String> where = new ArrayList<>(); List<Object> params = new ArrayList<>();
            String scope = customerScopeCondition(cols, "c", params); if (!scope.isEmpty()) where.add(scope);
            if (search != null && !search.trim().isEmpty()) {
                List<String> parts = new ArrayList<>();
                for (String sv : searchVariants(search.trim())) for (String col : new String[]{shmo, name, phone}) if (col != null) { parts.add("TRY_CONVERT(nvarchar(400),c.[" + col + "]) LIKE N'%' + ? + N'%'"); params.add(sv); }
                if (!parts.isEmpty()) where.add("(" + join(parts, " OR ") + ")");
            }
            String sql = "SELECT TOP (5) TRY_CONVERT(nvarchar(100),c.[" + shmo + "]), " + label + ", " +
                    (balance == null ? "CAST(0 AS decimal(19,2))" : "TRY_CONVERT(decimal(19,2),c.[" + balance + "])") + ", " +
                    (phone == null ? "CAST(NULL AS nvarchar(100))" : "TRY_CONVERT(nvarchar(100),c.[" + phone + "])") + ", " +
                    (credit == null ? "CAST(0 AS decimal(19,2))" : "TRY_CONVERT(decimal(19,2),c.[" + credit + "])") + ", " +
                    (address == null ? "CAST(NULL AS nvarchar(500))" : "TRY_CONVERT(nvarchar(500),c.[" + address + "])") + ", " +
                    (blocked == null ? "CAST(NULL AS nvarchar(40))" : "TRY_CONVERT(nvarchar(40),c.[" + blocked + "])") + ", " +
                    (route == null ? "CAST(NULL AS nvarchar(100))" : "TRY_CONVERT(nvarchar(100),c.[" + route + "])") +
                    " FROM dbo.CUSTOMERS c " + (where.isEmpty() ? "" : " WHERE " + join(where, " AND ")) + " ORDER BY " + label;
            JSONArray arr = new JSONArray();
            try (PreparedStatement ps = c.prepareStatement(sql)) {
                setParams(ps, params);
                try (ResultSet r = ps.executeQuery()) {
                    while (r.next()) {
                        JSONObject o = new JSONObject();
                        o.put("code", stringOr(r.getString(1), "")); o.put("name", stringOr(r.getString(2), "مشتری"));
                        o.put("balance", r.getDouble(3)); o.put("phone", stringOr(r.getString(4), ""));
                        o.put("invoiceCount", 0); o.put("totalSales", 0); o.put("lastSale", "");
                        o.put("creditLimit", r.getDouble(5)); o.put("address", stringOr(r.getString(6), ""));
                        String bv = stringOr(r.getString(7), ""); o.put("blockedRaw", bv);
                        String bl = normalizeDigits(bv).toLowerCase(Locale.US);
                        o.put("blocked", bl.equals("0") || bl.contains("blocked") || bl.contains("lock") || bl.contains("مسدود"));
                        o.put("route", stringOr(r.getString(8), "")); arr.put(o);
                    }
                }
            }
            return arr.toString();
        }
    }

    private JSONObject currentCartSnapshot(String status) {
        syncCartFormInputs();
        return buildCartSnapshot(status);
    }

    /** Snapshot of the in-memory cart without reading the cart page's input fields. */
    private JSONObject buildCartSnapshot(String status) {
        JSONObject d = new JSONObject();
        try {
            if (visitorCartDraftId == null || visitorCartDraftId.trim().isEmpty()) visitorCartDraftId = "MEELANO-" + System.currentTimeMillis();
            d.put("clientUuid", visitorCartDraftId);
            d.put("items", new JSONArray(visitorCartItems.toString()));
            d.put("customer", visitorCartCustomer == null ? JSONObject.NULL : new JSONObject(visitorCartCustomer.toString()));
            d.put("customerCode", visitorCartCustomer == null ? "" : visitorCartCustomer.optString("code", ""));
            d.put("customerName", visitorCartCustomer == null ? "" : visitorCartCustomer.optString("name", ""));
            d.put("notes", visitorCartNotes); d.put("signature", visitorCartSignature);
            d.put("settlement", visitorCartSettlement); d.put("deliveryDate", visitorCartDeliveryDate); d.put("address", visitorCartAddress); d.put("paymentRef", visitorCartPaymentRef);
            d.put("subtotal", cartSubtotal()); d.put("lineDiscount", cartLineDiscounts()); d.put("globalDiscount", visitorCartGlobalDiscount); d.put("taxPercent", visitorCartTaxPercent); d.put("taxAmount", cartTaxAmount()); d.put("grandTotal", cartTotal());
            d.put("status", status == null ? finalCartStatus() : status); d.put("approvalReason", cartApprovalReason()); d.put("createdLocal", nowText());
            d.put("visitor", currentAccountName()); d.put("visitorId", currentVisitorScopeId() == null ? "" : String.valueOf(currentVisitorScopeId()));
        } catch (Exception ignored) { }
        return d;
    }

    // ---------------------------------------------------------------------------------------------
    // Cart autosave. Android may kill the app in the background (typically while the visitor is in
    // the camera/gallery or a barcode scanner). The cart is written to preferences on every change
    // and in onStop(), and restored automatically after the same account logs in again.
    // ---------------------------------------------------------------------------------------------
    private static final String KEY_CART_AUTOSAVE = "visitor_cart_autosave_json";
    private static final long CART_AUTOSAVE_MAX_AGE_MS = 7L * 24 * 60 * 60 * 1000;
    private boolean cartAutosaveRestoreChecked = false;

    private boolean cartIsEmptyForAutosave() {
        return (visitorCartItems == null || visitorCartItems.length() == 0) && visitorCartCustomer == null;
    }

    private void autosaveCart(boolean readCartInputs) {
        if (prefs == null || designPreview || session == null) return;
        try {
            if (readCartInputs && "cart".equals(activePage)) syncCartFormInputs();
            if (cartIsEmptyForAutosave()) { prefs.edit().remove(KEY_CART_AUTOSAVE).apply(); return; }
            JSONObject wrap = new JSONObject();
            wrap.put("owner", currentAccountName());
            wrap.put("savedAt", System.currentTimeMillis());
            wrap.put("snap", buildCartSnapshot("draft"));
            prefs.edit().putString(KEY_CART_AUTOSAVE, wrap.toString()).apply();
        } catch (Exception ignored) { }
    }

    private void maybeRestoreAutosavedCart() {
        if (cartAutosaveRestoreChecked || prefs == null || designPreview || session == null) return;
        cartAutosaveRestoreChecked = true;
        try {
            String raw = prefs.getString(KEY_CART_AUTOSAVE, "");
            if (raw == null || raw.trim().isEmpty() || !cartIsEmptyForAutosave()) return;
            JSONObject wrap = new JSONObject(raw);
            if (!currentAccountName().equalsIgnoreCase(wrap.optString("owner", ""))) return;
            long age = System.currentTimeMillis() - wrap.optLong("savedAt", 0);
            if (age < 0 || age > CART_AUTOSAVE_MAX_AGE_MS) { prefs.edit().remove(KEY_CART_AUTOSAVE).apply(); return; }
            JSONObject snap = wrap.optJSONObject("snap");
            if (snap == null) return;
            restoreCartSnapshot(snap);
            int lines = visitorCartItems == null ? 0 : visitorCartItems.length();
            if (lines > 0 || visitorCartCustomer != null) {
                showNotice(lines > 0 ? "سبد قبلی شما (" + formatNumber(lines) + " قلم) به‌طور خودکار بازیابی شد." : "مشتری انتخاب‌شده قبلی بازیابی شد.", true);
            }
        } catch (Exception ignored) { }
    }

    @Override
    protected void onStop() {
        autosaveCart(true);
        super.onStop();
    }

    // ---------------------------------------------------------------------------------------------
    // Security: auto sign-out after inactivity + fingerprint login for visitors.
    // ---------------------------------------------------------------------------------------------
    private static final String KEY_AUTO_LOCK_MIN = "auto_lock_minutes";
    private static final String KEY_BIO_USER = "visitor_bio_user";
    private static final String KEY_BIO_PASS = "visitor_bio_pass";
    private static final String KEY_BIO_ASKED = "visitor_bio_asked";
    private static final int DEFAULT_AUTO_LOCK_MIN = 60;
    private long lastUserInteractionAt = System.currentTimeMillis();
    private final android.os.Handler lockHandler = new android.os.Handler(android.os.Looper.getMainLooper());
    private final Runnable lockTick = new Runnable() {
        @Override public void run() { checkAutoLock(); lockHandler.postDelayed(this, 60_000L); }
    };

    @Override
    public void onUserInteraction() {
        super.onUserInteraction();
        lastUserInteractionAt = System.currentTimeMillis();
    }

    @Override
    protected void onResume() {
        super.onResume();
        checkAutoLock();
        lockHandler.removeCallbacks(lockTick);
        lockHandler.postDelayed(lockTick, 60_000L);
        maybeCheckForAppUpdate(false);
        autoSendOfflineQueue();
    }

    @Override
    protected void onPause() {
        lockHandler.removeCallbacks(lockTick);
        super.onPause();
    }

    private int autoLockMinutes() { return prefs == null ? DEFAULT_AUTO_LOCK_MIN : prefs.getInt(KEY_AUTO_LOCK_MIN, DEFAULT_AUTO_LOCK_MIN); }

    private void checkAutoLock() {
        int min = autoLockMinutes();
        if (min <= 0 || session == null || designPreview) return;
        if (System.currentTimeMillis() - lastUserInteractionAt < min * 60_000L) return;
        lastUserInteractionAt = System.currentTimeMillis();
        showLogin("برای امنیت، بعد از " + faDigits(String.valueOf(min)) + " دقیقه بی‌کاری از حساب خارج شدید. سبد شما ذخیره شده است.");
    }

    private boolean biometricAvailable() {
        if (Build.VERSION.SDK_INT < 28) return false;
        try {
            if (Build.VERSION.SDK_INT >= 29) {
                android.hardware.biometrics.BiometricManager bm = getSystemService(android.hardware.biometrics.BiometricManager.class);
                return bm != null && bm.canAuthenticate() == android.hardware.biometrics.BiometricManager.BIOMETRIC_SUCCESS;
            }
            return getPackageManager().hasSystemFeature(PackageManager.FEATURE_FINGERPRINT);
        } catch (Exception ignored) { return false; }
    }

    private boolean visitorBiometricEnabled() {
        return prefs != null && prefs.getString(KEY_BIO_PASS, "").startsWith("ks:") && !prefs.getString(KEY_BIO_USER, "").isEmpty();
    }

    /** The password is encrypted with a key kept in the phone's secure hardware (Android Keystore). */
    private boolean storeVisitorBiometric(String user, String password) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) return false;
        try {
            String enc = keystoreEncrypt(Base64.encodeToString(password.getBytes(StandardCharsets.UTF_8), Base64.NO_WRAP));
            prefs.edit().putString(KEY_BIO_USER, user).putString(KEY_BIO_PASS, "ks:" + enc).apply();
            return true;
        } catch (Exception ex) { return false; }
    }

    private String readVisitorBiometricPassword() {
        try {
            String v = prefs.getString(KEY_BIO_PASS, "");
            if (!v.startsWith("ks:")) return "";
            return new String(Base64.decode(keystoreDecrypt(v.substring(3)), Base64.NO_WRAP), StandardCharsets.UTF_8);
        } catch (Exception ex) { return ""; }
    }

    private void clearVisitorBiometric() {
        if (prefs != null) prefs.edit().remove(KEY_BIO_USER).remove(KEY_BIO_PASS).apply();
    }

    /** After a successful password login: offer fingerprint login once, or refresh the stored password. */
    private void afterVisitorPasswordLogin(String user, String password) {
        if (!VISITOR_EDITION || designPreview || prefs == null || !biometricAvailable()) return;
        if (visitorBiometricEnabled()) {
            if (user.equals(prefs.getString(KEY_BIO_USER, ""))) storeVisitorBiometric(user, password); // password may have changed
            else clearVisitorBiometric();
            return;
        }
        if (prefs.getBoolean(KEY_BIO_ASKED, false)) return;
        prefs.edit().putBoolean(KEY_BIO_ASKED, true).apply();
        AlertDialog dlg = new MeelanoDialogBuilder()
                .setTitle("ورود با اثر انگشت")
                .setMessage("دفعه بعد بدون نوشتن رمز، با اثر انگشت وارد شوید؟\nرمز شما به‌صورت رمزشده فقط روی همین گوشی نگه داشته می‌شود.")
                .setNegativeButton("نه، ممنون", null)
                .setPositiveButton("فعال کن", (d, w) -> showNotice(storeVisitorBiometric(user, password) ? "ورود با اثر انگشت فعال شد." : "فعال کردن اثر انگشت روی این گوشی ممکن نشد.", false))
                .create();
        dlg.setOnShowListener(d -> styleMeelanoDialog(dlg, GOLD));
        dlg.show();
    }

    private void startVisitorBiometricLogin(EditText username, EditText password, Runnable login) {
        if (Build.VERSION.SDK_INT < 28) return;
        try {
            CancellationSignal signal = new CancellationSignal();
            BiometricPrompt prompt = new BiometricPrompt.Builder(this)
                    .setTitle("ورود به " + editionTitle())
                    .setSubtitle(prefs.getString(KEY_BIO_USER, ""))
                    .setNegativeButton("ورود با رمز", getMainExecutor(), (d, which) -> password.requestFocus())
                    .build();
            prompt.authenticate(signal, getMainExecutor(), new BiometricPrompt.AuthenticationCallback() {
                @Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult result) {
                    String pass = readVisitorBiometricPassword();
                    if (pass.isEmpty()) { clearVisitorBiometric(); showNotice("لطفاً یک بار با رمز وارد شوید.", false); return; }
                    username.setText(prefs.getString(KEY_BIO_USER, ""));
                    password.setText(pass);
                    login.run();
                }
                @Override public void onAuthenticationError(int errorCode, CharSequence errString) { }
            });
        } catch (Exception ex) { showNotice("اثر انگشت در دسترس نیست؛ با رمز وارد شوید.", false); }
    }

    // ---------------------------------------------------------------------------------------------
    // "New version available" check. CI writes apk/latest.json next to each APK.
    // ---------------------------------------------------------------------------------------------
    private static final String UPDATE_MANIFEST_URL = "https://github.com/Companymeelano/Newhamrah/raw/arena/01a0e474-newhamrah/apk/latest.json";
    private static final String KEY_UPDATE_CHECKED_AT = "update_checked_at";
    private static final String KEY_UPDATE_LATEST = "update_latest_json";
    private static final long UPDATE_CHECK_INTERVAL_MS = 12L * 60 * 60 * 1000;

    private long installedVersionCode() {
        try {
            android.content.pm.PackageInfo pi = getPackageManager().getPackageInfo(getPackageName(), 0);
            return Build.VERSION.SDK_INT >= 28 ? pi.getLongVersionCode() : pi.versionCode;
        } catch (Exception ignored) { return 0; }
    }

    /** Latest version seen on the server, or null when unknown / not newer than this install. */
    private JSONObject pendingAppUpdate() {
        try {
            String raw = prefs == null ? "" : prefs.getString(KEY_UPDATE_LATEST, "");
            if (raw == null || raw.isEmpty()) return null;
            JSONObject o = new JSONObject(raw);
            return o.optLong("versionCode", 0) > installedVersionCode() ? o : null;
        } catch (Exception ignored) { return null; }
    }

    private void maybeCheckForAppUpdate(boolean manual) {
        if (prefs == null || designPreview) return;
        long last = prefs.getLong(KEY_UPDATE_CHECKED_AT, 0);
        if (!manual && System.currentTimeMillis() - last < UPDATE_CHECK_INTERVAL_MS) return;
        prefs.edit().putLong(KEY_UPDATE_CHECKED_AT, System.currentTimeMillis()).apply();
        // Own thread: the single DB executor must never wait on a slow internet request.
        new Thread(() -> {
            String body = null;
            java.net.HttpURLConnection conn = null;
            try {
                conn = (java.net.HttpURLConnection) new java.net.URL(STORE_EDITION ? STORE_UPDATE_MANIFEST_URL : UPDATE_MANIFEST_URL).openConnection();
                conn.setConnectTimeout(8000); conn.setReadTimeout(8000); conn.setInstanceFollowRedirects(true);
                if (conn.getResponseCode() == 200) {
                    try (java.io.InputStream in = conn.getInputStream()) {
                        ByteArrayOutputStream out = new ByteArrayOutputStream(); byte[] buf = new byte[2048]; int n;
                        while ((n = in.read(buf)) > 0 && out.size() < 16_384) out.write(buf, 0, n);
                        body = new String(out.toByteArray(), StandardCharsets.UTF_8);
                    }
                }
            } catch (Exception ignored) {
            } finally { if (conn != null) conn.disconnect(); }
            final String result = body;
            runOnUiThread(() -> {
                try {
                    if (result != null) { new JSONObject(result.trim()); prefs.edit().putString(KEY_UPDATE_LATEST, result.trim()).apply(); }
                } catch (Exception ignored) { }
                JSONObject up = pendingAppUpdate();
                if (up != null) showNotice("نسخه جدید " + faDigits(up.optString("versionName", "")) + " آماده است.", true, "دانلود", () -> openAppUpdate(up));
                else if (manual) showNotice(result == null ? "بررسی نسخه جدید ممکن نشد؛ اینترنت را بررسی کنید." : "برنامه شما به‌روز است.", false);
                if (manual && "settings".equals(activePage)) renderVisitorEditionSettings();
            });
        }, "meelano-update-check").start();
    }

    private void openAppUpdate(JSONObject up) {
        try { startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(up.optString("url", "")))); }
        catch (Exception ex) { showNotice("باز کردن لینک دانلود ممکن نشد.", false); }
    }

