    private String preflightCartSnapshot(JSONObject snap) throws Exception {
        try (Connection c = openConnection()) {
            ensurePrefactorTables(c);
            return checkCartSnapshotAgainstInventory(c, snap.optJSONArray("items"), false).toString();
        }
    }

    private void submitCartPrefactor(String status) { submitCartSnapshot(currentCartSnapshot(status == null ? finalCartStatus() : status), status == null ? finalCartStatus() : status, true); }

    private void submitCartSnapshot(JSONObject snap, String status, boolean clearOnSuccess) {
        if (snap == null || snap.optJSONArray("items") == null || snap.optJSONArray("items").length() == 0) { showNotice("سبد خالی است.", false); return; }
        if (snap.optString("customerCode", "").trim().isEmpty()) { showNotice("ابتدا مشتری را انتخاب کنید.", true); return; }
        runDb(() -> insertPrefactorSnapshot(snap, status), new DbCallback() {
            @Override public void ok(String body) { if ("draft".equals(status)) showNotice("پیش‌نویس ذخیره شد.", true); else if (String.valueOf(body).contains("نرسید")) { final long retryId = lastUnsyncedPrefactorId; showNotice(body, true, "تلاش دوباره", () -> retryAtiranPrefactorSync(retryId)); } else showNotice(body, true); if (clearOnSuccess && !"draft".equals(status)) { removeLocalDraft(snap.optString("clientUuid", "")); resetCartState(); } renderCartPage(); }
            @Override public void fail(Exception e) { if (!"draft".equals(status)) saveOfflinePrefactor(snap, shortError(e)); else showNotice("پیش‌نویس فقط محلی ماند.", true); renderCartPage(); }
        });
    }

    private void resetCartState() {
        visitorCartItems = new JSONArray(); visitorCartCustomer = null; visitorCartNotes = ""; visitorCartSignature = ""; visitorCartDraftId = ""; visitorCartSettlement = "اعتباری"; visitorCartDeliveryDate = ""; visitorCartAddress = ""; visitorCartPaymentRef = ""; visitorCartGlobalDiscount = 0; visitorCartTaxPercent = 0;
        refreshVisitorCartBadge();
    }

    private String insertPrefactor(String status) throws Exception { return insertPrefactorSnapshot(currentCartSnapshot(status), status); }

    private String insertPrefactorSnapshot(JSONObject snap, String status) throws Exception {
        try (Connection c = openConnection()) {
            ensurePrefactorTables(c);
            String uuid = snap.optString("clientUuid", "");
            if (!uuid.trim().isEmpty()) try (PreparedStatement find = c.prepareStatement("SELECT TOP (1) id FROM dbo.meelano_prefactors WHERE client_uuid=?")) { find.setString(1, uuid); try (ResultSet r = find.executeQuery()) { if (r.next()) { long existingId = r.getLong(1); try { syncNativeAtiranPrefactor(c, existingId, snap, snap.optJSONArray("items")); } catch (Exception ignored) { } return prefactorSubmitMessage(c, existingId); } } } catch (Exception ignored) { }
            c.setAutoCommit(false);
            try {
                // ارسال ویزیتور باید سریع باشد؛ کنترل سنگین موجودی/قیمت قبلاً از کالا انجام شده و اینجا باعث تاخیر ثبت می‌شد.
                long id;
                try (PreparedStatement ps = c.prepareStatement("INSERT INTO dbo.meelano_prefactors(client_uuid,visitor_username,visitor_id,customer_code,customer_name,notes,signature_data,total_amount,status,created_at,updated_at,delivery_date,delivery_address,settlement_type,payment_ref,subtotal_amount,global_discount,tax_percent,tax_amount,grand_total,approval_reason) VALUES(?,?,?,?,?,?,?,?,?,SYSDATETIME(),SYSDATETIME(),?,?,?,?,?,?,?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) {
                    ps.setString(1, uuid); ps.setString(2, currentAccountName()); ps.setString(3, snap.optString("visitorId", "")); ps.setString(4, snap.optString("customerCode", "")); ps.setString(5, snap.optString("customerName", "")); ps.setString(6, snap.optString("notes", "")); ps.setString(7, snap.optString("signature", "")); ps.setDouble(8, snap.optDouble("grandTotal", 0)); ps.setString(9, status == null ? snap.optString("status", "sent") : status);
                    ps.setString(10, snap.optString("deliveryDate", "")); ps.setString(11, snap.optString("address", "")); ps.setString(12, snap.optString("settlement", "")); ps.setString(13, snap.optString("paymentRef", "")); ps.setDouble(14, snap.optDouble("subtotal", 0)); ps.setDouble(15, snap.optDouble("globalDiscount", 0)); ps.setDouble(16, snap.optDouble("taxPercent", 0)); ps.setDouble(17, snap.optDouble("taxAmount", 0)); ps.setDouble(18, snap.optDouble("grandTotal", 0)); ps.setString(19, snap.optString("approvalReason", "")); ps.executeUpdate();
                    try (ResultSet keys = ps.getGeneratedKeys()) { id = keys.next() ? keys.getLong(1) : 0; }
                }
                if (id <= 0) { try (PreparedStatement ps = c.prepareStatement("SELECT ISNULL(MAX(id),0) FROM dbo.meelano_prefactors WHERE visitor_username=?")) { ps.setString(1, currentAccountName()); try (ResultSet r = ps.executeQuery()) { if (r.next()) id = r.getLong(1); } } }
                JSONArray items = snap.optJSONArray("items");
                try (PreparedStatement ps = c.prepareStatement("INSERT INTO dbo.meelano_prefactor_items(prefactor_id,product_code,product_name,unit,qty,price,amount,stock_snapshot,pack_count,price_tier,line_discount,line_note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)")) {
                    for (int i = 0; items != null && i < items.length(); i++) { JSONObject it = items.optJSONObject(i); if (it == null) continue; ps.setLong(1, id); ps.setString(2, it.optString("code", "")); ps.setString(3, it.optString("name", "")); ps.setString(4, it.optString("unit", "")); ps.setDouble(5, it.optDouble("qty", 0)); ps.setDouble(6, it.optDouble("price", 0)); ps.setDouble(7, cartItemNet(it)); ps.setDouble(8, it.optDouble("stock", 0)); ps.setDouble(9, it.optDouble("pack", 1)); ps.setString(10, it.optString("priceTier", "1")); ps.setDouble(11, it.optDouble("lineDiscount", 0)); ps.setString(12, it.optString("note", "")); ps.addBatch(); }
                    ps.executeBatch();
                }
                markPrefactorInvoiceReadiness(c, id, status == null ? snap.optString("status", "sent") : status);
                syncNativeAtiranPrefactor(c, id, snap, items);
                c.commit();
                return prefactorSubmitMessage(c, id);
            } catch (Exception ex) { try { c.rollback(); } catch (Exception ignored) { } throw ex; }
            finally { try { c.setAutoCommit(true); } catch (Exception ignored) { } }
        }
    }


    private static class SqlColumnMeta {
        String name; String type; boolean nullable; boolean identity; boolean computed; boolean hasDefault;
    }

    private static class NativePrefactorTarget {
        String headerTable; String detailTable; String noCol; String refCol; String productCol; String qtyCol; String priceCol; String amountCol; String uuidCol; boolean baseSales; String note;
    }

    private String qi(String name) { return "[" + (name == null ? "" : name.replace("]", "]]")) + "]"; }
    private String dbo(String table) { return "dbo." + qi(table); }

    private Map<String, SqlColumnMeta> sqlColumnMeta(Connection c, String table) throws Exception {
        Map<String, SqlColumnMeta> out = new LinkedHashMap<>();
        String sql = "SELECT col.name, typ.name, col.is_nullable, col.is_identity, col.is_computed, CASE WHEN col.default_object_id IS NULL OR col.default_object_id=0 THEN 0 ELSE 1 END " +
                "FROM sys.columns col JOIN sys.types typ ON typ.user_type_id=col.user_type_id JOIN sys.tables t ON t.object_id=col.object_id JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE s.name=N'dbo' AND t.name=? ORDER BY col.column_id";
        try (PreparedStatement ps = c.prepareStatement(sql)) {
            ps.setString(1, table);
            try (ResultSet r = ps.executeQuery()) {
                while (r.next()) {
                    SqlColumnMeta m = new SqlColumnMeta();
                    m.name = r.getString(1); m.type = stringOr(r.getString(2), "").toLowerCase(Locale.US); m.nullable = r.getBoolean(3); m.identity = r.getBoolean(4); m.computed = r.getBoolean(5); m.hasDefault = r.getBoolean(6);
                    if (m.name != null) out.put(m.name, m);
                }
            }
        }
        return out;
    }

    private String resolveNativeTable(Connection c, String... candidates) {
        for (String t : candidates) if (t != null && tableExists(c, t)) return t;
        boolean detail = false;
        if (candidates != null) for (String t : candidates) {
            String n = normalizeColumnName(t);
            if (containsAny(n, "sub", "detail", "item", "radif", "ریز", "اقلام")) { detail = true; break; }
        }
        return findNativePrefactorTable(c, detail);
    }

    private String findNativePrefactorTable(Connection c, boolean detail) {
        String best = null; int bestScore = 0;
        try (PreparedStatement ps = c.prepareStatement("SELECT t.name FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE s.name=N'dbo'")) {
            try (ResultSet r = ps.executeQuery()) {
                while (r.next()) {
                    String name = r.getString(1); String n = normalizeColumnName(name);
                    if (n.startsWith("meelano") || n.contains("meelano")) continue;
                    boolean pref = containsAny(n, "pish", "prefactor", "preinvoice", "proforma", "پیش", "پرفاکتور", "پروفورما");
                    boolean sale = containsAny(n, "sail", "sale", "sales", "forosh", "forush", "foroosh", "factor", "fact", "invoice", "فروش", "فاکتور", "فاكتور");
                    boolean sub = containsAny(n, "sub", "detail", "details", "item", "items", "radif", "line", "ریز", "اقلام", "ردیف");
                    if (!pref || !sale) continue;
                    if (detail != sub && !(detail && containsAny(n, "subsail", "subfactor", "factoritem", "factitem"))) continue;
                    int score = 20;
                    if (n.contains("sail")) score += 6;
                    if (n.contains("forosh") || n.contains("فروش")) score += 5;
                    if (n.contains("pish")) score += 5;
                    if (n.contains("prefactor")) score += 4;
                    if (detail && sub) score += 6;
                    if (!detail && !sub) score += 4;
                    if (score > bestScore) { bestScore = score; best = name; }
                }
            }
        } catch (Exception ignored) { }
        return best;
    }

    private NativePrefactorTarget discoverNativePrefactorTarget(Connection c) throws Exception {
        // Pre-invoices are never written into the real sales tables (sailfact/subsailfact): a row there is a real invoice.
        String header = resolveNativeTable(c, "sailfact_pish", "sailfactpish", "sailfact_p", "sailfactp", "sail_pish", "sailpish", "pish_sailfact", "pishsailfact", "pre_sailfact", "presailfact", "sailfact_pre", "sailfactpre", "pishfact", "pish_factor", "pishfactor", "preinvoice", "proforma", "prefactor", "پیش_فاکتور", "پيش_فاکتور");
        String detail = resolveNativeTable(c, "subsailfact_pish", "subsailfactpish", "subsailfact_p", "subsailfactp", "sub_sailfact_pish", "subsail_pish", "subpish_sailfact", "pish_subsailfact", "pishsubsailfact", "subpishfact", "sub_pish_factor", "subpishfactor", "preinvoice_items", "proforma_items", "prefactor_items", "ریز_پیش_فاکتور");
        NativePrefactorTarget dedicated = buildNativePrefactorTarget(c, header, detail, false, "جدول اختصاصی پیش‌فاکتور آتیران");
        if (dedicated != null) return dedicated;
        return null;
    }

    private NativePrefactorTarget buildNativePrefactorTarget(Connection c, String header, String detail, boolean baseSales, String note) throws Exception {
        if (c == null || header == null || detail == null || !tableExists(c, header) || !tableExists(c, detail)) return null;
        Set<String> hCols = columns(c, header); Set<String> dCols = columns(c, detail);
        String noCol = nativePrefactorNumberColumn(hCols);
        String refCol = noCol == null ? null : resolveFlexible(dCols, noCol, "shfacfo", "SHFACFO", "shfac", "shfacpish", "shfac_pish", "shpish", "sh_pish", "pish_no", "pish_number", "factor_no", "FactorNo", "fac_no", "No", "no", "number", "Number", "serial", "Serial", "shomare", "شماره");
        String productCol = resolveFlexible(dCols, "SHKA", "shka", "shkala", "KalaCode", "kala_code", "product_code", "ProductCode", "item_code", "code", "Code", "kala", "code_kala", "کد_کالا");
        String qtyCol = resolveFlexible(dCols, "tedad", "TEDAD", "TEDVAH", "qty", "Qty", "quantity", "Quantity", "meghdar", "Meghdar", "meghdar1", "amount_qty", "مقدار", "تعداد");
        if (noCol == null || refCol == null || productCol == null || qtyCol == null) return null;
        NativePrefactorTarget t = new NativePrefactorTarget();
        t.headerTable = header; t.detailTable = detail; t.noCol = noCol; t.refCol = refCol; t.productCol = productCol; t.qtyCol = qtyCol; t.baseSales = baseSales; t.note = note;
        t.priceCol = resolveFlexible(dCols, "fi", "FI", "fee", "Fee", "price", "Price", "nerkh", "Nerkh", "gheymat", "unit_price", "قیمت", "فی");
        t.amountCol = resolveFlexible(dCols, "LINESUM", "LineSum", "line_sum", "amount", "Amount", "mablagh", "total", "Total", "all", "line_total", "جمع");
        t.uuidCol = resolveFlexible(hCols, "client_uuid", "mobile_uuid", "uuid", "app_uuid", "external_id", "external_code", "source_id", "meelano_id");
        return t;
    }

    private String nativePrefactorMarkerColumn(Set<String> cols) {
        return resolveFlexible(cols,
                "is_pish", "isPish", "pish", "Pish", "pishfactor", "pish_factor", "is_pishfactor", "is_prefactor", "prefactor", "is_preinvoice", "preinvoice", "pre_invoice", "proforma", "is_proforma",
                "pish_noe", "pish_type", "factor_pish", "pish_flag", "پیش_فاکتور", "پيش_فاکتور", "پیشفاکتور", "پيشفاکتور", "پرفاکتور", "پروفورما");
    }

    private String nativeWeakPrefactorMarkerColumn(Set<String> cols) {
        String strong = nativePrefactorMarkerColumn(cols);
        if (strong != null) return strong;
        return resolveFlexible(cols, "factor_type", "FactorType", "type_factor", "typefac", "fact_type", "doc_type", "doctype", "sanad_type", "noe", "Noe", "kind", "Kind", "نوع_سند", "نوع_فاکتور");
    }

    private void putNativePrefactorMarkers(Map<String, Object> values, Map<String, SqlColumnMeta> meta, Set<String> cols) {
        putNativeMarker(values, meta, cols, nativePrefactorMarkerColumn(cols));
        putNativeMarker(values, meta, cols, nativeWeakPrefactorMarkerColumn(cols));
    }

    private void putNativeMarker(Map<String, Object> values, Map<String, SqlColumnMeta> meta, Set<String> cols, String col) {
        if (col == null || values == null || values.containsKey(col)) return;
        SqlColumnMeta m = meta == null ? null : meta.get(col);
        values.put(col, nativePrefactorMarkerValue(m, col));
    }

    private Object nativePrefactorMarkerValue(SqlColumnMeta m, String col) {
        String t = m == null ? "" : stringOr(m.type, "").toLowerCase(Locale.US);
        if (t.contains("bit")) return 1;
        if (isNumericSqlType(t)) return 1;
        String n = normalizeColumnName(col);
        if (containsAny(n, "status", "state", "vaziat", "وضعیت")) return NATIVE_PREF_STATUS_TEXT;
        return "پیش فاکتور";
    }

    private Object nativeExternalIdValue(SqlColumnMeta m, long id) {
        String v = "MEELANO-APP-" + id;
        String t = m == null ? "" : stringOr(m.type, "").toLowerCase(Locale.US);
        if (t.contains("uniqueidentifier")) return java.util.UUID.nameUUIDFromBytes(v.getBytes()).toString();
        return v;
    }

    private String nativeExternalIdText(SqlColumnMeta m, long id) { return String.valueOf(nativeExternalIdValue(m, id)); }

    private String nativePrefactorNumberColumn(Set<String> cols) {
        String c = resolveFlexible(cols, "shfacfo", "SHFACFO", "shfac", "shfacpish", "shfac_pish", "shpish", "sh_pish", "pish_no", "pish_number", "factor_no", "FactorNo", "fac_no", "No", "no", "number", "Number", "serial", "Serial", "shomare", "شماره");
        if (c != null) return c;
        for (String col : cols) {
            String n = normalizeColumnName(col);
            if (containsAny(n, "shfac", "factor", "fact", "serial", "number", "shomare", "شماره")) return col;
        }
        return null;
    }

    private String currentNativePrefactorNo(Connection c, long id) {
        if (id <= 0) return "";
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) ISNULL(native_prefactor_no,N'') FROM dbo.meelano_prefactors WHERE id=?")) {
            ps.setLong(1, id);
            try (ResultSet r = ps.executeQuery()) { return r.next() ? stringOr(r.getString(1), "") : ""; }
        } catch (Exception ignored) { return ""; }
    }

    private String currentNativePrefactorTable(Connection c, long id) {
        if (id <= 0) return "";
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) ISNULL(native_prefactor_table,N'') FROM dbo.meelano_prefactors WHERE id=?")) {
            ps.setLong(1, id);
            try (ResultSet r = ps.executeQuery()) { return r.next() ? stringOr(r.getString(1), "") : ""; }
        } catch (Exception ignored) { return ""; }
    }

    private boolean nativeHeaderRowExists(Connection c, NativePrefactorTarget target, String nativeNo, long id) {
        if (c == null || target == null || nativeNo == null || nativeNo.trim().isEmpty()) return false;
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) 1 FROM " + dbo(target.headerTable) + " WHERE TRY_CONVERT(nvarchar(120)," + qi(target.noCol) + ")=?")) {
            ps.setString(1, nativeNo.trim());
            try (ResultSet r = ps.executeQuery()) { if (r.next()) return true; }
        } catch (Exception ignored) { }
        return false;
    }

    private String findExistingNativePrefactorNo(Connection c, NativePrefactorTarget target, long id) {
        if (c == null || target == null || id <= 0 || target.uuidCol == null) return "";
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) TRY_CONVERT(nvarchar(120)," + qi(target.noCol) + ") FROM " + dbo(target.headerTable) + " WHERE TRY_CONVERT(nvarchar(220)," + qi(target.uuidCol) + ")=? ORDER BY " + qi(target.noCol) + " DESC")) {
            ps.setString(1, nativeExternalIdText(sqlColumnMeta(c, target.headerTable).get(target.uuidCol), id));
            try (ResultSet r = ps.executeQuery()) { return r.next() ? stringOr(r.getString(1), "") : ""; }
        } catch (Exception ignored) { return ""; }
    }

    private void updateNativePrefactorSync(Connection c, long id, String table, String no, String note) {
        if (c == null || id <= 0) return;
        try (PreparedStatement ps = c.prepareStatement("UPDATE dbo.meelano_prefactors SET native_prefactor_table=?, native_prefactor_no=?, native_sync_at=SYSDATETIME(), system_convert_note=?, updated_at=SYSDATETIME() WHERE id=?")) {
            ps.setString(1, stringOr(table, "")); ps.setString(2, stringOr(no, "")); ps.setString(3, stringOr(note, "")); ps.setLong(4, id); ps.executeUpdate();
        } catch (Exception ignored) { }
    }

    private String nativeAtiranToday(Connection c) {
        for (String fn : new String[]{"date_alan", "Date_Alan", "tarikh_alan", "Tarikh_Alan", "today_shamsi", "Today_Shamsi"}) {
            if (!hasFunction(c, fn)) continue;
            try (Statement st = c.createStatement(); ResultSet r = st.executeQuery("SELECT TRY_CONVERT(nvarchar(30),dbo." + qi(fn) + "())")) {
                if (r.next()) { String v = stringOr(r.getString(1), "").trim(); if (!v.isEmpty()) return v; }
            } catch (Exception ignored) { }
        }
        return jalaliTodayText();
    }

    private String jalaliTodayText() {
        try {
            Calendar cal = Calendar.getInstance();
            int gy = cal.get(Calendar.YEAR); int gm = cal.get(Calendar.MONTH) + 1; int gd = cal.get(Calendar.DAY_OF_MONTH);
            int[] gdm = {0,31,28,31,30,31,30,31,31,30,31,30,31};
            int gy2 = gy - 1600; int gm2 = gm - 1; int gd2 = gd - 1;
            long gDayNo = 365L * gy2 + (gy2 + 3) / 4 - (gy2 + 99) / 100 + (gy2 + 399) / 400;
            for (int i = 1; i <= gm2; ++i) gDayNo += gdm[i];
            if (gm > 2 && ((gy % 4 == 0 && gy % 100 != 0) || (gy % 400 == 0))) gDayNo++;
            gDayNo += gd2;
            long jDayNo = gDayNo - 79;
            long jNp = jDayNo / 12053; jDayNo %= 12053;
            int jy = (int)(979 + 33 * jNp + 4 * (jDayNo / 1461)); jDayNo %= 1461;
            if (jDayNo >= 366) { jy += (int)((jDayNo - 1) / 365); jDayNo = (jDayNo - 1) % 365; }
            int jm, jd;
            if (jDayNo < 186) { jm = 1 + (int)(jDayNo / 31); jd = 1 + (int)(jDayNo % 31); }
            else { jm = 7 + (int)((jDayNo - 186) / 30); jd = 1 + (int)((jDayNo - 186) % 30); }
            return String.format(Locale.US, "%04d/%02d/%02d", jy, jm, jd);
        } catch (Exception ignored) { return todayDateText(); }
    }

    private void syncNativeAtiranPrefactor(Connection c, long id, JSONObject snap, JSONArray items) {
        if (c == null || id <= 0 || snap == null) return;
        String st = snap.optString("status", "sent");
        if ("draft".equals(st)) { updateNativePrefactorSync(c, id, "", "", "پیش‌نویس است و هنوز برای تبدیل به فاکتور فروش ارسال نشده."); return; }
        if (isAtiranPishSchema(c)) { syncAtiranPishExact(c, id, snap, items); return; }
        java.sql.Savepoint sp = null;
        boolean startedTx = false;
        try {
            NativePrefactorTarget target = discoverNativePrefactorTarget(c);
            if (target == null) { updateNativePrefactorSync(c, id, "", "", "پیش‌فاکتور در میلانو ذخیره شد، اما محل ثبت پیش‌فاکتور در آتیران پیدا نشد."); return; }
            String existingNo = currentNativePrefactorNo(c, id).trim();
            String existingTable = currentNativePrefactorTable(c, id).trim();
            if (!existingNo.isEmpty() && existingTable.equalsIgnoreCase(target.headerTable) && nativeHeaderRowExists(c, target, existingNo, id)) return;
            String alreadyInTarget = findExistingNativePrefactorNo(c, target, id);
            if (!alreadyInTarget.trim().isEmpty()) { updateNativePrefactorSync(c, id, target.headerTable, alreadyInTarget.trim(), "رکورد قبلی Meelano در جدول " + target.headerTable + " پیدا شد و برای مسیر «فاکتور فروش ← از پیش فاکتور» ثبت شد."); return; }

            boolean auto = c.getAutoCommit();
            if (auto) { c.setAutoCommit(false); startedTx = true; }
            else sp = c.setSavepoint("meelano_native_prefactor");

            Set<String> hCols = columns(c, target.headerTable); Set<String> dCols = columns(c, target.detailTable);
            Map<String, SqlColumnMeta> hMeta = sqlColumnMeta(c, target.headerTable);
            Map<String, SqlColumnMeta> dMeta = sqlColumnMeta(c, target.detailTable);
            long nativeNo = nextNativeNumber(c, target.headerTable, target.noCol);
            String nativeDate = nativeAtiranToday(c);
            Map<String, Object> hv = new LinkedHashMap<>();
            hv.put(target.noCol, nativeNo);
            putResolved(hv, hCols, snap.optString("customerCode", ""), "shmo", "SHMO", "customer", "customer_code", "cust_code", "code_moshtari", "کد_مشتری");
            putResolved(hv, hCols, snap.optString("customerName", ""), "moname", "MONAME", "customer_name", "CustomerName", "name", "Name", "نام");
            putResolved(hv, hCols, nativeDate, "date", "DATE", "tarikh", "Date", "tarikh_factor", "تاریخ");
            putResolved(hv, hCols, stringOr(snap.optString("deliveryDate", ""), nativeDate), "t_date", "tasvieh_date", "delivery_date", "DeliveryDate", "sarresid", "due_date", "تاریخ_تحویل");
            putResolved(hv, hCols, snap.optDouble("grandTotal", 0), "all", "All", "total", "Total", "grand_total", "amount", "mablagh", "kol", "jamkol", "جمع");
            putResolved(hv, hCols, snap.optDouble("subtotal", 0), "subtotal", "sub_total", "sum", "sum_price", "jam", "جمع_خام");
            putResolved(hv, hCols, snap.optDouble("globalDiscount", 0) + snap.optDouble("lineDiscount", 0), "tafif", "takhfif", "discount", "Discount", "تخفیف");
            putResolved(hv, hCols, snap.optDouble("taxAmount", 0), "tax", "Tax", "maliat", "Maliat", "vat", "VAT", "مالیات");
            putResolved(hv, hCols, snap.optDouble("taxPercent", 0), "tax_percent", "TaxPercent", "darsad_maliat", "درصد_مالیات");
            putResolved(hv, hCols, currentAccountName(), "visitor", "Visitor", "visitor_username", "user", "username", "karbar", "کاربر");
            putResolved(hv, hCols, snap.optString("visitorId", ""), "visitor_id", "VisitorId", "vis_rdf", "VIS_RDF", "shv", "shvaz", "visitor_code", "کد_ویزیتور");
            String extCol = resolveFlexible(hCols, "client_uuid", "mobile_uuid", "uuid", "app_uuid", "external_id", "external_code", "source_id", "meelano_id");
            if (extCol != null && !hv.containsKey(extCol)) hv.put(extCol, nativeExternalIdValue(hMeta.get(extCol), id));
            putResolved(hv, hCols, snap.optString("notes", ""), "tozihat", "Tozihat", "description", "Description", "note", "notes", "memo", "شرح", "توضیحات");
            putResolved(hv, hCols, snap.optString("settlement", ""), "tasvieh", "Tasvieh", "settlement", "payment_type", "نوع_تسویه");
            putResolved(hv, hCols, NATIVE_PREF_STATUS_TEXT, "status", "Status", "state", "State", "vaziat", "Vaziat", "وضعیت");
            putResolved(hv, hCols, 0, "converted", "is_converted", "convert", "Convert", "tabdil", "Tabdil", "invoiced", "is_invoiced", "invoice_done");
            putResolved(hv, hCols, 1, "ready", "ready_for_invoice", "for_invoice", "can_invoice", "آماده_فاکتور");
            putNativePrefactorMarkers(hv, hMeta, hCols);
            putResolved(hv, hCols, 0, "is_deleted", "deleted", "Delete", "Deleted", "del", "حذف");
            putResolved(hv, hCols, 1, "active", "Active", "is_active", "enable", "enabled");
            insertFlexibleRow(c, target.headerTable, hv);

            if (items == null || items.length() == 0) throw new IllegalStateException("اقلام پیش‌فاکتور برای ثبت در آتیران خالی است.");
            for (int i = 0; i < items.length(); i++) {
                JSONObject it = items.optJSONObject(i); if (it == null) continue;
                Map<String, Object> dv = new LinkedHashMap<>();
                dv.put(target.refCol, nativeNo); dv.put(target.productCol, it.optString("code", "")); dv.put(target.qtyCol, it.optDouble("qty", 0));
                if (target.priceCol != null) dv.put(target.priceCol, it.optDouble("price", 0));
                if (target.amountCol != null) dv.put(target.amountCol, cartItemNet(it));
                putResolved(dv, dCols, i + 1, "radif", "Radif", "row", "row_no", "ردیف");
                putResolved(dv, dCols, it.optString("name", ""), "naka", "NAKA", "product_name", "ProductName", "name", "Name", "نام_کالا");
                putResolved(dv, dCols, it.optString("unit", ""), "vahed", "unit", "Unit", "unit_name", "واحد");
                putResolved(dv, dCols, it.optDouble("lineDiscount", 0), "tafif", "takhfif", "discount", "Discount", "تخفیف");
                putResolved(dv, dCols, it.optString("note", ""), "tozihat", "note", "notes", "memo", "شرح", "توضیحات");
                putResolved(dv, dCols, nativeDate, "date", "DATE", "tarikh", "Date", "تاریخ");
                putResolved(dv, dCols, 0, "converted", "is_converted", "invoiced", "is_invoiced");
                putNativePrefactorMarkers(dv, dMeta, dCols);
                putResolved(dv, dCols, 0, "is_deleted", "deleted", "Delete", "Deleted", "del", "حذف"); putResolved(dv, dCols, 1, "active", "Active", "is_active", "enable", "enabled");
                insertFlexibleRow(c, target.detailTable, dv);
            }
            updateNativePrefactorSync(c, id, target.headerTable, String.valueOf(nativeNo), "در جدول " + target.headerTable + " / " + target.detailTable + " با تاریخ " + nativeDate + " ثبت شد (" + stringOr(target.note, "ساختار آتیران") + ") و باید در مسیر «فاکتور فروش ← از پیش فاکتور» قابل انتخاب باشد.");
            if (startedTx) c.commit();
        } catch (Exception ex) {
            try { if (startedTx) c.rollback(); else if (sp != null) c.rollback(sp); } catch (Exception ignored) { }
            updateNativePrefactorSync(c, id, "", "", "همگام‌سازی با پیش‌فاکتور آتیران کامل نشد: " + shortError(ex));
            try { if (startedTx) c.commit(); } catch (Exception ignored) { }
        } finally { try { if (startedTx) c.setAutoCommit(true); } catch (Exception ignored) { } }
    }



    // ---------------------------------------------------------------------------------------------
    // Atiran pre-invoice writer (sailfact_pish / subsailfact_pish).
    // Built from Atiran's own database, read in September 2026:
    //  * dbo.add_sail_pish (Atiran's own "new pre-invoice" procedure) writes rdf__=1, shfacfo=MAX+1,
    //    active='t', isret/ismodify '0', Rejected=0, sh_f=0, taeed=0, taeedUser/user_f/date_f '--',
    //    man_gh = customer balance, then sets TaedHesabdari / TaedForush when overal_setting 77 / 78 = 1.
    //  * dbo.ListPishFactor (the list Atiran shows) only returns rows with active='t', Rejected=0,
    //    TaedForush=1, TaedHesabdari=1, sh_f=0 AND at least one subsailfact_pish row with active='t'
    //    whose SHKA exists in inventory; the customer must reach CITYS through masir/Quarter/regions.
    //  * Detail lines: RDF is 0-based, rdf__ equals the header's rdf__, JOZPRICE is the price of one
    //    piece, VAHPRICE = JOZPRICE * inventory.mohvah, LINESUM = (TEDVAH*mohvah + TEDJOZ) * JOZPRICE.
    //  * Dates are Persian text yyyy/mm/dd (char(10)); Atiran text uses the Arabic yeh.
    // Earlier Meelano versions wrote active='1', left Rejected/sh_f NULL and skipped the approvals,
    // so Atiran never listed those rows. They are switched off (active='f') the next time this runs.
    // ---------------------------------------------------------------------------------------------
    private static final String ATIRAN_MEELANO_STAMP = "MEELANO-";

    private boolean isAtiranPishSchema(Connection c) {
        try {
            if (c == null || !tableExists(c, "sailfact_pish") || !tableExists(c, "subsailfact_pish")) return false;
            Set<String> h = columns(c, "sailfact_pish"); Set<String> d = columns(c, "subsailfact_pish");
            return hasCol(h, "shfacfo") && hasCol(h, "rdf__") && hasCol(h, "active") && hasCol(h, "shmo") && hasCol(h, "all")
                    && hasCol(d, "shfacfo") && hasCol(d, "rdf__") && hasCol(d, "SHKA") && hasCol(d, "RDF") && hasCol(d, "TEDVAH") && hasCol(d, "JOZPRICE") && hasCol(d, "active");
        } catch (Exception ignored) { return false; }
    }

    /** Atiran stores Persian text with the Arabic yeh; many of its columns are varchar (code page 1256 has no Persian yeh). */
    private String atiranText(String s, int max) {
        String v = stringOr(s, "").replace('\u06CC', '\u064A').replace('\u0649', '\u064A').replace("\u200C", " ").trim();
        return max > 0 && v.length() > max ? v.substring(0, max) : v;
    }

    private String atiranPersianToday(Connection c) {
        try (Statement st = c.createStatement(); ResultSet r = st.executeQuery("SELECT TRY_CONVERT(nvarchar(30),dbo.UDF_Gregorian_To_Persian(GETDATE()))")) {
            if (r.next()) { String v = normalizeDigits(stringOr(r.getString(1), "")).trim(); if (v.matches("^1[34]\\d{2}/\\d{2}/\\d{2}$")) return v; }
        } catch (Exception ignored) { }
        String v = normalizeDigits(stringOr(nativeAtiranToday(c), "")).trim();
        return v.matches("^1[34]\\d{2}/\\d{2}/\\d{2}$") ? v : jalaliTodayText();
    }

    private long atiranSetting(Connection c, int id, long fallback) {
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) TRY_CONVERT(bigint,[value]) FROM dbo.overal_setting WHERE id=?")) {
            ps.setInt(1, id);
            try (ResultSet r = ps.executeQuery()) { if (r.next()) { long v = r.getLong(1); if (!r.wasNull()) return v; } }
        } catch (Exception ignored) { }
        return fallback;
    }

    private int atiranDefaultWarehouse(Connection c) {
        String[] queries = {
                "SELECT TOP (1) rdf_anbar FROM dbo.anbars WHERE ISNULL(Base,0)=1 AND ISNULL(Active,1)=1 ORDER BY rdf_anbar",
                "SELECT TOP (1) s.rdf_anbar FROM dbo.subsailfact s WHERE s.active='t' AND EXISTS(SELECT 1 FROM dbo.anbars a WHERE a.rdf_anbar=s.rdf_anbar) GROUP BY s.rdf_anbar ORDER BY COUNT_BIG(1) DESC",
                "SELECT TOP (1) rdf_anbar FROM dbo.anbars WHERE ISNULL(Active,1)=1 ORDER BY rdf_anbar",
                "SELECT TOP (1) rdf_anbar FROM dbo.anbars ORDER BY rdf_anbar" };
        for (String q : queries) {
            try (Statement st = c.createStatement(); ResultSet r = st.executeQuery(q)) { if (r.next()) return r.getInt(1); } catch (Exception ignored) { }
        }
        return 1;
    }

    private void putAtiran(Map<String, Object> values, Set<String> cols, String col, Object value) {
        String real = resolve(cols, col);
        if (real != null && value != null) values.put(real, value);
    }

    private static double round2(double v) { return Math.round(v * 100.0) / 100.0; }
    private static double round3(double v) { return Math.round(v * 1000.0) / 1000.0; }

    /** Soft-disables rows written by old Meelano versions (active='1' is never used by Atiran itself: it uses 't'/'f'). */
    private void deactivateLegacyMeelanoPishRows(Connection c) {
        try (Statement st = c.createStatement()) {
            st.executeUpdate("UPDATE dbo.sailfact_pish SET active='f' WHERE active NOT IN ('t','f')");
            st.executeUpdate("UPDATE dbo.subsailfact_pish SET active='f' WHERE active NOT IN ('t','f')");
        } catch (Exception ignored) { }
    }

    private long findAtiranPishByStamp(Connection c, Set<String> hCols, long id) {
        String stamp = resolve(hCols, "Stamp");
        if (stamp == null || id <= 0) return 0;
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) shfacfo FROM dbo.sailfact_pish WHERE active='t' AND TRY_CONVERT(nvarchar(120)," + qi(stamp) + ")=? ORDER BY shfacfo DESC")) {
            ps.setString(1, ATIRAN_MEELANO_STAMP + id);
            try (ResultSet r = ps.executeQuery()) { if (r.next()) return r.getLong(1); }
        } catch (Exception ignored) { }
        return 0;
    }

    private boolean atiranPishActive(Connection c, String no) {
        long n = (long) parseNumber(no, 0);
        if (n <= 0) return false;
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) 1 FROM dbo.sailfact_pish h WHERE h.shfacfo=? AND h.active='t' AND EXISTS(SELECT 1 FROM dbo.subsailfact_pish d WHERE d.shfacfo=h.shfacfo AND d.rdf__=h.rdf__ AND d.active='t')")) {
            ps.setLong(1, n);
            try (ResultSet r = ps.executeQuery()) { return r.next(); }
        } catch (Exception ignored) { return false; }
    }

    /** Describes whether Atiran's own list (dbo.ListPishFactor) will show this pre-invoice. */
    private String atiranPishVisibilityNote(Connection c, long no) {
        try (PreparedStatement ps = c.prepareStatement(
                "SELECT ISNULL(CAST(h.TaedHesabdari AS int),0), ISNULL(CAST(h.TaedForush AS int),0), ISNULL(CAST(h.Rejected AS int),0), " +
                "(SELECT COUNT_BIG(1) FROM dbo.subsailfact_pish d JOIN dbo.inventory i ON i.shka=d.SHKA WHERE d.shfacfo=h.shfacfo AND d.rdf__=h.rdf__ AND d.active='t'), " +
                "(SELECT COUNT_BIG(1) FROM dbo.CUSTOMERS cu JOIN dbo.masir m ON cu.RDF_masir=m.rdf_masir JOIN dbo.[Quarter] q ON m.QuarterID=q.ID JOIN dbo.regions r ON q.RegionId=r.rdf_region JOIN dbo.CITYS ct ON r.rdf_city=ct.RDF WHERE cu.SHMO=h.shmo) " +
                "FROM dbo.sailfact_pish h WHERE h.shfacfo=? AND h.active='t'")) {
            ps.setLong(1, no);
            try (ResultSet r = ps.executeQuery()) {
                if (!r.next()) return "ردیف در آتیران پیدا نشد.";
                List<String> problems = new ArrayList<>();
                if (r.getInt(1) != 1) problems.add("تایید حسابداری");
                if (r.getInt(2) != 1) problems.add("تایید مدیر فروش");
                if (r.getInt(3) != 0) problems.add("رد شده است");
                if (r.getLong(4) <= 0) problems.add("کالاهای پیش‌فاکتور در آتیران شناخته نشد");
                if (r.getLong(5) <= 0) problems.add("مسیر/محله مشتری در آتیران تعریف نشده");
                if (problems.isEmpty()) return "";
                return "در فهرست آتیران هنوز دیده نمی‌شود؛ مانده: " + join(problems, "، ") + ".";
            }
        } catch (Exception ex) { return ""; }
    }

    /**
     * Writes one Meelano pre-invoice into Atiran exactly the way dbo.add_sail_pish does.
     * Must run inside a transaction (the caller commits or rolls back).
     * Returns the Atiran pre-invoice number (shfacfo).
     */
    private long writeAtiranPish(Connection c, long id, JSONObject snap, JSONArray items) throws Exception {
        if (items == null || items.length() == 0) throw new DbException("اقلام پیش‌فاکتور خالی است.");
        Set<String> hCols = columns(c, "sailfact_pish"); Set<String> dCols = columns(c, "subsailfact_pish");

        long shmo = (long) parseNumber(snap.optString("customerCode", ""), 0);
        if (shmo <= 0) throw new DbException("کد مشتری برای آتیران معتبر نیست.");
        double customerBalance = 0; boolean customerFound = false;
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) ISNULL(TRY_CONVERT(decimal(19,4),man),0) FROM dbo.CUSTOMERS WHERE SHMO=?")) {
            ps.setLong(1, shmo);
            try (ResultSet r = ps.executeQuery()) { if (r.next()) { customerFound = true; customerBalance = r.getDouble(1); } }
        }
        if (!customerFound) throw new DbException("مشتری با کد " + shmo + " در آتیران پیدا نشد.");

        int visRdf = -1;
        long wantedVisitor = (long) parseNumber(snap.optString("visitorId", ""), 0);
        if (wantedVisitor > 0) {
            try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) vis_rdf FROM dbo.visitors WHERE vis_rdf=?")) {
                ps.setLong(1, wantedVisitor);
                try (ResultSet r = ps.executeQuery()) { if (r.next()) visRdf = r.getInt(1); }
            } catch (Exception ignored) { }
        }

        int warehouse = atiranDefaultWarehouse(c);
        double taxPercent = Math.max(0, snap.optDouble("taxPercent", 0));
        List<Map<String, Object>> lines = new ArrayList<>(); List<String> unknown = new ArrayList<>();
        double sumGross = 0, sumLineDiscount = 0;
        for (int i = 0; i < items.length(); i++) {
            JSONObject it = items.optJSONObject(i); if (it == null) continue;
            String code = it.optString("code", "").trim();
            long shka = (long) parseNumber(code, 0);
            long mohvah = 1; String pack = ""; boolean found = false;
            if (shka > 0) {
                try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) ISNULL(TRY_CONVERT(bigint,mohvah),1), ISNULL(TRY_CONVERT(nvarchar(60),bastebandi),N'') FROM dbo.inventory WHERE shka=?")) {
                    ps.setLong(1, shka);
                    try (ResultSet r = ps.executeQuery()) { if (r.next()) { found = true; mohvah = Math.max(1, r.getLong(1)); pack = stringOr(r.getString(2), ""); } }
                }
            }
            if (!found) { unknown.add(code.isEmpty() ? it.optString("name", "?") : code); continue; }
            double qty = Math.max(0, it.optDouble("qty", 0));
            double piecePrice = Math.max(0, it.optDouble("price", 0));
            double gross = cartItemGross(it); double discount = cartItemDiscount(it);
            double tedvah; int tedjoz;
            if (mohvah > 1 && Math.abs(qty - Math.rint(qty)) < 1e-9) { long pieces = Math.round(qty); tedvah = pieces / mohvah; tedjoz = (int) (pieces % mohvah); }
            else if (mohvah > 1) { tedvah = round3(qty / mohvah); tedjoz = 0; }
            else { tedvah = round3(qty); tedjoz = 0; }
            Map<String, Object> d = new LinkedHashMap<>();
            putAtiran(d, dCols, "rdf__", 1); putAtiran(d, dCols, "SHKA", shka); putAtiran(d, dCols, "rdf_anbar", warehouse);
            putAtiran(d, dCols, "TEDVAH", tedvah); putAtiran(d, dCols, "TEDJOZ", tedjoz);
            putAtiran(d, dCols, "VAHPRICE", piecePrice * mohvah); putAtiran(d, dCols, "JOZPRICE", piecePrice);
            putAtiran(d, dCols, "BASTEBANDI", atiranText(pack, 25)); putAtiran(d, dCols, "TEDBASTEBANDI", 0);
            putAtiran(d, dCols, "LINESUM", gross); putAtiran(d, dCols, "LINEGAIN", 0); putAtiran(d, dCols, "ISRET", "0");
            putAtiran(d, dCols, "PERTAFIF", gross > 0 ? round2(discount * 100.0 / gross) : 0); putAtiran(d, dCols, "RDF", lines.size());
            putAtiran(d, dCols, "jozgain", 0); putAtiran(d, dCols, "PERVIS", 0); putAtiran(d, dCols, "litakhma", discount);
            putAtiran(d, dCols, "active", "t"); putAtiran(d, dCols, "amani", false);
            putAtiran(d, dCols, "Pavarez", 0); putAtiran(d, dCols, "Avarez", 0);
            putAtiran(d, dCols, "Ptax", taxPercent); putAtiran(d, dCols, "Tax", Math.round(Math.max(0, gross - discount) * taxPercent / 100.0));
            putAtiran(d, dCols, "Mp", 0); putAtiran(d, dCols, "PerPromotion", 0);
            lines.add(d); sumGross += gross; sumLineDiscount += discount;
        }
        if (!unknown.isEmpty()) throw new DbException("این کالاها در آتیران پیدا نشد: " + join(unknown, "، "));
        if (lines.isEmpty()) throw new DbException("هیچ کالای معتبری برای آتیران در پیش‌فاکتور نیست.");

        long no;
        try (Statement st = c.createStatement(); ResultSet r = st.executeQuery("SELECT ISNULL(MAX(shfacfo),0)+1 FROM dbo.sailfact_pish WITH (UPDLOCK, HOLDLOCK)")) {
            no = r.next() ? Math.max(1, r.getLong(1)) : 1;
        }
        String date = atiranPersianToday(c);
        String user = atiranText(stringOr(snap.optString("visitor", ""), currentAccountName()), 300);
        if (user.isEmpty()) user = "Meelano";
        double discountTotal = sumLineDiscount + Math.max(0, snap.optDouble("globalDiscount", 0));
        double tax = Math.max(0, snap.optDouble("taxAmount", 0));
        double all = snap.optDouble("grandTotal", 0);
        if (all <= 0) all = Math.max(0, sumGross - discountTotal + tax);
        String notes = atiranText(snap.optString("notes", ""), 900);
        String settlement = atiranText(snap.optString("settlement", ""), 200);
        int tahbarg = 0, nahPar = 0;
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) ISNULL(rdf_tahbarg,0), ISNULL(nah_par,0) FROM dbo.sailfact WHERE active='t' AND (shmo=? OR ?=0) ORDER BY CASE WHEN shmo=? THEN 0 ELSE 1 END, shfacfo DESC")) {
            ps.setLong(1, shmo); ps.setInt(2, 0); ps.setLong(3, shmo);
            try (ResultSet r = ps.executeQuery()) { if (r.next()) { tahbarg = r.getInt(1); nahPar = r.getInt(2); } }
        } catch (Exception ignored) { }

        Map<String, Object> h = new LinkedHashMap<>();
        putAtiran(h, hCols, "rdf__", 1); putAtiran(h, hCols, "shfacfo", no); putAtiran(h, hCols, "USER__", user);
        putAtiran(h, hCols, "date", date); putAtiran(h, hCols, "shmo", shmo); putAtiran(h, hCols, "barbari", 0);
        putAtiran(h, hCols, "shfacthand", notes.isEmpty() ? "ذكر نشده" : notes); putAtiran(h, hCols, "vis_rdf", visRdf);
        putAtiran(h, hCols, "sumlineall", sumGross); putAtiran(h, hCols, "all", all); putAtiran(h, hCols, "gainall", 0);
        putAtiran(h, hCols, "tafif", discountTotal); putAtiran(h, hCols, "jamtakhgh", sumLineDiscount);
        putAtiran(h, hCols, "done_date", date); putAtiran(h, hCols, "panevis", "ذکر نشده");
        putAtiran(h, hCols, "isret", "0"); putAtiran(h, hCols, "ismodify", "0"); putAtiran(h, hCols, "active", "t");
        putAtiran(h, hCols, "modpar", 0); putAtiran(h, hCols, "rdf_sarbarg", 0); putAtiran(h, hCols, "rdf_tahbarg", tahbarg);
        putAtiran(h, hCols, "nah_par", nahPar); putAtiran(h, hCols, "mod_darsad_vis", 0);
        if (!settlement.isEmpty()) putAtiran(h, hCols, "nah_d_text", settlement);
        putAtiran(h, hCols, "man_gh", customerBalance); putAtiran(h, hCols, "sh_f", 0); putAtiran(h, hCols, "user_f", "--"); putAtiran(h, hCols, "date_f", "--");
        putAtiran(h, hCols, "ted_rooz", (int) atiranSetting(c, 38, 0)); putAtiran(h, hCols, "taeed", 0); putAtiran(h, hCols, "taeedUser", "--");
        putAtiran(h, hCols, "sysid", 1); putAtiran(h, hCols, "TaedHesabdari", false); putAtiran(h, hCols, "TaedForush", false);
        putAtiran(h, hCols, "Rejected", false); putAtiran(h, hCols, "tax", tax); putAtiran(h, hCols, "avarez", 0); putAtiran(h, hCols, "Promotion", 0);
        putAtiran(h, hCols, "Stamp", ATIRAN_MEELANO_STAMP + id);
        insertFlexibleRow(c, "sailfact_pish", h);
        for (Map<String, Object> d : lines) { putAtiran(d, dCols, "shfacfo", no); insertFlexibleRow(c, "subsailfact_pish", d); }

        // Same automatic approvals Atiran's own add_sail_pish applies (overal_setting 77 and 78).
        if (atiranSetting(c, 77, 0) == 1 && hasCol(hCols, "TaedHesabdari")) {
            try (PreparedStatement ps = c.prepareStatement("UPDATE dbo.sailfact_pish SET TaedHesabdari=1, UserTaedHesabdari=N'اتوماتيك', DateTaedHesabdari=? WHERE shfacfo=? AND active='t'")) { ps.setString(1, date); ps.setLong(2, no); ps.executeUpdate(); }
        }
        if (atiranSetting(c, 78, 0) == 1 && hasCol(hCols, "TaedForush")) {
            try (PreparedStatement ps = c.prepareStatement("UPDATE dbo.sailfact_pish SET TaedForush=1, UserTaedForush=N'اتوماتيك', DateTaedForush=? WHERE shfacfo=? AND active='t'")) { ps.setString(1, date); ps.setLong(2, no); ps.executeUpdate(); }
        }
        return no;
    }

    private void syncAtiranPishExact(Connection c, long id, JSONObject snap, JSONArray items) {
        java.sql.Savepoint sp = null; boolean startedTx = false;
        try {
            String existingNo = currentNativePrefactorNo(c, id).trim();
            String existingTable = currentNativePrefactorTable(c, id).trim();
            if (!existingNo.isEmpty() && "sailfact_pish".equalsIgnoreCase(existingTable) && atiranPishActive(c, existingNo)) return;
            Set<String> hCols = columns(c, "sailfact_pish");
            long stamped = findAtiranPishByStamp(c, hCols, id);
            if (stamped > 0) {
                String vis = atiranPishVisibilityNote(c, stamped);
                updateNativePrefactorSync(c, id, "sailfact_pish", String.valueOf(stamped), "در آتیران ثبت است: پیش‌فاکتور شماره " + stamped + (vis.isEmpty() ? "" : " — " + vis));
                return;
            }
            if (c.getAutoCommit()) { c.setAutoCommit(false); startedTx = true; } else sp = c.setSavepoint("meelano_atiran_pish");
            deactivateLegacyMeelanoPishRows(c);
            long no = writeAtiranPish(c, id, snap, items);
            String vis = atiranPishVisibilityNote(c, no);
            updateNativePrefactorSync(c, id, "sailfact_pish", String.valueOf(no),
                    "در آتیران ثبت شد: پیش‌فاکتور شماره " + no + " به تاریخ " + atiranPersianToday(c) + (vis.isEmpty() ? " — در فهرست پیش‌فاکتورهای آتیران و «فاکتور فروش ← از پیش‌فاکتور» دیده می‌شود." : " — " + vis));
            if (startedTx) c.commit();
        } catch (Exception ex) {
            try { if (startedTx) c.rollback(); else if (sp != null) c.rollback(sp); } catch (Exception ignored) { }
            updateNativePrefactorSync(c, id, "", "", "به آتیران نرسید: " + shortError(ex));
            try { if (startedTx) c.commit(); } catch (Exception ignored) { }
        } finally { try { if (startedTx) c.setAutoCommit(true); } catch (Exception ignored) { } }
    }

    private volatile long lastUnsyncedPrefactorId = 0;

    /** Sends one saved pre-invoice to Atiran again (button on the "did not reach Atiran" notice). */
    private void retryAtiranPrefactorSync(long id) {
        if (id <= 0) return;
        showNotice("ارسال دوباره به آتیران…", false);
        runDb(() -> {
            try (Connection c = openConnection()) {
                ensurePrefactorTables(c);
                repairUnsyncedNativePrefactors(c);
                return prefactorSubmitMessage(c, id);
            }
        }, new DbCallback() {
            @Override public void ok(String body) { if (String.valueOf(body).contains("نرسید")) showNotice(body, true, "تلاش دوباره", () -> retryAtiranPrefactorSync(id)); else showNotice(body, true); }
            @Override public void fail(Exception e) { showNotice("اتصال به سرور برقرار نشد: " + shortError(e), true, "تلاش دوباره", () -> retryAtiranPrefactorSync(id)); }
        });
    }

    /** Message shown after the visitor submits: says honestly whether Atiran received the pre-invoice. */
    private String prefactorSubmitMessage(Connection c, long id) {
        String table = currentNativePrefactorTable(c, id).trim(); String no = currentNativePrefactorNo(c, id).trim();
        String note = "";
        try (PreparedStatement ps = c.prepareStatement("SELECT TOP (1) ISNULL(system_convert_note,N'') FROM dbo.meelano_prefactors WHERE id=?")) {
            ps.setLong(1, id);
            try (ResultSet r = ps.executeQuery()) { if (r.next()) note = stringOr(r.getString(1), ""); }
        } catch (Exception ignored) { }
        if (!no.isEmpty() && !table.isEmpty()) {
            String extra = note.contains("دیده نمی‌شود") ? "\n" + note.substring(note.indexOf("در فهرست")) : "";
            return "پیش‌فاکتور در آتیران ثبت شد. شماره آتیران: " + no + extra;
        }
        lastUnsyncedPrefactorId = id;
        return "پیش‌فاکتور در میلانو ذخیره شد (شماره " + id + ") اما به آتیران نرسید." + (note.isEmpty() ? "" : "\nعلت: " + note.replace("به آتیران نرسید: ", "")) + "\nبا باز کردن «پیش‌فاکتورهای من» دوباره تلاش می‌شود.";
    }

    private void repairUnsyncedNativePrefactors(Connection c) {
        if (c == null) return;
        try {
            if (!tableExists(c, "meelano_prefactors") || !tableExists(c, "meelano_prefactor_items")) return;
            String sql = "SELECT TOP (40) id,client_uuid,visitor_username,visitor_id,customer_code,customer_name,notes,signature_data,ISNULL(grand_total,total_amount),status,delivery_date,delivery_address,settlement_type,payment_ref,subtotal_amount,global_discount,tax_percent,tax_amount,approval_reason " +
                    "FROM dbo.meelano_prefactors WHERE ISNULL(status,N'')<>N'draft' AND (NULLIF(ISNULL(native_prefactor_no,N''),N'') IS NULL OR native_sync_at IS NULL OR created_at>=DATEADD(day,-14,SYSDATETIME())) ORDER BY id DESC";
            JSONArray pending = new JSONArray();
            try (PreparedStatement ps = c.prepareStatement(sql); ResultSet r = ps.executeQuery()) {
                while (r.next()) {
                    long id = r.getLong(1);
                    JSONObject snap = new JSONObject();
                    snap.put("repairId", id);
                    snap.put("clientUuid", stringOr(r.getString(2), "")); snap.put("visitor", stringOr(r.getString(3), "")); snap.put("visitorId", stringOr(r.getString(4), ""));
                    snap.put("customerCode", stringOr(r.getString(5), "")); snap.put("customerName", stringOr(r.getString(6), "")); snap.put("notes", stringOr(r.getString(7), "")); snap.put("signature", stringOr(r.getString(8), ""));
                    snap.put("grandTotal", r.getDouble(9)); snap.put("status", stringOr(r.getString(10), "sent")); snap.put("deliveryDate", stringOr(r.getString(11), "")); snap.put("address", stringOr(r.getString(12), ""));
                    snap.put("settlement", stringOr(r.getString(13), "")); snap.put("paymentRef", stringOr(r.getString(14), "")); snap.put("subtotal", r.getDouble(15)); snap.put("globalDiscount", r.getDouble(16));
                    snap.put("taxPercent", r.getDouble(17)); snap.put("taxAmount", r.getDouble(18)); snap.put("approvalReason", stringOr(r.getString(19), ""));
                    pending.put(snap);
                }
            }
            for (int pidx = 0; pidx < pending.length(); pidx++) {
                JSONObject snap = pending.optJSONObject(pidx); if (snap == null) continue;
                long id = snap.optLong("repairId", 0);
                JSONArray items = new JSONArray();
                try (PreparedStatement ip = c.prepareStatement("SELECT product_code,product_name,unit,qty,price,amount,stock_snapshot,pack_count,price_tier,line_discount,line_note FROM dbo.meelano_prefactor_items WHERE prefactor_id=? ORDER BY id")) {
                    ip.setLong(1, id);
                    try (ResultSet ir = ip.executeQuery()) {
                        while (ir.next()) { JSONObject it = new JSONObject(); it.put("code", stringOr(ir.getString(1), "")); it.put("name", stringOr(ir.getString(2), "")); it.put("unit", stringOr(ir.getString(3), "")); it.put("qty", ir.getDouble(4)); it.put("price", ir.getDouble(5)); it.put("amount", ir.getDouble(6)); it.put("stock", ir.getDouble(7)); it.put("pack", ir.getDouble(8)); it.put("priceTier", stringOr(ir.getString(9), "1")); it.put("lineDiscount", ir.getDouble(10)); it.put("note", stringOr(ir.getString(11), "")); items.put(it); }
                    }
                }
                snap.put("items", items);
                if (items.length() > 0) syncNativeAtiranPrefactor(c, id, snap, items);
            }
        } catch (Exception ignored) { }
    }

    private void putResolved(Map<String, Object> values, Set<String> cols, Object value, String... candidates) {
        String col = resolveFlexible(cols, candidates);
        if (col != null && !values.containsKey(col)) values.put(col, value);
    }

    /**
     * Next Atiran pre-invoice number. Must be called inside the caller's transaction:
     * UPDLOCK + HOLDLOCK keeps the range locked until commit, so two visitors submitting at the
     * same moment are serialised instead of both receiving the same number. The internal Meelano
     * id is never used as a floor (that made numbers jump), and a failed read aborts the native
     * sync (recorded as "sync incomplete") instead of silently writing a wrong number.
     */
    private long nextNativeNumber(Connection c, String table, String col) throws Exception {
        String sql = "SELECT ISNULL(MAX(TRY_CONVERT(bigint," + qi(col) + ")),0)+1 FROM " + dbo(table) + " WITH (UPDLOCK, HOLDLOCK)";
        try (Statement st = c.createStatement(); ResultSet r = st.executeQuery(sql)) {
            if (r.next()) return Math.max(1L, r.getLong(1));
        }
        throw new DbException("شماره بعدی پیش‌فاکتور آتیران خوانده نشد.");
    }

    private boolean insertFlexibleRow(Connection c, String table, Map<String, Object> values) throws Exception {
        Map<String, SqlColumnMeta> meta = sqlColumnMeta(c, table);
        List<SqlColumnMeta> cols = new ArrayList<>(); List<Object> params = new ArrayList<>();
        for (SqlColumnMeta m : meta.values()) {
            if (m == null || m.identity || m.computed || isRowVersionType(m.type)) continue;
            boolean has = values != null && values.containsKey(m.name);
            if (!has && (m.nullable || m.hasDefault)) continue;
            cols.add(m); params.add(has ? values.get(m.name) : nativeDefaultValue(m));
        }
        if (cols.isEmpty()) return false;
        StringBuilder sql = new StringBuilder("INSERT INTO ").append(dbo(table)).append("(");
        for (int i = 0; i < cols.size(); i++) { if (i > 0) sql.append(','); sql.append(qi(cols.get(i).name)); }
        sql.append(") VALUES("); for (int i = 0; i < cols.size(); i++) { if (i > 0) sql.append(','); sql.append('?'); } sql.append(')');
        try (PreparedStatement ps = c.prepareStatement(sql.toString())) {
            for (int i = 0; i < cols.size(); i++) setNativeParam(ps, i + 1, params.get(i), cols.get(i).type);
            ps.executeUpdate(); return true;
        }
    }

    private boolean isRowVersionType(String type) { String t = stringOr(type, "").toLowerCase(Locale.US); return t.contains("timestamp") || t.contains("rowversion"); }
    private boolean isNumericSqlType(String type) { String t = stringOr(type, "").toLowerCase(Locale.US); return t.contains("int") || t.contains("decimal") || t.contains("numeric") || t.contains("money") || t.contains("float") || t.contains("real"); }
    private boolean isDateSqlType(String type) { String t = stringOr(type, "").toLowerCase(Locale.US); return t.contains("date") || t.contains("time"); }

    private Object nativeDefaultValue(SqlColumnMeta m) {
        String t = m == null ? "" : stringOr(m.type, "").toLowerCase(Locale.US);
        if (t.contains("bit")) return 0;
        if (isNumericSqlType(t)) return 0;
        if (isDateSqlType(t)) return new java.sql.Timestamp(System.currentTimeMillis());
        if (t.contains("uniqueidentifier")) return java.util.UUID.randomUUID().toString();
        if (t.contains("binary") || t.contains("image")) return new byte[0];
        return "";
    }

    private void setNativeParam(PreparedStatement ps, int idx, Object value, String type) throws Exception {
        String t = stringOr(type, "").toLowerCase(Locale.US);
        if (value == null) { ps.setNull(idx, java.sql.Types.NULL); return; }
        if (t.contains("bit")) { ps.setBoolean(idx, value instanceof Boolean ? (Boolean)value : parseNumber(String.valueOf(value), 0) != 0); return; }
        if (t.contains("bigint")) { ps.setLong(idx, Math.round(nativeDoubleValue(value))); return; }
        if (t.contains("int") || t.contains("smallint") || t.contains("tinyint")) { ps.setInt(idx, (int)Math.round(nativeDoubleValue(value))); return; }
        if (t.contains("decimal") || t.contains("numeric") || t.contains("money") || t.contains("float") || t.contains("real")) { ps.setDouble(idx, nativeDoubleValue(value)); return; }
        if (isDateSqlType(t)) { if (value instanceof java.sql.Timestamp) ps.setTimestamp(idx, (java.sql.Timestamp)value); else ps.setTimestamp(idx, new java.sql.Timestamp(System.currentTimeMillis())); return; }
        if (t.contains("binary") || t.contains("image")) { ps.setBytes(idx, value instanceof byte[] ? (byte[])value : new byte[0]); return; }
        ps.setString(idx, String.valueOf(value));
    }

    private double nativeDoubleValue(Object value) {
        if (value instanceof Number) return ((Number)value).doubleValue();
        return parseNumber(String.valueOf(value), 0);
    }

    private void markPrefactorInvoiceReadiness(Connection c, long id, String status) {
        if (c == null || id <= 0) return;
        try {
            String st = status == null ? "" : status;
            boolean ready = "sent".equals(st) || "approved".equals(st) || "pending_approval".equals(st);
            String invoiceStatus = ready ? "ready" : "not_ready";
            try (PreparedStatement ps = c.prepareStatement("UPDATE dbo.meelano_prefactors SET ready_for_invoice=?, invoice_status=?, system_convert_note=CASE WHEN NULLIF(system_convert_note,N'') IS NULL THEN ? ELSE system_convert_note END, updated_at=SYSDATETIME() WHERE id=?")) {
                ps.setBoolean(1, ready); ps.setString(2, invoiceStatus); ps.setString(3, ready ? "آماده تبدیل به فاکتور در سیستم از جدول/نمای meelano_prefactors_ready_for_invoice" : "پس از تایید/ارسال آماده تبدیل می‌شود"); ps.setLong(4, id); ps.executeUpdate();
            }
        } catch (Exception ignored) { }
    }

    /**
     * Reads the live approval state of each pre-invoice from Atiran's own table (dbo.sailfact_pish):
     * TaedForush = sales approval, TaedHesabdari = accounting approval, Rejected, sh_f = invoice number.
     * Adds it as r.atiran = {no, sales, accounting, rejected, invoice}. Silently skipped on other databases.
     */
    private void attachAtiranPishStatus(Connection c, JSONArray rows) {
        try {
            Map<Long, JSONObject> byNo = new HashMap<>();
            for (int i = 0; i < rows.length(); i++) {
                JSONObject o = rows.optJSONObject(i); if (o == null) continue;
                if (!"sailfact_pish".equalsIgnoreCase(o.optString("nativeTable", ""))) continue;
                try { long n = Long.parseLong(o.optString("nativeNo", "").trim()); if (n > 0) byNo.put(n, o); } catch (Exception ignored) { }
            }
            if (byNo.isEmpty()) return;
            try (PreparedStatement chk = c.prepareStatement("SELECT CASE WHEN OBJECT_ID(N'dbo.sailfact_pish') IS NULL THEN 0 ELSE 1 END"); ResultSet r = chk.executeQuery()) {
                if (!r.next() || r.getInt(1) != 1) return;
            }
            StringBuilder in = new StringBuilder();
            for (Long n : byNo.keySet()) { if (in.length() > 0) in.append(','); in.append(n); } // numbers only: safe to inline
            String sql = "SELECT h.shfacfo, ISNULL(CAST(h.TaedForush AS int),0), ISNULL(CAST(h.TaedHesabdari AS int),0), ISNULL(CAST(h.Rejected AS int),0), ISNULL(TRY_CONVERT(bigint,h.sh_f),0) " +
                    "FROM dbo.sailfact_pish h WHERE h.active='t' AND h.shfacfo IN (" + in + ")";
            try (PreparedStatement ps = c.prepareStatement(sql); ResultSet r = ps.executeQuery()) {
                while (r.next()) {
                    JSONObject o = byNo.get(r.getLong(1)); if (o == null) continue;
                    JSONObject a = new JSONObject();
                    a.put("no", r.getLong(1)); a.put("sales", r.getInt(2) == 1); a.put("accounting", r.getInt(3) == 1);
                    a.put("rejected", r.getInt(4) != 0); a.put("invoice", r.getLong(5));
                    o.put("atiran", a);
                }
            }
        } catch (Exception ignored) { }
    }

    /** Three small steps under a pre-invoice card: sales approval → accounting approval → invoiced. */
    private void addAtiranStatusSteps(LinearLayout parent, JSONObject a) {
        if (parent == null || a == null) return;
        LinearLayout box = new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(8), dp(6), dp(8), dp(6));
        box.setBackground(roundedStroke(alpha(INFO, 12), 14, alpha(INFO, 50)));
        TextView t = text("وضعیت در آتیران • پیش‌فاکتور شماره " + faDigits(String.valueOf(a.optLong("no"))), 10f, MUTED, Typeface.BOLD);
        box.addView(t, new LinearLayout.LayoutParams(-1, -2));
        LinearLayout steps = new LinearLayout(this); steps.setOrientation(LinearLayout.HORIZONTAL);
        if (a.optBoolean("rejected", false)) {
            steps.addView(pill("✕ رد شده", DANGER, true), new LinearLayout.LayoutParams(-2, -2));
        } else {
            boolean sales = a.optBoolean("sales", false), acc = a.optBoolean("accounting", false);
            long inv = a.optLong("invoice", 0);
            steps.addView(pill((sales ? "✓ " : "… ") + "تأیید فروش", sales ? SUCCESS : WARNING, sales), new LinearLayout.LayoutParams(0, -2, 1f));
            LinearLayout.LayoutParams sp = new LinearLayout.LayoutParams(0, -2, 1f); sp.setMargins(dp(4), 0, 0, 0);
            steps.addView(pill((acc ? "✓ " : "… ") + "تأیید حسابداری", acc ? SUCCESS : WARNING, acc), sp);
            LinearLayout.LayoutParams ip = new LinearLayout.LayoutParams(0, -2, 1f); ip.setMargins(dp(4), 0, 0, 0);
            steps.addView(pill(inv > 0 ? "✓ فاکتور " + faDigits(String.valueOf(inv)) : "… فاکتور نشده", inv > 0 ? SUCCESS : MUTED, inv > 0), ip);
        }
        for (int i = 0; i < steps.getChildCount(); i++) { View v = steps.getChildAt(i); if (v instanceof TextView) { ((TextView) v).setGravity(Gravity.CENTER); ((TextView) v).setSingleLine(true); } }
        LinearLayout.LayoutParams stp = new LinearLayout.LayoutParams(-1, -2); stp.setMargins(0, dp(5), 0, 0); box.addView(steps, stp);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(-1, -2); lp.setMargins(0, dp(7), 0, 0);
        parent.addView(box, lp);
    }

    private String prefactorInvoiceReadinessText(JSONObject r) {
        if (r == null) return "";
        String inv = r.optString("invoiceStatus", "");
        if ("invoiced".equals(inv) || "invoiced".equals(r.optString("status", ""))) return "تبدیل‌شده به فاکتور" + (r.optString("invoiceNumber", "").isEmpty() ? "" : " • " + r.optString("invoiceNumber", ""));
        if (r.optBoolean("readyForInvoice", false) || "ready".equals(inv)) return "آماده تبدیل به فاکتور در سیستم";
        if ("awaiting_approval".equals(inv)) return "پس از تایید آماده تبدیل می‌شود";
        return "ثبت شده؛ آماده‌سازی تبدیل پس از ارسال نهایی";
    }

    private double[] queryCartStockPriceRow(Connection c, String primarySql, String fallbackSql, String code) throws Exception {
        try { return queryCartStockPriceRowOnce(c, primarySql, code); }
        catch (Exception ex) { if (fallbackSql != null && !fallbackSql.trim().isEmpty()) return queryCartStockPriceRowOnce(c, fallbackSql, code); throw ex; }
    }

    private double[] queryCartStockPriceRowOnce(Connection c, String sql, String code) throws Exception {
        try (PreparedStatement ps = c.prepareStatement(sql)) {
            ps.setString(1, code == null ? "" : code);
            try (ResultSet r = ps.executeQuery()) {
                if (!r.next()) return null;
                return new double[]{r.getDouble(1), r.getDouble(2), r.getDouble(3)};
            }
        }
    }

    private JSONObject checkCartSnapshotAgainstInventory(Connection c, JSONArray items, boolean strict) throws Exception {
        JSONObject out = new JSONObject(); JSONArray warnings = new JSONArray(); boolean blocked = false;
        Set<String> cols = columns(c, "inventory");
        String shka = resolveProductKeyColumn(cols);
        if (shka == null) { out.put("warnings", warnings); return out; }
        String stock = resolveStockQuantityColumn(cols);
        String price1 = resolveSalePrice1Column(cols);
        String price2 = resolveSalePrice2Column(cols);
        Set<String> saleCols = columns(c, "subsailfact");
        Set<String> buyCols = columns(c, "subbuyfact");
        String saleKey = resolveFlexible(saleCols, "SHKA", "shka", "StuffCode", "KalaID", "ProductID", "product_code", "کد_کالا");
        String saleQty = resolveFlexible(saleCols, "tedad", "Tedad", "TEDVAH", "qty", "quantity", "Qty", "تعداد", "meghdar");
        String buyKey = resolveFlexible(buyCols, "shka", "SHKA", "StuffCode", "KalaID", "ProductID", "product_code", "کد_کالا");
        String buyQty = resolveFlexible(buyCols, "tedad", "Tedad", "TEDVAH", "qty", "quantity", "Qty", "تعداد", "meghdar");
        String relPriceTable = null, relPriceKey = null, relPrice1 = null, relPrice2 = null; Set<String> relPriceCols = null;
        for (String t : candidateDboTables(c, new String[]{"KalaPrice", "KalaPrices", "kala_price", "KalaFee", "KalaFi", "KalaNerkh", "NerkhKala", "PriceList", "Price_List", "ProductPrice", "ProductPrices", "ItemPrice", "ItemPrices", "tblKalaPrice", "tblPrice", "tblPrices"}, "price", "fee", "fi", "nerkh", "gheymat", "ghimat", "qeymat", "forosh", "foroosh", "فروش", "قیمت", "قيمت", "نرخ", "فی")) {
            if (t == null || t.equalsIgnoreCase("inventory") || t.equalsIgnoreCase("subsailfact") || t.equalsIgnoreCase("subbuyfact")) continue;
            Set<String> pc = columns(c, t); String pk = resolveRelatedProductKeyColumn(pc); String p1c = resolveSalePrice1Column(pc); String p2c = resolveSalePrice2Column(pc);
            if (pk != null && (p1c != null || p2c != null)) { relPriceTable = t; relPriceKey = pk; relPrice1 = p1c; relPrice2 = p2c; relPriceCols = pc; break; }
        }
        String relStockTable = null, relStockKey = null, relStockBalance = null, relStockIn = null, relStockOut = null, relStockQty = null, relStockDir = null; Set<String> relStockCols = null;
        for (String t : candidateDboTables(c, new String[]{"KalaMojoodi", "MojoodiKala", "MojoodiAnbar", "AnbarMojoodi", "KalaStock", "ProductStock", "InventoryStock", "WarehouseStock", "StockBalance", "InventoryBalance", "AnbarKala", "KalaAnbar", "KalaWarehouse", "vKalaMojoodi", "vwKalaMojoodi", "ViewMojoodiKala", "stock", "stocks", "tblStock", "kardex", "KalaKardex", "AnbarKardex", "subanbar", "SubAnbar", "subAnbFact", "WarehouseMovement"}, "stock", "mojood", "mojoodi", "mojudi", "mande", "remain", "balance", "anbar", "warehouse", "kardex", "gardesh", "movement", "موجودی", "موجودي", "مانده", "انبار", "گردش")) {
            if (t == null || t.equalsIgnoreCase("inventory") || t.equalsIgnoreCase("subsailfact") || t.equalsIgnoreCase("subbuyfact")) continue;
            Set<String> sc = columns(c, t); String sk = resolveRelatedProductKeyColumn(sc); String sb = resolveStockBalanceColumn(sc); String sin = resolveStockMovementInColumn(sc); String sout = resolveStockMovementOutColumn(sc); String sq = resolveStockMovementQtyColumn(sc); String sd = resolveStockDirectionColumn(sc);
            if (sk != null && (sb != null || (sin != null && sout != null) || (sq != null && sd != null) || (sq != null && tableNameLooksStockSummary(t)))) { relStockTable = t; relStockKey = sk; relStockBalance = sb; relStockIn = sin; relStockOut = sout; relStockQty = sq; relStockDir = sd; relStockCols = sc; break; }
        }
        String saleSoft = softDeleteCondition(saleCols, "s");
        String buySoft = softDeleteCondition(buyCols, "b");
        String saleApply = saleKey != null ? "OUTER APPLY (SELECT " + (saleQty == null ? "CAST(0 AS decimal(19,3))" : "ISNULL(SUM(" + sqlNumberExpr("s", saleQty, "decimal(19,3)") + "),0)") + " sale_qty FROM dbo.subsailfact s WHERE TRY_CONVERT(nvarchar(100),s.[" + saleKey + "])=TRY_CONVERT(nvarchar(100),i.[" + shka + "])" + activeAnd(saleCols, "s") + (saleSoft.isEmpty()?"":" AND "+saleSoft) + ") sa " : "OUTER APPLY (SELECT CAST(0 AS decimal(19,3)) sale_qty) sa ";
        String buyApply = buyKey != null ? "OUTER APPLY (SELECT " + (buyQty == null ? "CAST(0 AS decimal(19,3))" : "ISNULL(SUM(" + sqlNumberExpr("b", buyQty, "decimal(19,3)") + "),0)") + " buy_qty FROM dbo.subbuyfact b WHERE TRY_CONVERT(nvarchar(100),b.[" + buyKey + "])=TRY_CONVERT(nvarchar(100),i.[" + shka + "])" + activeAnd(buyCols, "b") + (buySoft.isEmpty()?"":" AND "+buySoft) + ") ba " : "OUTER APPLY (SELECT CAST(0 AS decimal(19,3)) buy_qty) ba ";
        String relPriceSoft = softDeleteCondition(relPriceCols == null ? new HashSet<String>() : relPriceCols, "pr");
        String priceApply = relPriceTable != null && relPriceKey != null ? "OUTER APPLY (SELECT TOP (1) " + sqlNumberExpr("pr", relPrice1, "decimal(19,2)") + " price1, " + sqlNumberExpr("pr", relPrice2, "decimal(19,2)") + " price2 FROM dbo.[" + relPriceTable + "] pr WHERE TRY_CONVERT(nvarchar(100),pr.[" + relPriceKey + "])=TRY_CONVERT(nvarchar(100),i.[" + shka + "])" + activeAnd(relPriceCols, "pr") + (relPriceSoft.isEmpty()?"":" AND "+relPriceSoft) + relatedTopOrder(relPriceCols, "pr") + ") prx " : "OUTER APPLY (SELECT CAST(NULL AS decimal(19,2)) price1, CAST(NULL AS decimal(19,2)) price2) prx ";
        String stockApply = relatedStockApply(relStockTable, relStockCols, relStockKey, relStockBalance, relStockIn, relStockOut, relStockQty, relStockDir, "i", shka, "stx");
        String invP1 = sqlNumberExpr("i", price1, "decimal(19,2)");
        String invP2 = sqlNumberExpr("i", price2, "decimal(19,2)");
        String p1Expr = "COALESCE(NULLIF(prx.price1,0)," + invP1 + ",0)";
        String p2RawExpr = "COALESCE(NULLIF(prx.price2,0)," + invP2 + ",0)";
        String p2FinalExpr = "CASE WHEN ISNULL(" + p2RawExpr + ",0)>0 THEN " + p2RawExpr + " WHEN ISNULL(" + p1Expr + ",0)>0 THEN ROUND(" + p1Expr + "*1.06,0) ELSE 0 END";
        String movement = "(ISNULL(ba.buy_qty,0)-ISNULL(sa.sale_qty,0))";
        String invStock = stock == null ? "CAST(NULL AS decimal(19,3))" : sqlNumberExpr("i", stock, "decimal(19,3)");
        String stockExpr = "CASE WHEN ISNULL(stx.stock_rows,0)>0 THEN ISNULL(stx.stock_qty,0) ELSE COALESCE(" + invStock + "," + movement + ",0) END";
        boolean hasReliableStockSource = relStockTable != null || stock != null || (saleKey != null && saleQty != null && buyKey != null && buyQty != null);
        String sql = "SELECT " + stockExpr + " AS st," + p1Expr + " AS p1," + p2FinalExpr + " AS p2 FROM dbo.inventory i " + saleApply + buyApply + priceApply + stockApply + " WHERE TRY_CONVERT(nvarchar(100),i.[" + shka + "])=?";
        String fallbackSql = relStockTable == null ? null : "SELECT " + stockExpr + " AS st," + p1Expr + " AS p1," + p2FinalExpr + " AS p2 FROM dbo.inventory i " + saleApply + buyApply + priceApply + relatedStockApply(null, null, null, null, null, null, null, null, "i", shka, "stx") + " WHERE TRY_CONVERT(nvarchar(100),i.[" + shka + "])=?";
        for (int i=0; items!=null && i<items.length(); i++) {
            JSONObject it=items.optJSONObject(i); if (it==null) continue;
            double[] row = queryCartStockPriceRow(c, sql, fallbackSql, it.optString("code", ""));
            if(row == null){ warnings.put("کالا پیدا نشد: "+it.optString("name","")); blocked=true; continue; }
            double st=row[0]; double p1=row[1]; double p2=row[2];
            if(hasReliableStockSource && st<it.optDouble("qty",0)){ warnings.put("موجودی کافی نیست: "+it.optString("name","")+" / موجودی "+formatNumber(st)); blocked=true; }
            double dbPrice="m".equals(it.optString("priceTier","1"))?0:("2".equals(it.optString("priceTier","1"))?p2:p1);
            if(dbPrice>0 && Math.abs(dbPrice-it.optDouble("price",0))>1){ warnings.put("قیمت کالا تغییر کرده: "+it.optString("name","")); if(strict) blocked=true; }
        }
        out.put("warnings", warnings); out.put("blocked", blocked); out.put("ok", !blocked);
        if (strict && blocked) throw new DbException(warnings.length()>0 ? warnings.optString(0) : "کنترل موجودی/قیمت تایید نشد.");
        return out;
    }

    private void ensurePrefactorTables(Connection c) throws Exception {
        try (Statement st = c.createStatement()) {
            st.execute("IF OBJECT_ID(N'dbo.meelano_prefactors',N'U') IS NULL CREATE TABLE dbo.meelano_prefactors (id bigint IDENTITY(1,1) NOT NULL PRIMARY KEY, client_uuid nvarchar(80) NULL, visitor_username nvarchar(160) NULL, visitor_id nvarchar(80) NULL, customer_code nvarchar(100) NULL, customer_name nvarchar(250) NULL, notes nvarchar(max) NULL, signature_data nvarchar(max) NULL, total_amount decimal(19,2) NULL, subtotal_amount decimal(19,2) NULL, global_discount decimal(19,2) NULL, tax_percent decimal(9,3) NULL, tax_amount decimal(19,2) NULL, grand_total decimal(19,2) NULL, status nvarchar(30) NOT NULL DEFAULT N'draft', approval_reason nvarchar(700) NULL, delivery_date nvarchar(40) NULL, delivery_address nvarchar(700) NULL, settlement_type nvarchar(80) NULL, payment_ref nvarchar(160) NULL, created_at datetime2 NOT NULL DEFAULT SYSDATETIME(), updated_at datetime2 NULL)");
            st.execute("IF OBJECT_ID(N'dbo.meelano_prefactor_items',N'U') IS NULL CREATE TABLE dbo.meelano_prefactor_items (id bigint IDENTITY(1,1) NOT NULL PRIMARY KEY, prefactor_id bigint NOT NULL, product_code nvarchar(100) NULL, product_name nvarchar(500) NULL, unit nvarchar(80) NULL, qty decimal(19,4) NULL, price decimal(19,2) NULL, amount decimal(19,2) NULL, stock_snapshot decimal(19,4) NULL, pack_count decimal(19,4) NULL, price_tier nvarchar(10) NULL, line_discount decimal(19,2) NULL, line_note nvarchar(700) NULL)");
            for (String sql : new String[]{
                    "IF COL_LENGTH('dbo.meelano_prefactors','client_uuid') IS NULL ALTER TABLE dbo.meelano_prefactors ADD client_uuid nvarchar(80) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','delivery_date') IS NULL ALTER TABLE dbo.meelano_prefactors ADD delivery_date nvarchar(40) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','delivery_address') IS NULL ALTER TABLE dbo.meelano_prefactors ADD delivery_address nvarchar(700) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','settlement_type') IS NULL ALTER TABLE dbo.meelano_prefactors ADD settlement_type nvarchar(80) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','payment_ref') IS NULL ALTER TABLE dbo.meelano_prefactors ADD payment_ref nvarchar(160) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','subtotal_amount') IS NULL ALTER TABLE dbo.meelano_prefactors ADD subtotal_amount decimal(19,2) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','global_discount') IS NULL ALTER TABLE dbo.meelano_prefactors ADD global_discount decimal(19,2) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','tax_percent') IS NULL ALTER TABLE dbo.meelano_prefactors ADD tax_percent decimal(9,3) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','tax_amount') IS NULL ALTER TABLE dbo.meelano_prefactors ADD tax_amount decimal(19,2) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','grand_total') IS NULL ALTER TABLE dbo.meelano_prefactors ADD grand_total decimal(19,2) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','approval_reason') IS NULL ALTER TABLE dbo.meelano_prefactors ADD approval_reason nvarchar(700) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','ready_for_invoice') IS NULL ALTER TABLE dbo.meelano_prefactors ADD ready_for_invoice bit NOT NULL DEFAULT 0",
                    "IF COL_LENGTH('dbo.meelano_prefactors','invoice_status') IS NULL ALTER TABLE dbo.meelano_prefactors ADD invoice_status nvarchar(40) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','invoice_number') IS NULL ALTER TABLE dbo.meelano_prefactors ADD invoice_number nvarchar(80) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','invoice_at') IS NULL ALTER TABLE dbo.meelano_prefactors ADD invoice_at datetime2 NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','system_convert_note') IS NULL ALTER TABLE dbo.meelano_prefactors ADD system_convert_note nvarchar(700) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','native_prefactor_table') IS NULL ALTER TABLE dbo.meelano_prefactors ADD native_prefactor_table nvarchar(120) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','native_prefactor_no') IS NULL ALTER TABLE dbo.meelano_prefactors ADD native_prefactor_no nvarchar(120) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','native_sync_at') IS NULL ALTER TABLE dbo.meelano_prefactors ADD native_sync_at datetime2 NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactors','updated_at') IS NULL ALTER TABLE dbo.meelano_prefactors ADD updated_at datetime2 NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactor_items','price_tier') IS NULL ALTER TABLE dbo.meelano_prefactor_items ADD price_tier nvarchar(10) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactor_items','line_discount') IS NULL ALTER TABLE dbo.meelano_prefactor_items ADD line_discount decimal(19,2) NULL",
                    "IF COL_LENGTH('dbo.meelano_prefactor_items','line_note') IS NULL ALTER TABLE dbo.meelano_prefactor_items ADD line_note nvarchar(700) NULL"
            }) st.execute(sql);
            st.execute("IF OBJECT_ID(N'dbo.meelano_visit_results',N'U') IS NULL CREATE TABLE dbo.meelano_visit_results (id bigint IDENTITY(1,1) PRIMARY KEY, visitor_username nvarchar(160) NULL, visitor_id nvarchar(80) NULL, customer_code nvarchar(100) NULL, customer_name nvarchar(250) NULL, result nvarchar(120) NULL, notes nvarchar(700) NULL, created_at datetime2 NOT NULL DEFAULT SYSDATETIME())");
            try { st.execute("IF COL_LENGTH('dbo.meelano_visit_results','lat') IS NULL ALTER TABLE dbo.meelano_visit_results ADD lat float NULL, lng float NULL"); } catch (Exception ignored) { }
            st.execute("IF OBJECT_ID(N'dbo.meelano_day_reports',N'U') IS NULL CREATE TABLE dbo.meelano_day_reports (id bigint IDENTITY(1,1) PRIMARY KEY, visitor_username nvarchar(160) NULL, visitor_id nvarchar(80) NULL, report_text nvarchar(max) NULL, created_at datetime2 NOT NULL DEFAULT SYSDATETIME())");
            try { st.execute("IF OBJECT_ID(N'dbo.meelano_prefactors_ready_for_invoice',N'V') IS NOT NULL DROP VIEW dbo.meelano_prefactors_ready_for_invoice"); } catch (Exception ignored) { }
            try { st.execute("CREATE VIEW dbo.meelano_prefactors_ready_for_invoice AS SELECT p.id,p.client_uuid,p.visitor_username,p.visitor_id,p.customer_code,p.customer_name,p.grand_total,p.status,p.created_at,p.ready_for_invoice,p.invoice_status,COUNT(i.id) AS item_count,ISNULL(SUM(i.amount),0) AS items_amount FROM dbo.meelano_prefactors p LEFT JOIN dbo.meelano_prefactor_items i ON i.prefactor_id=p.id WHERE ISNULL(p.ready_for_invoice,0)=1 AND ISNULL(p.invoice_status,N'')<>N'invoiced' GROUP BY p.id,p.client_uuid,p.visitor_username,p.visitor_id,p.customer_code,p.customer_name,p.grand_total,p.status,p.created_at,p.ready_for_invoice,p.invoice_status"); } catch (Exception ignored) { }
        }
    }


    private String prefactorStatusFa(String st) {
        if ("draft".equals(st)) return "پیش‌نویس";
        if ("sent".equals(st)) return "ارسال‌شده";
        if ("pending_approval".equals(st)) return "در انتظار تایید";
        if ("approved".equals(st)) return "تایید شده";
        if ("rejected".equals(st)) return "رد شده";
        if ("needs_revision".equals(st)) return "نیازمند اصلاح";
        if ("invoiced".equals(st)) return "تبدیل‌شده به فاکتور";
        if ("canceled".equals(st)) return "لغو شده";
        return stringOr(st, "نامشخص");
    }

    private String prefactorScopeWhere(String alias, List<Object> params) {
        String pfx = alias == null || alias.trim().isEmpty() ? "" : alias + ".";
        String role = session == null ? "" : canonicalAccessRole(session.accessRole);
        if ("admin".equals(role) || "manager".equals(role) || "senior_accountant".equals(role) || "accountant".equals(role) || "collections".equals(role)) return "";
        List<String> parts = new ArrayList<>();
        String user = currentAccountName();
        if (user != null && !user.trim().isEmpty()) { parts.add("LTRIM(RTRIM(" + pfx + "visitor_username))=?"); params.add(user.trim()); }
        Integer vid = currentVisitorScopeId();
        if (vid != null && vid > 0) { parts.add("LTRIM(RTRIM(" + pfx + "visitor_id))=?"); params.add(String.valueOf(vid)); }
        return parts.isEmpty() ? "" : " WHERE (" + join(parts, " OR ") + ")";
    }

    private void loadMyPrefactors() {
        if (!canUsePermission("prefactor_list")) { redirectToAllowedPage("prefactor_list"); return; }
        content.removeAllViews(); if (!VISITOR_EDITION) addHero("پیش‌فاکتورهای من", "پیگیری، ویرایش پیش‌نویس، ارسال مجدد، PDF و وضعیت تایید");
        addManualRefreshPanel("cart", "بروزرسانی پیش‌فاکتورها", "نمایش آخرین سفارش‌های ویزیتور", () -> loadMyPrefactors());
        LinearLayout list = new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); content.addView(list, new LinearLayout.LayoutParams(-1, -2)); addLoading(list, "در حال دریافت پیش‌فاکتورها…");
        runDb(this::queryMyPrefactorsSql, new DbCallback() { @Override public void ok(String body) { try { renderMyPrefactors(new JSONArray(body)); } catch(Exception e){ showPageError("پیش‌فاکتورهای من", e, () -> loadMyPrefactors()); } } @Override public void fail(Exception e){ showPageError("پیش‌فاکتورهای من", e, () -> loadMyPrefactors()); } });
    }

    private String queryMyPrefactorsSql() throws Exception {
        try (Connection c = openConnection()) {
            ensurePrefactorTables(c);
            repairUnsyncedNativePrefactors(c);
            List<Object> params = new ArrayList<>(); String where = prefactorScopeWhere("p", params);
            String sql = "SELECT TOP (100) p.id, TRY_CONVERT(nvarchar(30),p.created_at), p.status, p.customer_code, p.customer_name, ISNULL(p.grand_total,p.total_amount), p.settlement_type, p.delivery_date, p.approval_reason, ISNULL(x.cnt,0), ISNULL(p.ready_for_invoice,0), ISNULL(p.invoice_status,N''), ISNULL(p.invoice_number,N''), ISNULL(p.native_prefactor_table,N''), ISNULL(p.native_prefactor_no,N'') FROM dbo.meelano_prefactors p OUTER APPLY (SELECT COUNT_BIG(1) cnt FROM dbo.meelano_prefactor_items i WHERE i.prefactor_id=p.id) x" + where + " ORDER BY p.created_at DESC, p.id DESC";
            JSONArray arr = new JSONArray();
            try (PreparedStatement ps = c.prepareStatement(sql)) { setParams(ps, params); try(ResultSet r = ps.executeQuery()) { while(r.next()){ JSONObject o=new JSONObject(); o.put("id", r.getLong(1)); o.put("date", stringOr(r.getString(2), "")); o.put("status", stringOr(r.getString(3), "")); o.put("customerCode", stringOr(r.getString(4), "")); o.put("customerName", stringOr(r.getString(5), "")); o.put("total", r.getDouble(6)); o.put("settlement", stringOr(r.getString(7), "")); o.put("delivery", stringOr(r.getString(8), "")); o.put("reason", stringOr(r.getString(9), "")); o.put("items", r.getLong(10)); o.put("readyForInvoice", r.getBoolean(11)); o.put("invoiceStatus", stringOr(r.getString(12), "")); o.put("invoiceNumber", stringOr(r.getString(13), "")); o.put("nativeTable", stringOr(r.getString(14), "")); o.put("nativeNo", stringOr(r.getString(15), "")); arr.put(o); } } }
            attachAtiranPishStatus(c, arr);
            return arr.toString();
        }
    }

    private String prefactorDateKey(JSONObject r) {
        String d = r == null ? "" : r.optString("date", "");
        if (d == null || d.trim().isEmpty()) return "بدون تاریخ";
        d = d.trim().replace('T', ' ');
        int sp = d.indexOf(' ');
        return sp > 0 ? d.substring(0, sp) : (d.length() >= 10 ? d.substring(0, 10) : d);
    }

    private String prefactorTimeKey(JSONObject r) {
        String d = r == null ? "" : r.optString("date", "");
        if (d == null) return "—";
        d = d.trim().replace('T', ' ');
        int sp = d.indexOf(' ');
        if (sp < 0 || sp + 1 >= d.length()) return "—";
        String t = d.substring(sp + 1).trim();
        return t.length() >= 5 ? t.substring(0, 5) : t;
    }

    private int prefactorStatusAccent(String st) {
        if ("approved".equals(st) || "invoiced".equals(st)) return SUCCESS;
        if ("rejected".equals(st) || "needs_revision".equals(st) || "canceled".equals(st)) return DANGER;
        if ("pending_approval".equals(st)) return WARNING;
        if ("draft".equals(st)) return INFO;
        return navAccent("cart");
    }

    private int prefactorStatusCount(JSONArray rows, String status) {
        int n = 0; if (rows != null) for (int i=0;i<rows.length();i++){ JSONObject r=rows.optJSONObject(i); if(r!=null && (status == null || status.equals(r.optString("status","")))) n++; }
        return n;
    }

    private double prefactorRowsTotal(JSONArray rows) {
        double t=0; if(rows!=null) for(int i=0;i<rows.length();i++){ JSONObject r=rows.optJSONObject(i); if(r!=null) t+=r.optDouble("total",0); }
        return t;
    }

