    private void saveVisitResult(JSONObject customer,String result,String note){
        final double[] loc = lastKnownLatLng();
        appendVisitLog(customer, result, loc);
        runDb(() -> { try(Connection c=openConnection()){ ensurePrefactorTables(c);
            boolean hasLoc = false;
            try (PreparedStatement chk = c.prepareStatement("SELECT CASE WHEN COL_LENGTH('dbo.meelano_visit_results','lat') IS NULL THEN 0 ELSE 1 END"); ResultSet rr = chk.executeQuery()) { hasLoc = rr.next() && rr.getInt(1) == 1; }
            String sql = hasLoc
                    ? "INSERT INTO dbo.meelano_visit_results(visitor_username,visitor_id,customer_code,customer_name,result,notes,created_at,lat,lng) VALUES(?,?,?,?,?,?,SYSDATETIME(),?,?)"
                    : "INSERT INTO dbo.meelano_visit_results(visitor_username,visitor_id,customer_code,customer_name,result,notes,created_at) VALUES(?,?,?,?,?,?,SYSDATETIME())";
            try(PreparedStatement ps=c.prepareStatement(sql)){ ps.setString(1,currentAccountName()); ps.setString(2,currentVisitorScopeId()==null?"":String.valueOf(currentVisitorScopeId())); ps.setString(3,customer.optString("code","")); ps.setString(4,customer.optString("name","")); ps.setString(5,result); ps.setString(6,note);
                if (hasLoc) { if (loc == null) { ps.setNull(7, java.sql.Types.FLOAT); ps.setNull(8, java.sql.Types.FLOAT); } else { ps.setDouble(7, loc[0]); ps.setDouble(8, loc[1]); } }
                ps.executeUpdate(); } } return "ok"; }, new DbCallback(){ @Override public void ok(String b){ showNotice("نتیجه بازدید ثبت شد.", false); } @Override public void fail(Exception e){ saveLocalVisitResult(customer,result,note); showNotice("نتیجه به‌صورت محلی نگهداری شد.", true); }});
    }

    // ---------------------------------------------------------------------------------------------
    // Visit location + today's route. Every visit is logged on the phone (with location when the
    // visitor allowed it); the route opens in the phone's map app.
    // ---------------------------------------------------------------------------------------------
    private static final String KEY_VISIT_LOG = "visit_log_local";
    private static final String KEY_LOCATION_ASKED = "visit_location_asked";

    private boolean hasLocationPermission() {
        return Build.VERSION.SDK_INT < 23 || checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) == PackageManager.PERMISSION_GRANTED
                || checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED;
    }

    /** Asks once (on the visit page) for location, so visits can be placed on the route map. */
    private void maybeAskVisitLocationPermission() {
        if (designPreview || prefs == null || hasLocationPermission() || prefs.getBoolean(KEY_LOCATION_ASKED, false) || Build.VERSION.SDK_INT < 23) return;
        prefs.edit().putBoolean(KEY_LOCATION_ASKED, true).apply();
        AlertDialog dlg = new MeelanoDialogBuilder()
                .setTitle("ثبت محل ویزیت")
                .setMessage("برای نمایش مسیر روزانه روی نقشه، محل هر ویزیت ثبت شود؟ موقعیت فقط هنگام ثبت ویزیت خوانده می‌شود.")
                .setNegativeButton("نه", null)
                .setPositiveButton("بله", (d, w) -> requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION, Manifest.permission.ACCESS_FINE_LOCATION}, 9221))
                .create();
        dlg.setOnShowListener(d -> styleMeelanoDialog(dlg, navAccent("visit")));
        dlg.show();
    }

    /** Newest last-known position from GPS / network / passive providers; null when unknown. */
    @SuppressWarnings("MissingPermission")
    private double[] lastKnownLatLng() {
        if (!hasLocationPermission()) return null;
        try {
            android.location.LocationManager lm = (android.location.LocationManager) getSystemService(Context.LOCATION_SERVICE);
            if (lm == null) return null;
            android.location.Location best = null;
            for (String p : new String[]{android.location.LocationManager.GPS_PROVIDER, android.location.LocationManager.NETWORK_PROVIDER, android.location.LocationManager.PASSIVE_PROVIDER}) {
                try {
                    android.location.Location l = lm.getLastKnownLocation(p);
                    if (l != null && (best == null || l.getTime() > best.getTime())) best = l;
                } catch (Exception ignored) { }
            }
            // Older than 30 minutes is not "here" any more.
            if (best == null || System.currentTimeMillis() - best.getTime() > 30L * 60 * 1000) return null;
            return new double[]{best.getLatitude(), best.getLongitude()};
        } catch (Exception ignored) { return null; }
    }

    private JSONArray visitLog() {
        try { return new JSONArray(prefs == null ? "[]" : prefs.getString(KEY_VISIT_LOG, "[]")); } catch (Exception ignored) { return new JSONArray(); }
    }

    private void appendVisitLog(JSONObject customer, String result, double[] loc) {
        try {
            JSONArray a = visitLog();
            JSONObject o = new JSONObject();
            o.put("code", customer == null ? "" : customer.optString("code", ""));
            o.put("name", customer == null ? "" : customer.optString("name", ""));
            o.put("result", stringOr(result, ""));
            o.put("time", nowText());
            if (loc != null) { o.put("lat", loc[0]); o.put("lng", loc[1]); }
            a.put(o);
            JSONArray lim = new JSONArray();
            for (int i = Math.max(0, a.length() - 200); i < a.length(); i++) lim.put(a.optJSONObject(i));
            prefs.edit().putString(KEY_VISIT_LOG, lim.toString()).apply();
        } catch (Exception ignored) { }
    }

    private JSONArray todayVisitLog() {
        JSONArray out = new JSONArray(); String today = todayDateText(); JSONArray a = visitLog();
        for (int i = 0; i < a.length(); i++) { JSONObject o = a.optJSONObject(i); if (o != null && o.optString("time", "").startsWith(today)) out.put(o); }
        return out;
    }

    /** Opens today's visits in order as a route in the map app (Google Maps directions URL). */
    private void openTodayRouteMap() {
        JSONArray today = todayVisitLog();
        StringBuilder path = new StringBuilder();
        int points = 0;
        for (int i = 0; i < today.length(); i++) {
            JSONObject o = today.optJSONObject(i);
            if (o == null || !o.has("lat")) continue;
            path.append('/').append(String.format(java.util.Locale.US, "%.6f,%.6f", o.optDouble("lat"), o.optDouble("lng")));
            points++;
        }
        if (points == 0) {
            showNotice(hasLocationPermission() ? "امروز هنوز ویزیتی با موقعیت ثبت نشده است." : "برای مسیر روزانه، اجازه موقعیت مکانی را در تنظیمات گوشی بدهید.", true);
            return;
        }
        try { startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse("https://www.google.com/maps/dir" + path))); }
        catch (Exception ex) { showNotice("برنامه نقشه پیدا نشد.", false); }
    }

    /** Visit page card: today's visits in time order + «مسیر امروز روی نقشه». */
    private void addTodayRouteCard() {
        JSONArray today = todayVisitLog();
        int accent = navAccent("visit");
        LinearLayout c = card(); c.setBackground(themedSectionBg("visit", 26));
        c.addView(visitorSectionTitle("مسیر امروز", "⌖", accent), new LinearLayout.LayoutParams(-1, -2));
        c.addView(text(today.length() == 0 ? "هنوز ویزیتی ثبت نشده است." : faDigits(String.valueOf(today.length())) + " ویزیت ثبت شده است.", 10.6f, MUTED, Typeface.BOLD), new LinearLayout.LayoutParams(-1, -2));
        for (int i = Math.max(0, today.length() - 6); i < today.length(); i++) {
            JSONObject o = today.optJSONObject(i); if (o == null) continue;
            String t = o.optString("time", ""); int sp = t.indexOf(' ');
            String hm = sp > 0 && t.length() >= sp + 6 ? t.substring(sp + 1, sp + 6) : "";
            TextView row = text(faDigits(hm) + "  •  " + o.optString("name", "مشتری") + (o.optString("result", "").isEmpty() ? "" : "  •  " + o.optString("result", "")) + (o.has("lat") ? "  📍" : ""), 11f, TEXT, Typeface.BOLD);
            row.setSingleLine(true); row.setEllipsize(TextUtils.TruncateAt.END);
            LinearLayout.LayoutParams rp = new LinearLayout.LayoutParams(-1, -2); rp.setMargins(0, dp(5), 0, 0); c.addView(row, rp);
        }
        Button map = themedActionButton("مسیر امروز روی نقشه", accent, false);
        map.setOnClickListener(v -> openTodayRouteMap());
        LinearLayout.LayoutParams mp = new LinearLayout.LayoutParams(-1, dp(48)); mp.setMargins(0, dp(9), 0, 0); c.addView(map, mp);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(-1, -2); lp.setMargins(0, 0, 0, dp(12)); content.addView(c, lp);
    }

    private void showEndOfDayReportDialog(){
        if (!canUsePermission("day_report")) { showNotice("گزارش پایان روز برای این حساب فعال نیست.", false); return; }
        runDb(this::queryEndOfDayReportSql,new DbCallback(){ @Override public void ok(String body){ showEndOfDayReportText(body); } @Override public void fail(Exception e){ showEndOfDayReportText("جمع‌بندی آفلاین\nپیش‌نویس محلی: "+formatNumber(localDrafts().length())+"\nصف ارسال: "+formatNumber(offlineQueue().length())+"\n"+readableError(e)); }});
    }

    private String queryEndOfDayReportSql() throws Exception { try(Connection c=openConnection()){ ensurePrefactorTables(c); List<Object> params=new ArrayList<>(); String where=prefactorScopeWhere("p",params); String and=where.isEmpty()?" WHERE ":where+" AND "; String sql="SELECT COUNT_BIG(1), ISNULL(SUM(ISNULL(grand_total,total_amount)),0), SUM(CASE WHEN status=N'draft' THEN 1 ELSE 0 END), SUM(CASE WHEN status=N'pending_approval' THEN 1 ELSE 0 END) FROM dbo.meelano_prefactors p"+and+" CONVERT(date,p.created_at)=CONVERT(date,SYSDATETIME())"; long cnt=0,draft=0,pending=0; double total=0; try(PreparedStatement ps=c.prepareStatement(sql)){ setParams(ps,params); try(ResultSet r=ps.executeQuery()){ if(r.next()){cnt=r.getLong(1); total=r.getDouble(2); draft=r.getLong(3); pending=r.getLong(4);} } } return "گزارش پایان روز ویزیتور\nپیش‌فاکتور امروز: "+formatNumber(cnt)+"\nجمع مبلغ: "+money(total)+"\nپیش‌نویس: "+formatNumber(draft)+"\nدر انتظار تایید: "+formatNumber(pending)+"\nصف آفلاین گوشی: "+formatNumber(offlineQueue().length()); } }

    private void showEndOfDayReportText(String body){ AlertDialog dlg=new MeelanoDialogBuilder().setTitle("جمع‌بندی پایان روز").setMessage(body).setNegativeButton("بستن",null).setPositiveButton("اشتراک/ثبت",(d,w)->{ sharePlainText("گزارش پایان روز MEELANO",body,null); saveEndOfDayReport(body); }).create(); dlg.show(); }

    private void saveEndOfDayReport(String body){ runDb(() -> { try(Connection c=openConnection()){ ensurePrefactorTables(c); try(PreparedStatement ps=c.prepareStatement("INSERT INTO dbo.meelano_day_reports(visitor_username,visitor_id,report_text,created_at) VALUES(?,?,?,SYSDATETIME())")){ ps.setString(1,currentAccountName()); ps.setString(2,currentVisitorScopeId()==null?"":String.valueOf(currentVisitorScopeId())); ps.setString(3,body); ps.executeUpdate(); } } return "ok"; }, new DbCallback(){ @Override public void ok(String b){ showNotice("گزارش پایان روز ثبت شد.", false); } @Override public void fail(Exception e){ showNotice("ثبت گزارش آنلاین انجام نشد.", true); }}); }

    private class SignaturePadView extends View {
        private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Path path = new Path();
        SignaturePadView(Context context) { super(context); p.setColor(TEXT); p.setStrokeWidth(dp(3)); p.setStyle(Paint.Style.STROKE); p.setStrokeCap(Paint.Cap.ROUND); p.setStrokeJoin(Paint.Join.ROUND); setBackground(roundedStroke(alpha(SURFACE_2, 220), 18, alpha(navAccent("cart"), 90))); }
        @Override protected void onDraw(Canvas c) { super.onDraw(c); c.drawPath(path, p); }
        @Override public boolean onTouchEvent(MotionEvent e) { float x=e.getX(), y=e.getY(); if(e.getAction()==MotionEvent.ACTION_DOWN){ path.moveTo(x,y); invalidate(); return true; } if(e.getAction()==MotionEvent.ACTION_MOVE){ path.lineTo(x,y); invalidate(); return true; } return true; }
        void clear() { path.reset(); invalidate(); }
        String exportPngBase64() { try { Bitmap b=Bitmap.createBitmap(Math.max(1,getWidth()), Math.max(1,getHeight()), Bitmap.Config.ARGB_8888); Canvas c=new Canvas(b); draw(c); ByteArrayOutputStream out=new ByteArrayOutputStream(); b.compress(Bitmap.CompressFormat.PNG, 90, out); return Base64.encodeToString(out.toByteArray(), Base64.NO_WRAP); } catch(Exception ex){ return ""; } }
    }

    private void loadProducts(String query) { loadProducts(query, "all", false); }

    private void loadProducts(String query, String filter) { loadProducts(query, filter, false); }

    private void loadProducts(String query, String filter, boolean force) {
        String q = query == null ? "" : query;
        String f = filter == null || filter.trim().isEmpty() ? "all" : filter;
        if (!force && productsCacheJson != null && !productsCacheJson.trim().isEmpty() && q.equals(productsCacheQuery) && f.equals(productsCacheFilter)) {
            try { renderProductsFromJson(new JSONArray(productsCacheJson), q, f); return; } catch (Exception ignored) { }
        }
        content.removeAllViews();
        addHero("کالا و انبار", "اطلاعات کالاها ثابت می‌ماند؛ برای داده جدید تازه‌سازی دستی کنید.");
        addManualRefreshPanel("products", "بروزرسانی دستی کالاها", "فیلتر فعلی بدون تازه‌سازی دستی ثابت می‌ماند", () -> loadProducts(q, f, true));
        addSearchBox("جستجوی کالا…", q, qq -> loadProducts(qq, f, true));
        addProductFilterChips(q, f);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        content.addView(list, new LinearLayout.LayoutParams(-1, -2));
        addLoading(list, "در حال دریافت کالاها…");
        runDb(() -> queryProducts(q, f), new DbCallback() {
            @Override public void ok(String body) {
                try {
                    productsCacheJson = body;
                    productsCacheQuery = q;
                    productsCacheFilter = f;
                    markRefresh("products");
                    renderProductsFromJson(new JSONArray(body), q, f);
                } catch (Exception e) { showPageError("کالا", e, () -> loadProducts(q, f, true)); }
            }
            @Override public void fail(Exception e) { showPageError("کالا", e, () -> loadProducts(q, f, true)); }
        });
    }

    private void renderProductsFromJson(JSONArray rows, String query, String filter) {
        content.removeAllViews();
        addHero("کالا و انبار", "فیلتر موجودی، گردش خرید/فروش و کارت‌های کالا با تم MEELANO");
        addManualRefreshPanel("products", "بروزرسانی دستی کالاها", "آخرین لیست ثابت نگه داشته شده است", () -> loadProducts(query, filter, true));
        addSearchBox("جستجوی کالا…", query, q -> loadProducts(q, filter, true));
        addProductFilterChips(query, filter);
        LinearLayout list = new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); content.addView(list, new LinearLayout.LayoutParams(-1, -2));
        if (rows == null || rows.length() == 0) { addEmptyTo(list, "کالایی مطابق فیلتر پیدا نشد."); return; }
        for (int i = 0; i < rows.length(); i++) addProductCard(list, rows.optJSONObject(i));
    }

    private void addProductFilterChips(String query, String activeFilter) {
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.HORIZONTAL);
        String[][] filters = {{"all","همه"},{"stock","موجود"},{"low","کم/منفی"},{"top","پرفروش"},{"idle","بدون گردش"}};
        for (String[] f : filters) {
            Button b = activeFilter.equals(f[0]) ? primaryButton(f[1]) : secondaryButton(f[1]);
            b.setTextSize(fs(10.5f));
            b.setOnClickListener(v -> loadProducts(query, f[0]));
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(0, dp(42), 1f);
            lp.setMargins(dp(3), 0, dp(3), dp(12));
            box.addView(b, lp);
        }
        content.addView(box, new LinearLayout.LayoutParams(-1, -2));
    }

    private String sqlNumberExpr(String alias, String col, String type) {
        if (col == null || col.trim().isEmpty()) return "CAST(NULL AS " + type + ")";
        String ref = (alias == null || alias.trim().isEmpty() ? "" : alias + ".") + "[" + col + "]";
        String raw = "TRY_CONVERT(nvarchar(120)," + ref + ")";
        String norm = "LTRIM(RTRIM(" + raw + "))";
        String[][] repl = {
                {"NCHAR(160)", "N''"}, {"N' '", "N''"}, {"N','", "N''"}, {"N'،'", "N''"}, {"N'٬'", "N''"},
                {"N'٫'", "N'.'"}, {"N'ریال'", "N''"}, {"N'تومان'", "N''"},
                {"N'۰'", "N'0'"}, {"N'۱'", "N'1'"}, {"N'۲'", "N'2'"}, {"N'۳'", "N'3'"}, {"N'۴'", "N'4'"},
                {"N'۵'", "N'5'"}, {"N'۶'", "N'6'"}, {"N'۷'", "N'7'"}, {"N'۸'", "N'8'"}, {"N'۹'", "N'9'"},
                {"N'٠'", "N'0'"}, {"N'١'", "N'1'"}, {"N'٢'", "N'2'"}, {"N'٣'", "N'3'"}, {"N'٤'", "N'4'"},
                {"N'٥'", "N'5'"}, {"N'٦'", "N'6'"}, {"N'٧'", "N'7'"}, {"N'٨'", "N'8'"}, {"N'٩'", "N'9'"}
        };
        for (String[] r : repl) norm = "REPLACE(" + norm + "," + r[0] + "," + r[1] + ")";
        return "COALESCE(TRY_CONVERT(" + type + "," + ref + "),TRY_CONVERT(" + type + "," + norm + "))";
    }

    private String factorLatestOrder(Set<String> cols, String alias) {
        String prefix = alias == null || alias.trim().isEmpty() ? "" : alias + ".";
        List<String> parts = new ArrayList<>();
        String active = resolveFlexible(cols, "active", "Active", "is_active", "enabled", "Enable", "is_current", "Current", "selected", "Valid", "valid");
        if (active != null) {
            String f = prefix + "[" + active + "]";
            parts.add("CASE WHEN UPPER(LTRIM(RTRIM(TRY_CONVERT(nvarchar(20)," + f + ")))) IN (N'T',N'TRUE',N'Y',N'YES',N'1',N'فعال') OR TRY_CONVERT(int," + f + ")=1 THEN 1 ELSE 0 END DESC");
        }
        for (String candidate : new String[]{"updated_at","UpdateDate","update_date","modified_at","ModifyDate","modify_date","edit_date","EditDate","last_update","LastUpdate","created_at","CreateDate","create_date","tarikh_sabt","date","DATE","t_date"}) {
            String col = resolveFlexible(cols, candidate);
            if (col != null) parts.add("TRY_CONVERT(datetime2," + prefix + "[" + col + "]) DESC");
        }
        for (String candidate : new String[]{"rdf","RDF","id","ID","serial","Serial","row_id","RowID","autoid","AutoID","radif","Radif"}) {
            String col = resolveFlexible(cols, candidate);
            if (col != null) parts.add("TRY_CONVERT(bigint," + prefix + "[" + col + "]) DESC");
        }
        parts.add("(SELECT 0)");
        return join(parts, ",");
    }

    private String dedupeFactorSource(String table, Set<String> cols, String numberCol, String alias, String innerWhere) {
        String a = alias == null || alias.trim().isEmpty() ? "h" : alias.trim();
        String where = innerWhere == null || innerWhere.trim().isEmpty() ? "" : innerWhere.trim();
        if (numberCol == null || numberCol.trim().isEmpty()) return "dbo.[" + table + "] " + a + (where.isEmpty() ? "" : " " + where.replace("x.", a + "."));
        String numberExpr = "NULLIF(LTRIM(RTRIM(TRY_CONVERT(nvarchar(120),x.[" + numberCol + "]))),N'')";
        String rowExpr = factorUniqueRowExpr(cols, "x");
        String partition = "COALESCE(" + numberExpr + "," + rowExpr + ")";
        return "(SELECT * FROM (SELECT x.*, ROW_NUMBER() OVER(PARTITION BY " + partition + " ORDER BY " + factorLatestOrder(cols, "x") + ") AS _meelano_rn FROM dbo.[" + table + "] x " + where + ") mx WHERE mx._meelano_rn=1) " + a;
    }

    private String factorUniqueRowExpr(Set<String> cols, String alias) {
        String prefix = alias == null || alias.trim().isEmpty() ? "" : alias + ".";
        for (String candidate : new String[]{"rdf", "RDF", "id", "ID", "serial", "Serial", "row_id", "RowID", "autoid", "AutoID", "radif", "Radif"}) {
            String col = resolveFlexible(cols, candidate);
            if (col != null) return "N'__row__' + COALESCE(TRY_CONVERT(nvarchar(120)," + prefix + "[" + col + "]),CONVERT(nvarchar(36),NEWID()))";
        }
        return "N'__row__' + CONVERT(nvarchar(36),NEWID())";
    }

    private String falseLikeCondition(String field) {
        String norm = "UPPER(LTRIM(RTRIM(TRY_CONVERT(nvarchar(40)," + field + "))))";
        return "(" + norm + " IS NULL OR " + norm + " IN (N'',N'0',N'F',N'FALSE',N'N',N'NO',N'خیر',N'خير',N'نه') OR TRY_CONVERT(int," + field + ")=0)";
    }

    private String softDeleteCondition(Set<String> cols, String alias) {
        String prefix = alias == null || alias.trim().isEmpty() ? "" : alias + ".";
        List<String> parts = new ArrayList<>();
        String del = resolveFlexible(cols, "deleted", "Deleted", "is_deleted", "IsDeleted", "isDelete", "delete_flag", "deleted_flag", "حذف", "حذف_شده");
        if (del != null) parts.add(falseLikeCondition(prefix + "[" + del + "]"));
        String cancel = resolveFlexible(cols, "cancel", "Cancel", "canceled", "cancelled", "is_cancel", "is_canceled", "void", "Void", "باطل", "ابطال");
        if (cancel != null) parts.add(falseLikeCondition(prefix + "[" + cancel + "]"));
        String status = resolveFlexible(cols, "status", "Status", "satus", "Satus", "state", "State");
        if (status != null) {
            String norm = "UPPER(LTRIM(RTRIM(TRY_CONVERT(nvarchar(50)," + prefix + "[" + status + "]))))";
            parts.add("(" + norm + " IS NULL OR " + norm + "=N'' OR " + norm + " NOT IN (N'DELETED',N'DELETE',N'CANCEL',N'CANCELLED',N'VOID',N'باطل',N'حذف',N'حذف شده',N'لغو',N'لغوشده'))");
        }
        return parts.isEmpty() ? "" : "(" + join(parts, " AND ") + ")";
    }

    private boolean isBinaryColumn(Map<String, String> types, String col) {
        if (types == null || col == null) return false;
        String type = types.get(col.toLowerCase(Locale.US));
        if (type == null) return false;
        return type.contains("binary") || "image".equals(type) || type.contains("varbinary");
    }

