    private String productLocalKey(JSONObject r) {
        String code = safeDisplayText(r == null ? null : r.opt("کد"), "").trim();
        if (code.isEmpty()) code = safeDisplayText(r == null ? null : r.opt("نام"), "کالا").trim();
        return normalizeDigits(code).replaceAll("[^0-9A-Za-zآ-یا-ی]+", "_");
    }

    private String productImageOverrideKey(JSONObject r) {
        return "visitor_product_image_" + productLocalKey(r);
    }

    private Bitmap visitorProductImageOverrideBitmap(JSONObject r) {
        try {
            if (prefs == null || r == null) return null;
            String key = productImageOverrideKey(r);
            String cacheKey = "local_image|" + key;
            Bitmap cached = productBitmapCache.get(cacheKey);
            if (cached != null && !cached.isRecycled()) return cached;
            String b64 = prefs.getString(key, "");
            if (b64 == null || b64.trim().isEmpty()) return null;
            byte[] bytes = Base64.decode(b64, Base64.DEFAULT);
            Bitmap bmp = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
            if (bmp != null) productBitmapCache.put(cacheKey, bmp);
            return bmp;
        } catch (Exception ignored) { return null; }
    }

    private void pickVisitorProductImage(JSONObject product) {
        if (product == null) return;
        pendingProductImageKey = productImageOverrideKey(product);
        pendingProductImageName = safeDisplayText(product.opt("نام"), "کالا");
        Intent i = new Intent(Intent.ACTION_GET_CONTENT);
        i.setType("image/*");
        i.addCategory(Intent.CATEGORY_OPENABLE);
        try { startActivityForResult(Intent.createChooser(i, "انتخاب تصویر کالا - مربع ۵۱۲×۵۱۲ پیشنهاد می‌شود"), REQ_PRODUCT_IMAGE); }
        catch (Exception ex) { showNotice("انتخاب تصویر در این دستگاه در دسترس نیست.", false); }
    }

    private static int sampleSizeFor(int width, int height, int targetMinSide) {
        int sample = 1;
        if (width <= 0 || height <= 0 || targetMinSide <= 0) return 1;
        while (Math.min(width, height) / (sample * 2) >= targetMinSide) sample *= 2;
        return sample;
    }

    /** Decodes an encoded image at no more than ~2x the requested short side. */
    private Bitmap decodeSampled(byte[] bytes, int targetMinSide) {
        if (bytes == null || bytes.length == 0) return null;
        BitmapFactory.Options bounds = new BitmapFactory.Options();
        bounds.inJustDecodeBounds = true;
        BitmapFactory.decodeByteArray(bytes, 0, bytes.length, bounds);
        BitmapFactory.Options opts = new BitmapFactory.Options();
        opts.inSampleSize = sampleSizeFor(bounds.outWidth, bounds.outHeight, targetMinSide);
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.length, opts);
    }

    private int exifRotationDegrees(Uri uri) {
        try (InputStream in = getContentResolver().openInputStream(uri)) {
            if (in == null) return 0;
            int o = new android.media.ExifInterface(in).getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION, android.media.ExifInterface.ORIENTATION_NORMAL);
            if (o == android.media.ExifInterface.ORIENTATION_ROTATE_90) return 90;
            if (o == android.media.ExifInterface.ORIENTATION_ROTATE_180) return 180;
            if (o == android.media.ExifInterface.ORIENTATION_ROTATE_270) return 270;
        } catch (Exception ignored) { }
        return 0;
    }

    /** Off the UI thread: sampled decode (no full-resolution bitmap), EXIF rotation, 512×512 JPEG. */
    private String encodeProductPhoto512(Uri uri) throws Exception {
        BitmapFactory.Options bounds = new BitmapFactory.Options();
        bounds.inJustDecodeBounds = true;
        try (InputStream in = getContentResolver().openInputStream(uri)) { BitmapFactory.decodeStream(in, null, bounds); }
        BitmapFactory.Options opts = new BitmapFactory.Options();
        opts.inSampleSize = sampleSizeFor(bounds.outWidth, bounds.outHeight, 512);
        Bitmap src;
        try (InputStream in = getContentResolver().openInputStream(uri)) { src = BitmapFactory.decodeStream(in, null, opts); }
        if (src == null) return null;
        int side = Math.min(src.getWidth(), src.getHeight());
        android.graphics.Matrix m = new android.graphics.Matrix();
        float scale = 512f / Math.max(1, side);
        m.postScale(scale, scale);
        int rotation = exifRotationDegrees(uri);
        if (rotation != 0) m.postRotate(rotation);
        Bitmap out = Bitmap.createBitmap(src, Math.max(0, (src.getWidth() - side) / 2), Math.max(0, (src.getHeight() - side) / 2), side, side, m, true);
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        out.compress(Bitmap.CompressFormat.JPEG, 86, bytes);
        if (out != src) out.recycle();
        src.recycle();
        return Base64.encodeToString(bytes.toByteArray(), Base64.NO_WRAP);
    }

    private void handleVisitorProductImage(Uri uri) {
        if (uri == null || pendingProductImageKey == null || pendingProductImageKey.trim().isEmpty()) return;
        final String key = pendingProductImageKey;
        final String name = pendingProductImageName;
        showNotice("در حال آماده‌سازی تصویر کالا…", false);
        preloadExecutor.execute(() -> {
            String encoded = null;
            Exception failure = null;
            try { encoded = encodeProductPhoto512(uri); } catch (Exception | OutOfMemoryError ex) { failure = ex instanceof Exception ? (Exception) ex : new Exception("حافظه کافی نبود"); }
            final String result = encoded;
            final Exception error = failure;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                if (result == null) { showNotice(error == null ? "تصویر خوانده نشد." : "ذخیره تصویر ممکن نشد: " + shortError(error), true); return; }
                if (prefs != null) prefs.edit().putString(key, result).apply();
                productBitmapCache.evictAll();
                showNotice("تصویر کالا با ابعاد ۵۱۲×۵۱۲ ذخیره شد: " + stringOr(name, "کالا"), true);
                if ("showcase".equals(activePage)) rerenderShowcaseFast(showcaseCacheQuery, showcaseCacheFilter);
                else if ("cart".equals(activePage)) renderCartPage();
            });
        });
        pendingProductImageKey = ""; pendingProductImageName = "";
    }

    // ------------------------------------------------------------------
    // Bundled product photos: assets/products/<key>.jpg (512x512), chosen by product name.
    // Priority in applyProductImage: visitor's own photo > photo from Atiran > bundled photo > drawn picture.
    // To add a photo: put <key>.jpg in assets/products and add its keywords in productPhotoKeyFor().
    // ------------------------------------------------------------------
    private final Set<String> missingProductPhotos = java.util.Collections.synchronizedSet(new HashSet<String>());

    private String productPhotoKey(JSONObject r) {
        if (r == null) return null;
        String forced = prefs == null ? "" : prefs.getString(productVisualOverrideKey(r), "");
        if (forced != null && !forced.trim().isEmpty()) return productPhotoKeyForType(forced.trim());
        String key = productPhotoKeyFor(r.optString("نام", ""));
        if (key == null) key = productPhotoKeyFor(r.optString("گروه", ""));
        return key;
    }

    private String productPhotoKeyForType(String type) { return MeelanoProductPhotos.keyForType(type); }

    private String productPhotoKeyFor(String text) { return MeelanoProductPhotos.keyFor(text); }

    private Bitmap bundledProductPhoto(JSONObject r) {
        String key = productPhotoKey(r);
        if (key == null || missingProductPhotos.contains(key)) return null;
        String cacheKey = "asset_photo|" + key;
        Bitmap cached = productBitmapCache.get(cacheKey);
        if (cached != null && !cached.isRecycled()) return cached;
        try (InputStream in = getAssets().open("products/" + key + ".jpg")) {
            Bitmap bmp = BitmapFactory.decodeStream(in);
            if (bmp != null) { productBitmapCache.put(cacheKey, bmp); return bmp; }
        } catch (Exception | OutOfMemoryError ignored) { }
        missingProductPhotos.add(key);
        return null;
    }

    private boolean hasProductImage(JSONObject r) {
        if (visitorProductImageOverrideBitmap(r) != null) return true;
        String raw = r == null ? "" : r.optString("تصویر", "");
        if (raw == null) return false;
        raw = raw.trim();
        if (raw.isEmpty() || "null".equalsIgnoreCase(raw)) return false;
        if (looksLikeExternalImageReference(raw)) return false;
        return raw.length() > 80 || raw.startsWith("data:image") || raw.startsWith("0x");
    }

    private boolean looksLikeExternalImageReference(String raw) {
        if (raw == null) return false;
        String v = raw.trim().toLowerCase(Locale.US);
        return v.startsWith("http://") || v.startsWith("https://") || v.startsWith("file:") || v.startsWith("content:") || v.contains("\\") || v.endsWith(".jpg") || v.endsWith(".jpeg") || v.endsWith(".png") || v.endsWith(".webp") || v.endsWith(".gif") || (v.contains("/") && v.length() < 160);
    }

    private void applyProductImage(ImageView img, JSONObject r) { applyProductImage(img, r, true); }

    private void applyProductImage(ImageView img, JSONObject r, boolean decodeRealImage) {
        if (img == null) return;
        Bitmap local = visitorProductImageOverrideBitmap(r);
        if (local != null) { img.clearColorFilter(); img.setImageBitmap(local); return; }
        Bitmap smart = bundledProductPhoto(r);
        if (smart == null) smart = smartProductBitmap(r);
        if (smart != null) { img.clearColorFilter(); img.setImageBitmap(smart); } else { img.setImageResource(R.drawable.mi_inventory_2); img.setColorFilter(alpha(MUTED, 200)); }
        if (!decodeRealImage || !hasProductImage(r)) return;
        String raw = r.optString("تصویر", "").trim();
        String cacheKey = "db_image|" + r.optString("کد", "") + "|" + raw.length() + "|" + raw.hashCode();
        Bitmap cachedImage = productBitmapCache.get(cacheKey);
        if (cachedImage != null && !cachedImage.isRecycled()) { img.clearColorFilter(); img.setImageBitmap(cachedImage); return; }
        int comma = raw.indexOf(',');
        if (raw.startsWith("data:image") && comma > 0) raw = raw.substring(comma + 1);
        try {
            byte[] bytes;
            String clean = raw.replace(" ", "").replace("\n", "").replace("\r", "").trim();
            if (clean.startsWith("0x") && clean.length() > 10) bytes = hexToBytes(clean.substring(2));
            else bytes = Base64.decode(clean, Base64.DEFAULT);
            // Product cards show the image at <= ~140dp; decode small instead of full resolution.
            Bitmap bmp = decodeSampled(bytes, dp(160));
            if (bmp != null) { productBitmapCache.put(cacheKey, bmp); img.clearColorFilter(); img.setImageBitmap(bmp); }
        } catch (Exception | OutOfMemoryError ignored) { }
    }

    private byte[] hexToBytes(String hex) {
        if (hex == null) return new byte[0];
        String h = hex.trim();
        if (h.length() % 2 == 1) h = "0" + h;
        byte[] out = new byte[h.length() / 2];
        for (int i = 0; i < out.length; i++) {
            int pos = i * 2;
            try { out[i] = (byte) Integer.parseInt(h.substring(pos, pos + 2), 16); }
            catch (Exception ignored) { out[i] = 0; }
        }
        return out;
    }

    private Bitmap smartProductBitmap(JSONObject r) {
        try {
            int w = 360, h = 360;
            String name = r == null ? "کالا" : stringOr(r.optString("نام", ""), "کالا");
            String group = r == null ? "" : r.optString("گروه", "");
            ProductVisualProfile vp = productVisualProfile(r);
            String cacheKey = currentThemeId() + "|premium|" + vp.type + "|" + shortProductTitle(name, 42) + "|" + shortProductTitle(group, 28);
            Bitmap cached = productBitmapCache.get(cacheKey);
            if (cached != null && !cached.isRecycled()) return cached;

            Bitmap bmp = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
            Canvas canvas = new Canvas(bmp);
            Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
            int accent = vp.accent;
            int deep = mix(SURFACE, accent, isLightTheme() ? 0.10f : 0.30f);
            int glow = mix(accent, Color.WHITE, isLightTheme() ? 0.58f : 0.32f);
            int warm = mix(GOLD_2, accent, 0.24f);

            RectF full = new RectF(0, 0, w, h);
            p.setStyle(Paint.Style.FILL);
            p.setShader(new LinearGradient(0, 0, w, h,
                    new int[]{mix(Color.WHITE, glow, isLightTheme() ? 0.18f : 0.08f), alpha(warm, 255), deep},
                    new float[]{0f, .45f, 1f}, Shader.TileMode.CLAMP));
            canvas.drawRoundRect(full, 38f, 38f, p);
            p.setShader(null);

            p.setShader(new RadialGradient(292, 62, 144, alpha(Color.WHITE, isLightTheme() ? 220 : 105), alpha(accent, 0), Shader.TileMode.CLAMP));
            canvas.drawCircle(292, 62, 144, p);
            p.setShader(null);
            p.setColor(alpha(GOLD_2, isLightTheme() ? 60 : 46)); canvas.drawCircle(58, 306, 108, p);
            p.setColor(alpha(Color.WHITE, isLightTheme() ? 168 : 34)); canvas.drawRoundRect(new RectF(18, 18, 342, 342), 34f, 34f, p);
            p.setColor(alpha(Color.BLACK, isLightTheme() ? 20 : 92)); canvas.drawRoundRect(new RectF(37, 248, 323, 314), 34f, 34f, p);
            p.setColor(alpha(Color.WHITE, isLightTheme() ? 110 : 22)); canvas.drawRoundRect(new RectF(42, 236, 318, 290), 26f, 26f, p);

            Path shine = new Path();
            shine.moveTo(42, 44); shine.lineTo(318, 30); shine.lineTo(274, 86); shine.lineTo(78, 101); shine.close();
            p.setColor(alpha(Color.WHITE, isLightTheme() ? 92 : 38)); canvas.drawPath(shine, p);

            drawProductIllustration(canvas, p, vp, name, group);
            drawProductSparkles(canvas, p, accent);

            RectF label = new RectF(28, 288, 332, 348);
            p.setShader(new LinearGradient(28, 288, 332, 348,
                    new int[]{alpha(Color.WHITE, isLightTheme() ? 230 : 64), alpha(mix(SURFACE, accent, .18f), isLightTheme() ? 236 : 214)},
                    null, Shader.TileMode.CLAMP));
            canvas.drawRoundRect(label, 24f, 24f, p);
            p.setShader(null);
            p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(2.1f); p.setColor(alpha(accent, isLightTheme() ? 128 : 118)); canvas.drawRoundRect(label, 24f, 24f, p);
            p.setStyle(Paint.Style.FILL);
            p.setTextAlign(Paint.Align.CENTER); p.setTypeface(MEELANO_BOLD);
            p.setTextSize(shortProductTitle(name, 24).length() > 17 ? 18f : 20.5f); p.setColor(TEXT); canvas.drawText(shortProductTitle(name, 24), w / 2f, 316f, p);
            p.setTextSize(13.5f); p.setColor(alpha(MUTED, 235)); canvas.drawText(vp.title, w / 2f, 338f, p);

            p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(3.2f); p.setColor(alpha(mix(accent, GOLD_2, .24f), isLightTheme() ? 160 : 190));
            canvas.drawRoundRect(new RectF(8, 8, w - 8, h - 8), 36f, 36f, p);
            p.setStrokeWidth(1.15f); p.setColor(alpha(Color.WHITE, isLightTheme() ? 176 : 72));
            canvas.drawRoundRect(new RectF(15, 15, w - 15, h - 15), 31f, 31f, p);
            p.setStyle(Paint.Style.FILL);
            productBitmapCache.put(cacheKey, bmp);
            return bmp;
        } catch (Exception ignored) { return null; }
    }

    private void drawProductSparkles(Canvas c, Paint p, int accent) {
        p.setStyle(Paint.Style.FILL);
        int[] xs = {54, 86, 286, 314, 248};
        int[] ys = {72, 228, 42, 212, 92};
        for (int i = 0; i < xs.length; i++) {
            float r = i % 2 == 0 ? 4.2f : 3.0f;
            p.setColor(alpha(i == 2 ? GOLD_2 : mix(accent, Color.WHITE, .36f), i == 3 ? 130 : 185));
            c.drawCircle(xs[i], ys[i], r, p);
            p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(1.4f); p.setColor(alpha(Color.WHITE, 110));
            c.drawLine(xs[i] - r * 2.2f, ys[i], xs[i] + r * 2.2f, ys[i], p);
            c.drawLine(xs[i], ys[i] - r * 2.2f, xs[i], ys[i] + r * 2.2f, p);
            p.setStyle(Paint.Style.FILL);
        }
    }

    private ProductVisualProfile productVisualProfile(JSONObject r) {
        if (r == null) return productVisualProfile("", "");
        String key = productVisualOverrideKey(r);
        String forced = prefs == null ? "" : prefs.getString(key, "");
        if (forced != null && !forced.trim().isEmpty()) return productVisualProfileForType(forced.trim());
        return productVisualProfile(r.optString("نام", ""), r.optString("گروه", ""));
    }

    private String productVisualOverrideKey(JSONObject r) {
        String code = r == null ? "" : r.optString("کد", "").trim();
        if (code.isEmpty()) code = r == null ? "" : r.optString("نام", "").trim();
        return "product_visual_override_" + normalizeDigits(code).replace(" ", "_");
    }

    /** Product type is decided by the NAME first; the group is only a fallback (e.g. «ماکارونی» in group «خشکبار و حبوبات»). */
    private ProductVisualProfile productVisualProfile(String name, String group) {
        ProductVisualProfile byName = productVisualProfileMatch(productKeyText(name == null ? "" : name));
        if (byName != null) return byName;
        ProductVisualProfile byGroup = productVisualProfileMatch(productKeyText(group == null ? "" : group));
        if (byGroup != null) return byGroup;
        return visual("generic_box", "کالای عمومی", "کالا", Color.rgb(126, 87, 255), isLightTheme() ? 14 : 22);
    }

