    private void runConnectionDiagnostics() {
        runDb(() -> {
            long t0 = System.currentTimeMillis();
            StringBuilder out = new StringBuilder();
            out.append("✓ تنظیمات اتصال امن Meelano آماده است\n");
            try (Connection c = openConnection()) {
                long connected = System.currentTimeMillis();
                out.append("✓ ورود امن موفق • ").append(connected - t0).append("ms\n");
                try (PreparedStatement ps = c.prepareStatement("SELECT DB_NAME(), @@VERSION")) {
                    try (ResultSet r = ps.executeQuery()) {
                        if (r.next()) {
                            out.append("✓ اجرای Query موفق • پایگاه: ").append(stringOr(r.getString(1), "—")).append("\n");
                            out.append("✓ نسخه سرور دریافت شد؛ جزئیات حساس نمایش داده نمی‌شود\n");
                        }
                    }
                }
                out.append("✓ نتیجه: اتصال سالم است؛ اگر داده‌ها خالی‌اند، دسترسی جدول/فیلتر تاریخ را بررسی کنید.");
            }
            return out.toString();
        }, new DbCallback() {
            @Override public void ok(String body) { new MeelanoDialogBuilder().setTitle("عیب‌یابی اتصال").setMessage(body).setPositiveButton("باشه", null).show(); if ("health".equals(activePage)) renderConnectionHealthPage(); }
            @Override public void fail(Exception e) { new MeelanoDialogBuilder().setTitle("عیب‌یابی اتصال").setMessage("اتصال کامل نشد:\n" + readableError(e) + "\n\nجزئیات حساس اتصال نمایش داده نمی‌شود.").setPositiveButton("باشه", null).show(); if ("health".equals(activePage)) renderConnectionHealthPage(); }
        });
    }

    private void testConnectionHealth() {
        runDb(() -> { try (Connection c = openConnection(); PreparedStatement ps = c.prepareStatement("SELECT 1")) { try (ResultSet r = ps.executeQuery()) { return r.next() ? "ok" : "empty"; } } }, new DbCallback() {
            @Override public void ok(String body) { showNotice("اتصال سالم است.", false); if ("health".equals(activePage)) renderConnectionHealthPage(); else renderSettings(); }
            @Override public void fail(Exception e) { showNotice(readableError(e), false); if ("health".equals(activePage)) renderConnectionHealthPage(); else renderSettings(); }
        });
    }

